window.BASAIR_QUESTIONS=(window.BASAIR_QUESTIONS||[]).concat([{"id":"s6-157","number":157,"surah":6,"verses":[25],"references":[{"surah":6,"verses":[25]}],"verseLabel":"الأنعام: 25","question":"ما دلالة اختيار لفظ ﴿أساطير﴾ في طعنهم بالقرآن؟","answer":"الأساطير جمع أسطورة، وهي الأحاديث والأباطيل التي لا نظام لها في زعمهم؛ فاختاروا اللفظ لاتهام القرآن بأنه منقول مختلق لا وحي منزل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص434، تحت عنوان «شرح المفردات»","url":""}]},{"id":"s6-158","number":158,"surah":6,"verses":[26],"references":[{"surah":6,"verses":[26]}],"verseLabel":"الأنعام: 26","question":"ما دلالة الجمع بين الفعلين المتقاربين جرسًا: ﴿ينهون عنه وينأون عنه﴾؟","answer":"جمعوا بين إضلال غيرهم وابتعادهم بأنفسهم: ينهون الناس عن اتباع الحق، وينأون هم عنه. والتقارب الصوتي بين الفعلين يرسخ تقابل الحركتين، ويكشف أن شرهم لم يقف عند ضلالهم بل تعداه إلى إضلال الآخرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص454–455، تحت «بلاغة الجناس في قوله تعالى: ﴿وهم ينهون عنه وينأون عنه﴾»","url":""}]},{"id":"s6-159","number":159,"surah":6,"verses":[26],"references":[{"surah":6,"verses":[26]}],"verseLabel":"الأنعام: 26","question":"ما دلالة حذف متعلق النهي والنأي في قوله تعالى: ﴿ينهون عنه وينأون عنه﴾؟","answer":"أطلق المتعلق اعتمادًا على السياق، فيشمل صدهم عن القرآن والرسول ﷺ وابتعادهم عنهما؛ فجمعوا إضلال غيرهم وضلال أنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص454، تحت عنوان «عدم ذكر متعلق النهي والنأي في قوله تعالى: ﴿ينهون عنه وينأون عنه﴾»","url":""}]},{"id":"s6-160","number":160,"surah":6,"verses":[26],"references":[{"surah":6,"verses":[26]}],"verseLabel":"الأنعام: 26","question":"لم لم يحدد قوله تعالى: ﴿وهم ينهون عنه وينأون عنه﴾ الأشخاص الذين يصدونهم عن الحق؟","answer":"حذف المفعول لإفادة العموم؛ فكانوا يريدون صد كل الناس عن سماع القرآن والإيمان بالنبي ﷺ. وجاء ذلك بإيجاز يصور اتساع سعيهم في المنع، مع ابتعادهم هم عن الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص454، تحت «دلالة حذف مفعول الفعلين في قوله: ﴿وهم ينهون عنه وينأون عنه﴾»","url":""}]},{"id":"s6-161","number":161,"surah":6,"verses":[26],"references":[{"surah":6,"verses":[26]}],"verseLabel":"الأنعام: 26","question":"ما دلالة تقديم نهيهم الناس على نأيهم بأنفسهم؟","answer":"قُدم النهي لأن خطره متعدٍّ إلى غيرهم، فهو إضلال بعد الضلال، ولأنه امتداد مباشر لمجادلتهم وطعنهم السابق في القرآن. ثم ذُكر نأيهم ليكتمل وصف من يمنع الآخرين مما لم ينتفع به هو.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص455، تحت «سر التعبير بتقديم قوله: ﴿وهم ينهون عنه﴾ على قوله: ﴿وينأون عنه﴾»","url":""}]},{"id":"s6-162","number":162,"surah":6,"verses":[26],"references":[{"surah":6,"verses":[26]}],"verseLabel":"الأنعام: 26","question":"ما دلالة القصر في قوله تعالى: ﴿وإن يهلكون إلا أنفسهم﴾؟","answer":"حصر عاقبة صدهم في أنفسهم؛ فهم يظنون أنهم يطفئون نور الوحي ويضرون الرسول والمؤمنين، والحقيقة أنهم لا يسوقون إلى الهلاك إلا ذواتهم. فالقصر يقلب تقديرهم للنتيجة ويطمئن إلى أن الحق لا تضره مكائدهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص456، تحت «دلالة القصر في قوله تعالى: ﴿وإن يهلكون إلا أنفسهم﴾».","url":""}]},{"id":"s6-163","number":163,"surah":6,"verses":[26],"references":[{"surah":6,"verses":[26]}],"verseLabel":"الأنعام: 26","question":"ما المجاز العقلي في قوله تعالى: ﴿وإن يهلكون إلا أنفسهم﴾؟","answer":"أسند الهلاك إليهم لأنهم تسببوا فيه بكفرهم وصدهم، مع أن الله هو الذي يجازيهم به؛ فصورهم يهدمون أنفسهم بأفعالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص456، تحت عنوان «بلاغة المجاز العقلي في قوله: ﴿وإن يهلكون إلا أنفسهم﴾»","url":""}]},{"id":"s6-1079","number":1079,"surah":6,"verses":[26],"references":[{"surah":6,"verses":[26]}],"verseLabel":"الأنعام: 26","question":"ما الفرق بين الهلاك والموت؟","answer":"الموت مفارقة الحياة، أما الهلاك فأعم في الفساد والضياع وسوء المصير؛ لذلك ناسب خسارة النفس بالكفر والعذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص457–458، تحت عنوان «الهلاك والموت»","url":""}]},{"id":"s6-1080","number":1080,"surah":6,"verses":[26],"references":[{"surah":6,"verses":[26]}],"verseLabel":"الأنعام: 26","question":"ما سر التعبير بالجملة الفعلية في قوله: ﴿ينهون عنه وينأون عنه﴾؟","answer":"صورت الجملة تجدد فعلهم واستمرارهم في صد غيرهم وابتعادهم هم عن الوحي، فجمعوا الإضلال والضلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص455–456، تحت عنوان «سر التعبير بالجملة الفعلية بقوله تعالى: ﴿ينهون عنه وينأون عنه﴾»","url":""}]},{"id":"s6-165","number":165,"surah":6,"verses":[27],"references":[{"surah":6,"verses":[27]}],"verseLabel":"الأنعام: 27","question":"ما دلالة المضارع في قوله تعالى: ﴿ولو ترى﴾ مع أن الوقوف على النار مستقبل؟","answer":"استُعمل المضارع لاستحضار المشهد المستقبل كأنه يقع الآن أمام العين؛ فتحول العقيدة بالغيب إلى صورة حية يرى السامع حركتها ويسمع حسرتها. وهذا أبلغ في الإنذار من الإخبار المجرد عما سيقع.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص461، تحت «دلالة التعبير بصيغة المضارع في قوله: ﴿ولو ترى إذ وقفوا على النار﴾».","url":""}]},{"id":"s6-166","number":166,"surah":6,"verses":[27],"references":[{"surah":6,"verses":[27]}],"verseLabel":"الأنعام: 27","question":"ما دلالة المضارع في قوله تعالى: ﴿ولو ترى إذ وقفوا على النار﴾؟","answer":"يستحضر المضارع المشهد المستقبل حتى يبدو للسامع كأنه يراه الآن، فيقوى التخويف.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص461، تحت عنوان «دلالة التعبير بصيغة المضارع في قوله: ﴿ولو ترى إذ وقفوا على النار﴾»","url":""}]},{"id":"s6-1081","number":1081,"surah":6,"verses":[27],"references":[{"surah":6,"verses":[27]}],"verseLabel":"الأنعام: 27","question":"ما دلالة التعبير عن المستقبل بالماضي في قوله تعالى: ﴿إذ وقفوا على النار﴾؟","answer":"صور الوقوف واقعًا مكتملًا متحققًا داخل المشهد المستحضر، فحقق المستقبل وجعله بمنزلة المشاهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص461–462، تحت عنوان «دلالة التعبير عن المستقبل بالماضي في قوله: ﴿إذ وقفوا على النار﴾»","url":""}]},{"id":"s6-167","number":167,"surah":6,"verses":[27],"references":[{"surah":6,"verses":[27]}],"verseLabel":"الأنعام: 27","question":"ما دلالة بناء ﴿وُقفوا﴾ للمفعول؟","answer":"وجّه البناء للمفعول النظر إلى نفس الإيقاف وهوله، فهو المقصود الأعظم في المشهد، دون إشغال السياق بذكر من أوقفهم. وفي عرض حالهم بهذه الصورة توبيخ لهم وتعظيم لما يلاقونه يوم القيامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص462، تحت «دلالة بناء الفعل لما لم يسم فاعله في قوله: ﴿ولو ترى إذ وقفوا على النار﴾»","url":""}]},{"id":"s6-168","number":168,"surah":6,"verses":[27],"references":[{"surah":6,"verses":[27]}],"verseLabel":"الأنعام: 27","question":"ما دلالة قوله تعالى: ﴿وُقفوا على النار﴾، دون: عند النار أو أمامها؟","answer":"من وجوه التعبير بـ﴿على﴾ أنهم أُطلعوا على النار وعاينوا حقيقتها، كما يقال: وقفت على الأمر، أي عرفته واطلعت عليه. فالمشهد يتجاوز مجرد القرب من مكانها إلى مواجهتها وانكشاف ما أنكروه، ولا يلزم من هذا الوجه تحديد موضعهم على حافتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص462–463، تحت «الدلالة على الاستعارة التبعية التصريحية في قوله: ﴿إذ وقفوا على النار﴾»","url":""}]},{"id":"s6-169","number":169,"surah":6,"verses":[27],"references":[{"surah":6,"verses":[27]}],"verseLabel":"الأنعام: 27","question":"ما دلالة حذف جواب ﴿لو﴾ في قوله تعالى: ﴿ولو ترى إذ وُقفوا على النار﴾؟","answer":"حُذف الجواب لتهويل المشهد؛ أي لرأيت أمرًا عظيمًا لا يحيط به وصف، فتذهب نفس السامع في تصوره كل مذهب. وما تلا الشرط من تمنّيهم الرجعة يفتح جانبًا من ذلك الهول دون أن يحصره.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص460–461، تحت «حذف جواب ﴿ولو﴾ الشرطية»","url":""}]},{"id":"s6-170","number":170,"surah":6,"verses":[27],"references":[{"surah":6,"verses":[27]}],"verseLabel":"الأنعام: 27","question":"ما دلالة ﴿يا﴾ قبل التمني في قولهم: ﴿يا ليتنا نرد﴾؟","answer":"يجوز أن تكون ﴿يا﴾ للتنبيه، فتلفت إلى شدة أمنيتهم، وأن تكون للنداء مع حذف المنادى، كأنهم ينادون حسرتهم: يا حسرتنا أقبلي، فهذا أوانك. وفي الوجهين يظهر اضطرابهم وتحسرهم حين عاينوا العاقبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص463–464، تحت «دلالة التعبير بحرف النداء (يا) في قوله تعالى: ﴿فقالوا يا ليتنا نرد﴾»","url":""}]},{"id":"s6-171","number":171,"surah":6,"verses":[27],"references":[{"surah":6,"verses":[27]}],"verseLabel":"الأنعام: 27","question":"ما دلالة التعبير بـ﴿نُرد﴾، دون: نرجع؟","answer":"اختير ﴿نُرد﴾ لأن الرد إذا استعمل في الانتقال من حال إلى حال أفاد الإعادة إلى الحالة الأولى؛ فتمنوا أن يعادوا إلى دار التكليف ليستدركوا وجوه تقصيرهم بعد معاينة الأهوال.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص465–466، تحت «دلالة اختيار المشركين التعبير بالرد في هذا السياق»","url":""}]},{"id":"s6-172","number":172,"surah":6,"verses":[27],"references":[{"surah":6,"verses":[27]}],"verseLabel":"الأنعام: 27","question":"ما دلالة ذكر الربوبية في قولهم: ﴿ولا نكذب بآيات ربنا﴾؟","answer":"اختاروا لفظ الربوبية طلبًا للتعطف والتحنن عليهم؛ لكن هذا الاسترحام جاء بعد فوات أوان الانتفاع.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص466–467، تحت «دلالة اختيار لفظ الربوبية في قوله: ﴿ولا نكذب بآيات ربنا﴾»","url":""}]},{"id":"s6-173","number":173,"surah":6,"verses":[27],"references":[{"surah":6,"verses":[27]}],"verseLabel":"الأنعام: 27","question":"ما سر العدول من نفي الإشراك إلى قولهم: ﴿ونكون من المؤمنين﴾؟","answer":"انتقلوا من مجرد ترك الشرك إلى ادعاء الدخول في الإيمان، فصوروا أمنيتهم تحولًا كاملًا في الاعتقاد والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص467، تحت عنوان «سر العدول عن نفي الإشراك إلى الإيمان»","url":""}]},{"id":"s6-1082","number":1082,"surah":6,"verses":[27],"references":[{"surah":6,"verses":[27]}],"verseLabel":"الأنعام: 27","question":"لماذا قالوا: ﴿من المؤمنين﴾ دون «من الذين آمنوا»؟","answer":"الاسم يدل على ثبوت الصفة ورسوخها، فكأنهم يتمنون الانتماء الدائم إلى جماعة المؤمنين لا فعل إيمان عابرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص467، تحت عنوان «سر التعبير بـ﴿المؤمنين﴾ دون (الذين آمنوا)»","url":""}]},{"id":"s6-174","number":174,"surah":6,"verses":[28],"references":[{"surah":6,"verses":[28]}],"verseLabel":"الأنعام: 28","question":"ما دلالة الإضراب بقوله تعالى: ﴿بل بدا لهم ما كانوا يخفون من قبل﴾ بعد تمنّيهم الرجعة؟","answer":"أضرب عن ظاهر أمنيتهم ليكشف باعثها الحقيقي: لم ينشأ قولهم عن إيمان راسخ، وإنما عن انكشاف ما أخفوه ومعاينة العاقبة. ولذلك بيّن بعدها أنهم لو رُدوا لعادوا إلى ما نُهوا عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص472، تحت «أثر ﴿بل﴾ في البيان»","url":""}]},{"id":"s6-175","number":175,"surah":6,"verses":[28],"references":[{"surah":6,"verses":[28]}],"verseLabel":"الأنعام: 28","question":"ما دلالة التعبير بقوله تعالى: ﴿بدا لهم﴾؟","answer":"البُدو ظهور الشيء بعد خفائه مع انكشافه للناظر، فناسب ما كتموه في الدنيا ثم صار يوم القيامة حاضرًا لا يمكن ستره.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص472–473، تحت عنوان «بلاغة المجاز في قوله تعالى: ﴿بدا لهم﴾ ودلالة انتقاء الفعل ﴿بدا﴾»","url":""}]},{"id":"s6-176","number":176,"surah":6,"verses":[28],"references":[{"surah":6,"verses":[28]}],"verseLabel":"الأنعام: 28","question":"ما دلالة اسم الموصول ﴿ما﴾ في قوله تعالى: ﴿ما كانوا يخفون من قبل﴾؟","answer":"جاء الموصول واسعًا ليشمل ما أخفوه من القبائح ومعرفة الحق وما كتمته نفوسهم، وجامع ذلك انكشاف المستور يوم القيامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص473–474، تحت عنوان «سر استعمال اسم الموصول (ما) في قوله تعالى: ﴿ما كانوا يخفون﴾»","url":""}]},{"id":"s6-177","number":177,"surah":6,"verses":[28],"references":[{"surah":6,"verses":[28]}],"verseLabel":"الأنعام: 28","question":"ما المقابلة في قوله تعالى: ﴿بل بدا لهم ما كانوا يخفون من قبل﴾؟","answer":"قابل بين البدو والإخفاء، فصور انتقال ما كتموه في الدنيا إلى انكشاف لا يستطيعون دفعه في الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص475، تحت عنوان «بديع المقابلة بين ﴿بدا لهم﴾ وقوله تعالى: ﴿ما كانوا يخفون من قبل﴾»","url":""}]},{"id":"s6-1083","number":1083,"surah":6,"verses":[28],"references":[{"surah":6,"verses":[28]}],"verseLabel":"الأنعام: 28","question":"ما دلالة قطع الظرف ﴿قبل﴾ عن الإضافة؟","answer":"حذف المضاف إليه للعلم به، أي من قبل هذا الموقف في الدنيا، فركز اللفظ على تقابل زمن الكتمان وزمن الانكشاف.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص475–476، تحت عنوان «دلالة قطع الظرف ﴿قبل﴾»","url":""}]},{"id":"s6-178","number":178,"surah":6,"verses":[28],"references":[{"surah":6,"verses":[28]}],"verseLabel":"الأنعام: 28","question":"ما دلالة الشرط في قوله تعالى: ﴿ولو ردوا لعادوا لما نهوا عنه﴾؟","answer":"كشف الشرط أن تمنّيهم وليد العذاب لا تحول راسخ؛ فلو عادوا إلى الدنيا عادوا إلى ما تأصل فيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص476، تحت عنوان «دلالة أسلوب الشرط في تجلية المعنى، في قوله تعالى: ﴿ولو ردوا لعادوا لما نهوا عنه﴾»","url":""}]},{"id":"s6-1084","number":1084,"surah":6,"verses":[28],"references":[{"surah":6,"verses":[28]}],"verseLabel":"الأنعام: 28","question":"ما دلالة نوع النهي وماهية المنهي عنه في قوله: ﴿لعادوا لما نهوا عنه﴾؟","answer":"يشمل النهي ما زجروا عنه من الشرك والتكذيب والمعاصي، ويفيد أن عودهم سيكون إلى جنس المخالفات التي منعتهم منها الرسل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص478، تحت عنوان «دلالة نوع النهي ودرجته، وماهية المنهي عنه في السياق»","url":""}]},{"id":"s6-179","number":179,"surah":6,"verses":[28],"references":[{"surah":6,"verses":[28]}],"verseLabel":"الأنعام: 28","question":"ما دلالة اللام في قوله تعالى: ﴿لعادوا لما نهوا عنه﴾؟","answer":"أفادت اللام استغراقهم في العودة إلى ما نهوا عنه من الكفر والمعاصي وفنون القبائح، ودلت على رسوخ إصرارهم عليها؛ فالآية لا تخبر بزلة مفردة بل برجوعهم إلى النهج الذي عهد منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص477–478، تحت «دلالة اللام في قوله تعالى: ﴿لما نهوا عنه﴾»","url":""}]},{"id":"s6-180","number":180,"surah":6,"verses":[28],"references":[{"surah":6,"verses":[28]}],"verseLabel":"الأنعام: 28","question":"إلى ماذا يتعلق قوله تعالى: ﴿لكاذبون﴾؟","answer":"يتعلق بوعدهم ألا يكذبوا وبزعمهم أنهم سيكونون مؤمنين، فالله يكشف أن أمنيتهم لا تطابق حقيقة نفوسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص478، تحت عنوان «بيان متعلق قوله تعالى: ﴿لكاذبون﴾ في الآية الكريمة»","url":""}]},{"id":"s6-1085","number":1085,"surah":6,"verses":[28],"references":[{"surah":6,"verses":[28]}],"verseLabel":"الأنعام: 28","question":"ما أثر تعدد المؤكدات في قوله تعالى: ﴿وإنهم لكاذبون﴾؟","answer":"أكدت ﴿إن﴾ واللام والجملة الاسمية ثبوت الكذب فيهم، وقطعت احتمال صدق وعد ولدته رهبة الموقف.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص478–479، تحت عنوان «أثر تعدد المؤكدات في جلاء المعنى في قوله تعالى: ﴿وإنهم لكاذبون﴾»","url":""}]},{"id":"s6-181","number":181,"surah":6,"verses":[29],"references":[{"surah":6,"verses":[29]}],"verseLabel":"الأنعام: 29","question":"ما دلالة الضمير في قولهم: ﴿إن هي إلا حياتنا الدنيا﴾ مع عدم تقدم مرجع صريح؟","answer":"الضمير في ﴿إن هي﴾ مبهم، يفسره ما بعد الاستثناء المفرغ، وقُصد بإبهامه الإيجاز اعتمادًا على مفسره؛ فـ﴿حياتنا الدنيا﴾ بعد ﴿إلا﴾ في حكم البدل منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص485، تحت «دلالة الحصر بالنفي والاستثناء المفرغ في قوله تعالى: ﴿إن هي إلا حياتنا الدنيا﴾»","url":""}]},{"id":"s6-182","number":182,"surah":6,"verses":[29],"references":[{"surah":6,"verses":[29]},{"surah":45,"verses":[24]}],"verseLabel":"الأنعام: 29؛ الجاثية: 24","question":"ما دلالة الحصر في قولهم: ﴿إن هي إلا حياتنا الدنيا﴾؟","answer":"حصروا جنس الحياة في الدنيا ونفوا حياة بعدها، فكان القصر تعبيرًا عن إنكار البعث، ثم أكدوه بقولهم: ﴿وما نحن بمبعوثين﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص484–485، تحت عنوان «دلالة الحصر بالنفي والاستثناء المفرغ في قوله تعالى: ﴿إن هي إلا حياتنا الدنيا﴾»","url":""}]},{"id":"s6-183","number":183,"surah":6,"verses":[29],"references":[{"surah":6,"verses":[29]}],"verseLabel":"الأنعام: 29","question":"ما دلالة وصف الحياة بـ﴿الدنيا﴾ في حكاية قول من ينكر الآخرة؟","answer":"﴿الدنيا﴾ هي الحاضرة القريبة العاجلة، ووصف الحياة بها توكيد لقصرهم الحياة عليها ونفي حياة سواها؛ ونسبوها إليهم لأنها موطن متعتهم، وفي ذلك إنكار صريح للبعث.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص485–486، تحت «دلالة وصف الحياة بـ(الدنيا) في الآية الكريمة»","url":""}]},{"id":"s6-184","number":184,"surah":6,"verses":[29],"references":[{"surah":6,"verses":[29]}],"verseLabel":"الأنعام: 29","question":"ما دلالة الجملة الاسمية والباء في قولهم: ﴿وما نحن بمبعوثين﴾؟","answer":"الجملة الاسمية توحي بثبات النفي في اعتقادهم، ودخول الباء في خبرها يزيده توكيدًا؛ فلم يقولوا إن البعث مستبعد فحسب، بل رسخوا نفيه عن ذواتهم. وهذا التشديد يهيئ للمشهد الذي يضطرهم فيه الواقع إلى الإقرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص486، تحت «دلالة النفي مع تأكيده في قوله تعالى: ﴿وما نحن بمبعوثين﴾»","url":""}]},{"id":"s6-185","number":185,"surah":6,"verses":[29],"references":[{"surah":6,"verses":[29]}],"verseLabel":"الأنعام: 29","question":"ما الذي ينكره قولهم: ﴿وما نحن بمبعوثين﴾ باستعمال لفظ البعث؟","answer":"البعث هنا إخراج الخلق من قبورهم وإرسالهم إلى الموقف؛ فهم لا ينكرون مجرد استمرار الحياة، بل ينكرون أن يعادوا بعد الموت ويخرجوا من القبور. لذلك يواجه هذا اللفظ أصل اعتقادهم بأن الحياة تنتهي بالدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص487، تحت «(البعث) و(النشور)»","url":""}]},{"id":"s6-186","number":186,"surah":6,"verses":[30],"references":[{"surah":6,"verses":[30]}],"verseLabel":"الأنعام: 30","question":"ما سرّ تكرار مشهد ﴿ولو ترى إذ وُقفوا﴾ مع اختلاف المتعلّق: ﴿على النار﴾ و﴿على ربهم﴾؟","answer":"المشهد الأول يريهم عاقبة التكذيب ممثلة في النار فتنبعث أمنية الرجوع، والثاني ينقلهم إلى الوقوف للحساب أمام حكم ربهم فيُنتزع منهم الإقرار بالحق. فالتكرار ليس إعادة، بل تصعيد من معاينة الجزاء إلى مواجهة المالك الذي أنكرو لقاءه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص489–490، تحت «التناسب السياقي بين الآيتين المفتتحتين بقوله تعالى: ﴿ولو ترى إذ وقفوا﴾»","url":""}]},{"id":"s6-187","number":187,"surah":6,"verses":[30],"references":[{"surah":6,"verses":[30]}],"verseLabel":"الأنعام: 30","question":"ما الاستعارة التمثيلية في قوله تعالى: ﴿إذ وقفوا على ربهم﴾؟","answer":"مثلت حالهم حين عرضوا للحساب وعاينوا سلطان ربهم بحال من أوقف على أمر فبلغه وانكشف له، من غير دلالة على مكان.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص492–493، تحت عنوان «بيان الاستعارة التمثيلية في ﴿وقفوا على ربهم﴾»","url":""}]},{"id":"s6-188","number":188,"surah":6,"verses":[30],"references":[{"surah":6,"verses":[30]}],"verseLabel":"الأنعام: 30","question":"ما الغرض من الاستفهام في قوله تعالى: ﴿أليس هذا بالحق﴾؟","answer":"الاستفهام تقريري توبيخي، يُلزمهم الاعتراف بالبعث والعذاب اللذين أنكروهما بعد أن صارا معاينين؛ ولذلك لم يملكوا إلا أن يقولوا ﴿بلى﴾. فالسؤال ليس لطلب علم، بل لإقامة الحجة عليهم من إقرارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص494، تحت «الاستفهام التقريري وأثره في المعنى في قوله تعالى: ﴿أليس هذا بالحق﴾».","url":""}]},{"id":"s6-189","number":189,"surah":6,"verses":[30],"references":[{"surah":6,"verses":[30]}],"verseLabel":"الأنعام: 30","question":"إلى ماذا يشير ﴿هذا﴾ في قوله تعالى: ﴿أليس هذا بالحق﴾؟","answer":"يشير إلى البعث والحساب والعذاب الحاضر الذي يشاهدونه، وهو ما سبق أن أنكروه بقولهم ﴿وما نحن بمبعوثين﴾. والإشارة للقريب تجعل الحقيقة التي جحدوها كأنها موضوعة أمام أعينهم لا سبيل إلى إنكارها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص494–495، تحت «بيان المشار إليه بـ(هذا) في قوله تعالى: ﴿أليس هذا بالحق﴾»","url":""}]},{"id":"s6-190","number":190,"surah":6,"verses":[30],"references":[{"surah":6,"verses":[30]}],"verseLabel":"الأنعام: 30","question":"ما دلالة الباء في قوله تعالى: ﴿أليس هذا بالحق﴾؟","answer":"الباء زائدة في خبر ﴿ليس﴾ لتوكيد اتصاف المشار إليه بالحق؛ أي أليس هذا حقًا ثابتًا لا شك فيه؟ فجاءت تقوية الإثبات في مقابلة قوة إنكارهم السابق للبعث.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص495، تحت «دلالة الباء الزائدة في سياق الاستفهام المنفي، في قوله تعالى: ﴿أليس هذا بالحق﴾»","url":""}]},{"id":"s6-191","number":191,"surah":6,"verses":[30],"references":[{"surah":6,"verses":[30]}],"verseLabel":"الأنعام: 30","question":"ما دلالة جوابهم بـ﴿بلى﴾، دون: نعم؟","answer":"﴿بلى﴾ موضوعة لإبطال النفي السابق؛ فلما قيل ﴿أليس هذا بالحق﴾ أجابوا بما يرفع النفي ويثبت أنه الحق. أما ﴿نعم﴾ في أصل الاستعمال فتصدق مضمون السؤال المنفي، وقد توهم استمرار النفي.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص494، تحت «الاستفهام التقريري وأثره في المعنى، في قوله تعالى: ﴿أليس هذا بالحق﴾»","url":""}]},{"id":"s6-192","number":192,"surah":6,"verses":[30],"references":[{"surah":6,"verses":[30]}],"verseLabel":"الأنعام: 30","question":"ما دلالة إيراد القسم في قولهم: ﴿بلى وربنا﴾؟","answer":"أكدوا بالقسم ما صار معلومًا لهم بالمشاهدة؛ فانقلبوا من إنكار البعث إلى إقرار مؤكد به حين لم يعد الإنكار ممكنًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص495–496، تحت عنوان «إيراد القسم لتأكيد لازم فائدة الخبر، في قوله تعالى: ﴿بلى وربنا﴾»","url":""}]},{"id":"s6-1086","number":1086,"surah":6,"verses":[30],"references":[{"surah":6,"verses":[30]}],"verseLabel":"الأنعام: 30","question":"ما سر استعمال مادة الربوبية في قسمهم: ﴿بلى وربنا﴾؟","answer":"استحضرت الربوبية سلطان من خلقهم وبعثهم وأوقفهم للحساب، فجاء إقرارهم بربه لهم شاهدًا على بطلان إنكارهم السابق.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص495–496، تحت عنوان «سر استعمال مادة الربوبية في القسم، في قوله تعالى: ﴿قالوا بلى وربنا﴾»","url":""}]},{"id":"s6-193","number":193,"surah":6,"verses":[30],"references":[{"surah":6,"verses":[30]}],"verseLabel":"الأنعام: 30","question":"ما دلالة فاء التفريع في قوله تعالى: ﴿قال فذوقوا العذاب﴾؟","answer":"فرعت الأمر بذوق العذاب على إقرارهم بالبعث والحق؛ فبعد أن شهدوا على أنفسهم لم يبق إلا الجزاء الذي كذبوا به.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص496، تحت عنوان «دلالة فاء التفريع في ﴿قال فذوقوا﴾»","url":""}]},{"id":"s6-1087","number":1087,"surah":6,"verses":[30],"references":[{"surah":6,"verses":[30]}],"verseLabel":"الأنعام: 30","question":"ما الاستعارة في قوله تعالى: ﴿فذوقوا العذاب﴾؟","answer":"استعير الذوق، وهو إدراك الطعم، لمباشرة العذاب؛ فصور الألم شيئًا يجدون أثره بأنفسهم إدراكًا حسيًا لا واسطة فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص496–497، تحت عنوان «مفهوم الاستعارة في قوله تعالى: ﴿فذوقوا العذاب﴾»","url":""}]},{"id":"s6-1088","number":1088,"surah":6,"verses":[30],"references":[{"surah":6,"verses":[30]}],"verseLabel":"الأنعام: 30","question":"ما الفرق الدلالي بين الذوق والإحساس في قوله تعالى: ﴿فذوقوا العذاب﴾؟","answer":"الذوق يدل على مباشرة الأثر واختباره، أما الإحساس فأعم؛ فاختير الذوق لتصوير شدة اتصال العذاب بهم ووجدانهم أثره.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص499–500، تحت عنوان «الفرق بين الذوق والإحساس»","url":""}]},{"id":"s6-194","number":194,"surah":6,"verses":[30],"references":[{"surah":6,"verses":[30]}],"verseLabel":"الأنعام: 30","question":"ما دلالة قوله تعالى: ﴿بما كنتم تكفرون﴾، دون: بكفركم؟","answer":"الباء سببية و﴿ما﴾ مصدرية؛ أي: بسبب كفركم، والتعبير بـ﴿كنتم تكفرون﴾ يستحضر دوامهم في الدنيا على الكفر وستر ما دلت عليه عقولهم من صدق الرسول، بدل تسمية الجريمة بالمصدر مجردة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص497–498، تحت «الباء السببية وأثرها في المعنى، في قوله تعالى: ﴿بما كنتم تكفرون﴾»","url":""}]},{"id":"s6-195","number":195,"surah":6,"verses":[31],"references":[{"surah":6,"verses":[31]}],"verseLabel":"الأنعام: 31","question":"ما دلالة التعبير بالماضي المؤكد في قوله تعالى: ﴿قد خسر﴾ مع أن الخسران الأخروي مستقبل؟","answer":"﴿قد﴾ مع الماضي تحقق وقوع الخسران حتى صُوّر المستقبل المقطوع به كأنه حدث وانتهى؛ فمن كذب بلقاء الله انعقد سبب خسارته من الآن. وفي الصيغة إنذار بأن النتيجة ليست احتمالًا ينتظر التجربة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص505، تحت «دلالة حرف التحقيق ﴿قد﴾ في قوله تعالى: ﴿قد خسر﴾»","url":""}]},{"id":"s6-196","number":196,"surah":6,"verses":[31],"references":[{"surah":6,"verses":[31]}],"verseLabel":"الأنعام: 31","question":"ما دلالة صلة الموصول في قوله تعالى: ﴿الذين كذبوا بلقاء الله﴾؟","answer":"عينت الصلة سبب الخسران وكشفت حقيقة أصحابه؛ فتكذيبهم بلقاء الله هو الذي ساقهم إلى الندامة حين قامت الساعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص506، تحت عنوان «دلالة صلة الموصول في الربط بين أجزاء السياق»","url":""}]},{"id":"s6-1089","number":1089,"surah":6,"verses":[31],"references":[{"surah":6,"verses":[31]}],"verseLabel":"الأنعام: 31","question":"ما الاستعارة في قوله تعالى: ﴿بلقاء الله﴾؟","answer":"مثل الانتقال إلى موقف الحساب والجزاء بلقاء العبد ربه، فاستحضر قرب المواجهة وانكشاف العمل يوم القيامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص506–507، تحت عنوان «بلاغة الاستعارة التمثيلية في قوله تعالى: ﴿بلقاء الله﴾»","url":""}]},{"id":"s6-197","number":197,"surah":6,"verses":[31],"references":[{"surah":6,"verses":[31]}],"verseLabel":"الأنعام: 31","question":"ما دلالة ﴿حتى﴾ في قوله تعالى: ﴿حتى إذا جاءتهم الساعة بغتة﴾؟","answer":"جعلت مجيء الساعة غاية لإمهالهم واسترسالهم في التكذيب؛ فإذا بلغوه انقطع زمن العمل وبدأت الحسرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص507، تحت عنوان «دلالة ﴿حتى﴾ على الغاية في قوله تعالى: ﴿حتى إذا جاءتهم الساعة﴾»","url":""}]},{"id":"s6-1090","number":1090,"surah":6,"verses":[31],"references":[{"surah":6,"verses":[31]}],"verseLabel":"الأنعام: 31","question":"ما دلالة أسلوب الشرط في قوله تعالى: ﴿إذا جاءتهم الساعة بغتة قالوا يا حسرتنا﴾؟","answer":"ربط الشرط مجيء الساعة المفاجئ بجواب لا يتخلف هو انفجار الحسرة، فصور سرعة انتقالهم من الغفلة إلى الندم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص507–508، تحت عنوان «دلالة الشرط والجواب في قوله تعالى: ﴿إذا جاءتهم الساعة بغتة قالوا﴾»","url":""}]},{"id":"s6-198","number":198,"surah":6,"verses":[31],"references":[{"surah":6,"verses":[31]},{"surah":7,"verses":[187]}],"verseLabel":"الأنعام: 31؛ الأعراف: 187","question":"ما نكتة تسمية يوم القيامة بالساعة؟","answer":"سميت الساعة لقربها وسرعة مجيئها أو لأنها تقع في وقت محدد بغتة، فاستحضرت التسمية مباغتة القيامة وقصر زمن الدنيا أمامها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص508–509، تحت عنوان «نكتة تسمية يوم القيامة بالساعة»","url":""}]},{"id":"s6-199","number":199,"surah":6,"verses":[31],"references":[{"surah":6,"verses":[31]}],"verseLabel":"الأنعام: 31","question":"ما دلالة تقييد مجيء الساعة بقوله تعالى: ﴿بغتة﴾؟","answer":"﴿بغتة﴾ تعني فجأة من غير توقع ولا مهلة، فتصور الساعة وهي تواجه المكذبين وجهًا لوجه قبل أن يستدركوا تفريطهم. ولذلك أعقبها فورًا قولهم ﴿يا حسرتنا﴾؛ إذ انقضى زمن العمل وبقي انكشاف الخسارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص509، تحت «دلالة الوجوه الإعرابية للفظ ﴿بغتة﴾ وأثرها في توسيع المعنى»","url":""}]},{"id":"s6-200","number":200,"surah":6,"verses":[31],"references":[{"surah":6,"verses":[31]}],"verseLabel":"الأنعام: 31","question":"ما المجاز في قولهم: ﴿يا حسرتنا﴾؟","answer":"نزلت الحسرة منزلة شخص حاضر ينادى؛ لاستحضارها وتعظيمها حين أحاطت بهم ولم يجدوا ما يدفعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص509، تحت عنوان «دلالة المجاز في قوله تعالى: ﴿يا حسرتنا﴾»","url":""}]},{"id":"s6-1091","number":1091,"surah":6,"verses":[31],"references":[{"surah":6,"verses":[31]}],"verseLabel":"الأنعام: 31","question":"ما فائدة النداء في قوله تعالى: ﴿يا حسرتنا على ما فرطنا فيها﴾؟","answer":"أبرز النداء شدة الندم حتى كأن الحسرة نفسها مطلوبة للحضور؛ فقد جاء وقتها واستولت عليهم عند فوات التدارك.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص510، تحت عنوان «فائدة النداء في قوله تعالى: ﴿يا حسرتنا﴾»","url":""}]},{"id":"s6-1092","number":1092,"surah":6,"verses":[31],"references":[{"surah":6,"verses":[31]}],"verseLabel":"الأنعام: 31","question":"ما دلالة إضافة الحسرة إلى ضميرهم في قولهم: ﴿يا حسرتنا﴾؟","answer":"نسبوا الحسرة إلى أنفسهم إقرارًا بأنها لازمتهم وكانت ثمرة تفريطهم، فلم تعد مصيبة عارضة يمكن فصلها عنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص510، تحت عنوان «دلالة إضافة الحسرة إلى ضمير جمع المتكلم»","url":""}]},{"id":"s6-201","number":201,"surah":6,"verses":[31],"references":[{"surah":6,"verses":[31]}],"verseLabel":"الأنعام: 31","question":"ما دلالة قولهم: ﴿على ما فرطنا فيها﴾، وإلى ماذا يعود ضمير ﴿فيها﴾؟","answer":"التفريط هو التقصير بتضييع ما كان ينبغي حفظه، والضمير في ﴿فيها﴾ يعود إلى الحياة الدنيا؛ أي تحسروا على ما ضيعوه فيها من الإيمان والعمل الصالح والاستعداد للساعة. وقيل يعود إلى الساعة بمعنى التفريط في شأنها، والمعنيان يلتقيان في إضاعة الاستعداد لها في الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص511، تحت «دلالة الضمير في ﴿فيها﴾ من قوله تعالى: ﴿على ما فرطنا فيها﴾»","url":""}]},{"id":"s6-202","number":202,"surah":6,"verses":[31],"references":[{"surah":6,"verses":[31]}],"verseLabel":"الأنعام: 31","question":"ما دلالة تصوير الذنوب أوزارًا يحملونها في قوله تعالى: ﴿وهم يحملون أوزارهم﴾؟","answer":"الوزر في أصله الحمل الثقيل، فاستعير للذنوب وما يترتب عليها من وبال وعقوبة، وجُسدت المعاصي أثقالًا ملازمة لا يستطيع أصحابها طرحها. فتجعل الصورة المعنى الأخروي محسوسًا منفّرًا يرى فيه القارئ أثر العمل على حامله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص513، تحت «الاستعارة تجسد الآثام في صورة الأوزار، في قوله تعالى: ﴿يحملون أوزارهم﴾»","url":""}]},{"id":"s6-203","number":203,"surah":6,"verses":[31],"references":[{"surah":6,"verses":[31]}],"verseLabel":"الأنعام: 31","question":"ما الكناية في قوله تعالى: ﴿وهم يحملون أوزارهم﴾؟","answer":"إضافة الأوزار إليهم كناية عن اختصاصهم بذنوبهم ولزوم تبعتها لهم؛ فلا يحملها عنهم أحد ولا يستطيعون طرحها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص513، تحت عنوان «دلالة الكناية بإضافة الأوزار إليهم، في قوله تعالى: ﴿وهم يحملون أوزارهم﴾»","url":""}]},{"id":"s6-1093","number":1093,"surah":6,"verses":[31],"references":[{"surah":6,"verses":[31]}],"verseLabel":"الأنعام: 31","question":"ما أثر اقتران التنكيت بالمبالغة في قوله تعالى: ﴿يحملون أوزارهم على ظهورهم﴾؟","answer":"خص الظهور لأنها موضع حمل الأثقال، وبالغ فجعل الذنوب أحمالًا محسوسة تثقلهم وتظهر خزيهم في موقف الحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص513–514، تحت عنوان «اقتران التنكيت والمبالغة، في قوله تعالى: ﴿يحملون أوزارهم على ظهورهم﴾»","url":""}]},{"id":"s6-204","number":204,"surah":6,"verses":[31],"references":[{"surah":6,"verses":[31]}],"verseLabel":"الأنعام: 31","question":"ما دور ﴿ألا﴾ الاستفتاحية في قوله تعالى: ﴿ألا ساء ما يزرون﴾؟","answer":"نبهت السامع إلى الحكم الآتي وهولته، فلفتت الانتباه إلى فظاعة ما يحملونه وسوء عاقبته.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص514، تحت عنوان «دور الأداة (ألا) الاستفتاحية في قوله تعالى: ﴿ألا ساء ما يزرون﴾»","url":""}]},{"id":"s6-1094","number":1094,"surah":6,"verses":[31],"references":[{"surah":6,"verses":[31]}],"verseLabel":"الأنعام: 31","question":"ما دلالة الفعل ﴿ساء﴾ في قوله تعالى: ﴿ألا ساء ما يزرون﴾؟","answer":"أنشأ ذمًا بالغًا لما يحملونه من الآثام، ورد آخر الآية إلى مادة الوزر ليؤكد قبح الحمل وثقله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص514–515، تحت عنوان «دلالة الفعل ﴿ساء﴾ في السياق وأثر ذلك في المعنى»","url":""}]},{"id":"s6-205","number":205,"surah":6,"verses":[32],"references":[{"surah":6,"verses":[32]}],"verseLabel":"الأنعام: 32","question":"ما دلالة قصر الحياة الدنيا على اللعب واللهو؟","answer":"كشف حقيقة الدنيا حين تجعل غاية وتنقطع عن عمل الآخرة: شغل سريع الزوال لا يبقى لصاحبه، بخلاف ما يتصل بالدار الباقية.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص521، تحت عنوان «قصر الموصوف على الصفة»","url":""}]},{"id":"s6-1095","number":1095,"surah":6,"verses":[32],"references":[{"surah":6,"verses":[32]}],"verseLabel":"الأنعام: 32","question":"ما دلالة ﴿أل﴾ في قوله تعالى: ﴿الحياة الدنيا﴾؟","answer":"هي للجنس، فتتناول جنس الحياة القريبة بما يزول من متاعها، ثم تقابلها الآية بالدار الآخرة الباقية.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص521–522، تحت عنوان «دلالة (أل) على تعريف الجنس في ﴿الحياة الدنيا﴾»","url":""}]},{"id":"s6-206","number":206,"surah":6,"verses":[32],"references":[{"surah":6,"verses":[32]}],"verseLabel":"الأنعام: 32","question":"ما دلالة تقديم ﴿اللعب﴾ على ﴿اللهو﴾؟","answer":"قُدّم اللعب لأن سياق الآية في بيان الخسارة، وهي أكثر ما تكون من اللعب لما فيه من سرور النفس على غير وجه مشروع وسرعة انقضائه؛ ثم ذُكر اللهو إشارةً إلى الجهالة والانشغال بالأمور السافلة والشواغل الباطلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص523، تحت «نكتة تقديم اللعب على اللهو في قوله تعالى: ﴿إلا لعب ولهو﴾»","url":""}]},{"id":"s6-207","number":207,"surah":6,"verses":[32],"references":[{"surah":6,"verses":[32]}],"verseLabel":"الأنعام: 32","question":"لم لم يذكر المفضل عليه بعد ﴿وللدار الآخرة خير﴾؟","answer":"إذا حملت ﴿خير﴾ على التفضيل، فالتقدير: خير من الدنيا، وحذف المفضل عليه لأن المقابلة السابقة جعلته معلومًا. ويجوز أن يكون اللفظ لبيان ما في الآخرة من الخير في نفسه، دون قصد المفاضلة؛ فلا يحتاج حينئذ إلى مفضل عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص525، تحت «معنى لفظ ﴿خير﴾ وسر حذف المفضل عليه»","url":""}]},{"id":"s6-208","number":208,"surah":6,"verses":[32],"references":[{"surah":6,"verses":[32]}],"verseLabel":"الأنعام: 32","question":"ما دلالة التعبير بـ﴿الدار الآخرة﴾ في مقابلة ﴿الحياة الدنيا﴾؟","answer":"عُبر عن الآخرة بالدار لأنها محل الإقامة ومقر الناس الأخير الذي لا تحول بعده، في مقابل الحياة الدنيا الأولى القريبة؛ فالمقابلة تكشف فناء الدنيا ودوام دار الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص524–525، تحت «بيان التكنية عن القيامة في قوله تعالى: ﴿وللدار الآخرة خير﴾»","url":""}]},{"id":"s6-209","number":209,"surah":6,"verses":[32],"references":[{"surah":6,"verses":[32]}],"verseLabel":"الأنعام: 32","question":"ما دلالة العدول إلى الموصول في قوله تعالى: ﴿للذين يتقون﴾؟","answer":"جعلت الصلة، وهي التقوى، علة استحقاق خير الآخرة وطريق الانتفاع به؛ فلا يناله من بلغ الآخرة بلا تقوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص525، تحت عنوان «العدول عن الاسم الصريح إلى الموصول وصلته»","url":""}]},{"id":"s6-1096","number":1096,"surah":6,"verses":[32],"references":[{"surah":6,"verses":[32]}],"verseLabel":"الأنعام: 32","question":"ما دلالة المبالغة في قوله تعالى: ﴿وللدار الآخرة خير للذين يتقون﴾؟","answer":"نوهت بالمتقين لاختيارهم الباقي، وعرضت بالمشركين الذين آثروا متاع الدنيا مع وضوح تفاضل الدارين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص525–526، تحت عنوان «دلالة المبالغة على التعريض بالمشركين والتنويه بالمتقين»","url":""}]},{"id":"s6-1097","number":1097,"surah":6,"verses":[32],"references":[{"surah":6,"verses":[32]}],"verseLabel":"الأنعام: 32","question":"ما الاحتباك في قوله تعالى: ﴿وللدار الآخرة خير للذين يتقون﴾؟","answer":"ذكر في الدنيا اللعب واللهو وحذف ما يقابله من الشر، وذكر في الآخرة الخير للمتقين وحذف ما يقابله من عذاب المكذبين؛ فدل المذكوران على المحذوفين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص525–526، تحت عنوان «دلالة أسلوب الاحتباك في قوله تعالى: ﴿وللدار الآخرة خير للذين يتقون﴾»","url":""}]},{"id":"s6-210","number":210,"surah":6,"verses":[32],"references":[{"surah":6,"verses":[32]}],"verseLabel":"الأنعام: 32","question":"ما أثر التذييل في قوله تعالى: ﴿أفلا تعقلون﴾؟","answer":"لخص نتيجة الموازنة بين الفاني والباقي، وقرر أن اختيار الآخرة هو مقتضى العقل السليم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص527، تحت عنوان «أثر أسلوب التذييل في الدلالة بقوله تعالى: ﴿أفلا تعقلون﴾»","url":""}]},{"id":"s6-1098","number":1098,"surah":6,"verses":[32],"references":[{"surah":6,"verses":[32]}],"verseLabel":"الأنعام: 32","question":"ما دلالة اجتماع الالتفات والاستفهام في قوله تعالى: ﴿أفلا تعقلون﴾؟","answer":"نقل الخطاب إليهم وواجههم بالسؤال مباشرة بعد الحديث عنهم، فاشتد التنبيه وصاروا مسؤولين عن تعطيل عقولهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص528، تحت عنوان «دلالة تضافر أسلوبي الالتفات والاستفهام»","url":""}]},{"id":"s6-1099","number":1099,"surah":6,"verses":[32],"references":[{"surah":6,"verses":[32]}],"verseLabel":"الأنعام: 32","question":"ما غرض الاستفهام في قوله تعالى: ﴿أفلا تعقلون﴾؟","answer":"للتبكيت والتوبيخ؛ لأن تفضيل الباقي على الفاني تدركه العقول، فكان إعراضهم عنه موضع إنكار.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص528–529، تحت عنوان «دلالة الاستفهام على التبكيت والتوبيخ في قوله تعالى: ﴿أفلا تعقلون﴾»","url":""}]},{"id":"s6-211","number":211,"surah":6,"verses":[33],"references":[{"surah":6,"verses":[33]}],"verseLabel":"الأنعام: 33","question":"ما أثر ﴿قد﴾ في قوله تعالى: ﴿قد نعلم إنه ليحزنك الذي يقولون﴾؟","answer":"هي للتحقيق لا للتقليل، فأكدت إحاطة علم الله بحزن رسوله ﷺ وجاءت تسلية له بأن ألمه معلوم عند ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص532–533، تحت عنوان «أثر لفظ التحقيق ﴿قد﴾»","url":""}]},{"id":"s6-1100","number":1100,"surah":6,"verses":[33],"references":[{"surah":6,"verses":[33]}],"verseLabel":"الأنعام: 33","question":"ما دلالة المضارع ﴿نعلم﴾ بعد ﴿قد﴾؟","answer":"دل على استمرار العلم وتجدده بحسب ما يتجدد من أقوالهم المؤذية، فكان في ذلك دوام العناية والتثبيت.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص533–534، تحت عنوان «معنى الفعل المضارع ﴿نعلم﴾ بعد ﴿قد﴾»","url":""}]},{"id":"s6-212","number":212,"surah":6,"verses":[33],"references":[{"surah":6,"verses":[33]}],"verseLabel":"الأنعام: 33","question":"ما الفرق بين قوله هنا: ﴿قد نعلم إنه ليحزنك الذي يقولون﴾، وقوله في يس: ﴿فلا يحزنك قولهم﴾؟","answer":"يعرض سياق الأنعام الحزن عرضًا مؤكدًا، ويستحضر بـ﴿الذي يقولون﴾ قبح أقوالهم وتجددها واستمرار أثرها؛ ثم يسلّي الرسول ﷺ بقوله: ﴿فإنهم لا يكذبونك﴾، والمقام يدل على: فلا تحزن. أما آية يس فصرحت بالنهي مباشرةً: ﴿فلا يحزنك قولهم﴾. فلكل صياغة موضعها في بيان الحزن ودفعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص536–537، تحت «نكتة الفرق بين ﴿ليحزنك الذي يقولون﴾ و﴿فلا يحزنك قولهم﴾»","url":""}]},{"id":"s6-213","number":213,"surah":6,"verses":[33],"references":[{"surah":6,"verses":[33]}],"verseLabel":"الأنعام: 33","question":"ما نكتة العدول إلى الموصول في قوله تعالى: ﴿ليحزنك الذي يقولون﴾؟","answer":"عم الموصول أقوالهم المؤذية وربط الحزن بعلته من غير إعادة ألفاظهم القبيحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص535، تحت عنوان «نكتة العدول إلى الاسم الموصول في قوله تعالى: ﴿ليحزنك الذي يقولون﴾»","url":""}]},{"id":"s6-1101","number":1101,"surah":6,"verses":[33],"references":[{"surah":6,"verses":[33]}],"verseLabel":"الأنعام: 33","question":"ما دلالة المضارع في قوله تعالى: ﴿الذي يقولون﴾؟","answer":"استحضر تجدد أقوالهم واستمرار صدورها، فناسب تجدد ما تحدثه من حزن.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص535–536، تحت عنوان «دلالة الفعل المضارع في قوله تعالى: ﴿الذي يقولون﴾»","url":""}]},{"id":"s6-1102","number":1102,"surah":6,"verses":[33],"references":[{"surah":6,"verses":[33]}],"verseLabel":"الأنعام: 33","question":"ما فائدة عدم ذكر ما يقولون في قوله تعالى: ﴿الذي يقولون﴾؟","answer":"ترك المقول مطلقًا ليشمل كل صور التكذيب والسخرية والاتهام، وللإعراض عن حكاية ألفاظهم لشناعتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص536، تحت عنوان «فائدة عدم ذكر ما يقولون»","url":""}]},{"id":"s6-214","number":214,"surah":6,"verses":[33],"references":[{"surah":6,"verses":[33]}],"verseLabel":"الأنعام: 33","question":"ما أثر اختلاف القراءة في قوله تعالى: ﴿فإنهم لا يكذبونك﴾؟","answer":"على التشديد يكون المعنى أنهم لا يثبتون كذبك في أنفسهم، وعلى التخفيف أنهم لا يجدونك كاذبًا؛ وفي الوجهين يعرفون صدقه ويجحدون الآيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص539، تحت عنوان «توجيه المعنى باختلاف القراءة في قوله تعالى: ﴿فإنهم لا يكذبونك﴾»","url":""}]},{"id":"s6-1103","number":1103,"surah":6,"verses":[33],"references":[{"surah":6,"verses":[33]}],"verseLabel":"الأنعام: 33","question":"ما دلالة الاستدراك في قوله تعالى: ﴿ولكن الظالمين بآيات الله يجحدون﴾؟","answer":"دفع توهم أن نفي تكذيب شخص الرسول ﷺ ينفي عنهم الجحود؛ فبين أن خصومتهم متجهة إلى آيات الله مكابرة وظلمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص539، تحت عنوان «الاستدراك لدفع التوهم في قوله تعالى: ﴿ولكن الظالمين بآيات الله يجحدون﴾»","url":""}]},{"id":"s6-215","number":215,"surah":6,"verses":[33],"references":[{"surah":6,"verses":[33]}],"verseLabel":"الأنعام: 33","question":"ما دلالة الانتقال من ضمير النبي ﷺ في ﴿يكذبونك﴾ إلى الاسم الظاهر في ﴿بآيات الله يجحدون﴾؟","answer":"أظهر اسم الله ليرفع القضية من أذى شخصي للرسول إلى جحود بحجج الله نفسه، فيشتد ذمهم وتتم تسلية النبي ﷺ. كما أن إضافة الآيات إلى الله تعظم ما واجهوه بالإنكار وتبين صاحب الحق الذي اعتدوا عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص540–541، تحت «بلاغة القصر بتقديم الجار والمجرور في قوله تعالى: ﴿بآيات الله يجحدون﴾»","url":""}]},{"id":"s6-216","number":216,"surah":6,"verses":[33],"references":[{"surah":6,"verses":[33]}],"verseLabel":"الأنعام: 33","question":"ما دلالة تقديم ﴿بآيات الله﴾ على ﴿يجحدون﴾؟","answer":"قدم الجار والمجرور للعناية بموضع جحودهم وللقصر بحسب السياق: ليس الذي ينالونه حقيقةً شخص الرسول ﷺ، وإنما تتجه مكابرتهم إلى آيات الله. وفي التقديم تعجيل بذكر الآيات المعظمة قبل تسجيل فعل الجحود.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص540–541، تحت «بلاغة القصر بتقديم الجار والمجرور في قوله تعالى: ﴿بآيات الله يجحدون﴾»","url":""}]},{"id":"s6-217","number":217,"surah":6,"verses":[33],"references":[{"surah":6,"verses":[33]}],"verseLabel":"الأنعام: 33","question":"ما دلالة الجحود في قوله تعالى: ﴿بآيات الله يجحدون﴾؟","answer":"الجحود إنكار الحق مع معرفته، فدل على أنهم تيقنوا الآيات ثم ردوها ظلمًا ومكابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص541، تحت عنوان «دلالة الجحود بآيات الله في قوله تعالى: ﴿ولكن الظالمين بآيات الله يجحدون﴾»","url":""}]},{"id":"s6-1104","number":1104,"surah":6,"verses":[33],"references":[{"surah":6,"verses":[33]}],"verseLabel":"الأنعام: 33","question":"ما الفرق بين الجحد والإنكار؟","answer":"الإنكار أعم وقد يقع لعدم المعرفة، أما الجحد فهو إنكار ما عرفه صاحبه أو استيقنه؛ ولذلك كان أبلغ في ذمهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص541–542، تحت عنوان «(الجحد) و(الإنكار)»","url":""}]},{"id":"s6-218","number":218,"surah":6,"verses":[34],"references":[{"surah":6,"verses":[34]}],"verseLabel":"الأنعام: 34","question":"ما دلالة تنكير ﴿رسل﴾ في قوله تعالى: ﴿ولقد كذبت رسل من قبلك﴾؟","answer":"يفتح التنكير، مع وصف الرسل بأنهم من قبله، باب التسلية بسابقين كثيرين ذوي شأن عرفوا التكذيب والصبر عليه. فلا تختص هذه المحنة برسول واحد؛ وإنما هي سيرة متكررة يجد فيها النبي ﷺ القدوة والثبات.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص549–550، تحت «دلالة تعلق حرف ﴿من﴾ في قوله تعالى: ﴿ولقد كذبت رسل من قبلك﴾»","url":""}]},{"id":"s6-219","number":219,"surah":6,"verses":[34],"references":[{"surah":6,"verses":[34]}],"verseLabel":"الأنعام: 34","question":"ما دلالة بناء ﴿كُذبت﴾ للمفعول؟","answer":"وجه العناية إلى ما وقع على الرسل من التكذيب لأنه موضع تسلية النبي ﷺ والقدوة في الصبر، أما المكذبون فتختلف أممهم ولا حاجة إلى تسميتهم. وفي حذف الفاعل تعميم لكل من سلك طريقهم في مقاومة الرسل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص548–549، تحت «أثر البناء للمفعول في توجيه المعنى»","url":""}]},{"id":"s6-220","number":220,"surah":6,"verses":[34],"references":[{"surah":6,"verses":[34]}],"verseLabel":"الأنعام: 34","question":"ما دلالة تعدية الصبر بـ﴿على﴾ في قوله تعالى: ﴿فصبروا على ما كذبوا وأوذوا﴾؟","answer":"تفيد ﴿على﴾ الاستعلاء والتمكن؛ فكأن التكذيب والأذى حمل ثقيل علاه الرسل وثبتوا فوقه فلم يغلبهم. والتعبير يرسم الصبر قوةً ومغالبةً لا مجرد انتظار سلبي.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص550–551، تحت «نكتة تعدية فعل الصبر بالحرف ﴿على﴾ في قوله تعالى: ﴿فصبروا على ما كذبوا﴾»","url":""}]},{"id":"s6-221","number":221,"surah":6,"verses":[34],"references":[{"surah":6,"verses":[34]}],"verseLabel":"الأنعام: 34","question":"ما دلالة الجمع بين التكذيب والأذى مع أن التكذيب لون من الأذى؟","answer":"خُص التكذيب بالذكر لأنه أذى موجه إلى الرسالة والحق الذي جاء به الرسل، ثم عُطف عليه الأذى وهو أعم، فيشمل كل إساءة نالتهم وما كان أشد من مجرد التكذيب؛ فاجتمع الخاص والعام لإحاطة البلاء الذي صبروا عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص550، تحت «دلالة عطف العام على الخاص في قوله تعالى: ﴿فصبروا على ما كذبوا وأوذوا﴾»","url":""}]},{"id":"s6-222","number":222,"surah":6,"verses":[34],"references":[{"surah":6,"verses":[34]}],"verseLabel":"الأنعام: 34","question":"ما دلالة جعل مجيء النصر غايةً في قوله تعالى: ﴿حتى أتاهم نصرنا﴾؟","answer":"تفيد ﴿حتى﴾ استمرار صبرهم طوال زمن التكذيب والأذى إلى أن جاء النصر في وقته الذي قدره الله. فالنصر ثمرة موعودة للصبر، لكنه لا يعفي من احتمال الطريق حتى يبلغ أجله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص552–553، تحت «ورود الحرف ﴿حتى﴾ مفيدًا الغاية»","url":""}]},{"id":"s6-223","number":223,"surah":6,"verses":[34],"references":[{"surah":6,"verses":[34]}],"verseLabel":"الأنعام: 34","question":"ما سر استعمال مادة الإتيان مع النصر في قوله تعالى: ﴿حتى أتاهم نصرنا﴾؟","answer":"صور النصر كأنه قادم يبلغ الرسل في وقته المقدر، فزاد معنى تحقق الوعد ووصوله بعد الصبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص553، تحت عنوان «سر استعمال مادة الإتيان مع النصر»","url":""}]},{"id":"s6-1105","number":1105,"surah":6,"verses":[34],"references":[{"surah":6,"verses":[34]}],"verseLabel":"الأنعام: 34","question":"ما المجاز في قوله تعالى: ﴿حتى أتاهم نصرنا﴾؟","answer":"شخص النصر بمعنى تحقق أسبابه وآثاره في صورة آتٍ يصل إليهم، فصار الوعد مشهدًا محسوسًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص553–554، تحت عنوان «دلالة المجاز في قوله تعالى: ﴿حتى أتاهم نصرنا﴾»","url":""}]},{"id":"s6-224","number":224,"surah":6,"verses":[34],"references":[{"surah":6,"verses":[34]}],"verseLabel":"الأنعام: 34","question":"ما دلالة العطف في قوله تعالى: ﴿ولا مبدل لكلمات الله﴾؟","answer":"عطف ضمانًا عامًا على خبر نصر الرسل؛ فنصرهم من كلمات الله التي لا يملك أحد تغييرها أو منع نفاذها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص554، تحت عنوان «دلالة العطف وأثره في المعنى»","url":""}]},{"id":"s6-1106","number":1106,"surah":6,"verses":[34],"references":[{"surah":6,"verses":[34]}],"verseLabel":"الأنعام: 34","question":"ما الكناية في قوله تعالى: ﴿ولا مبدل لكلمات الله﴾؟","answer":"كناية عن تحقق وعد الله وثبات سنته؛ فانتفاء من يبدل كلماته يقتضي نفاذها حتمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص554–555، تحت عنوان «دلالة الكناية في قوله تعالى: ﴿ولا مبدل لكلمات الله﴾»","url":""}]},{"id":"s6-225","number":225,"surah":6,"verses":[34],"references":[{"surah":6,"verses":[34]}],"verseLabel":"الأنعام: 34","question":"ما دلالة جمع ﴿كلمات الله﴾ في قوله تعالى: ﴿ولا مبدل لكلمات الله﴾؟","answer":"الجمع يشمل ما تعدد من وعود الله وأحكامه وقضائه ووحيه، ومنها كلمته بنصر رسله؛ فلا يملك أحد تبديل شيء منها. وبهذا انتقل التثبيت من وعد واحد إلى قاعدة عامة تحمي كل ما أخبر الله به.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص555، تحت «دلالة الكناية في قوله تعالى: ﴿ولا مبدل لكلمات الله﴾».","url":""}]},{"id":"s6-226","number":226,"surah":6,"verses":[34],"references":[{"surah":6,"verses":[34]}],"verseLabel":"الأنعام: 34","question":"ما أثر القسم و﴿قد﴾ في قوله تعالى: ﴿ولقد جاءك من نبإ المرسلين﴾؟","answer":"تضافرا في تأكيد تحقق وصول الخبر المسلي، فثبت للنبي ﷺ أن سنة الابتلاء والنصر ماضية في الرسل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص557، تحت عنوان «تضافر القسم وحرف التحقيق في البيان والتأكيد»","url":""}]},{"id":"s6-1107","number":1107,"surah":6,"verses":[34],"references":[{"surah":6,"verses":[34]}],"verseLabel":"الأنعام: 34","question":"ما دلالة ﴿من﴾ في قوله تعالى: ﴿من نبإ المرسلين﴾؟","answer":"هي للتبعيض؛ أي جاءه من أخبار الرسل القدر الذي يحقق العبرة والتثبيت، لا استقصاء جميع أحوالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص557–558، تحت عنوان «دلالة ﴿من﴾ على أن الإنسان لا يؤتى من العلم إلا بعضه»","url":""}]},{"id":"s6-1108","number":1108,"surah":6,"verses":[34],"references":[{"surah":6,"verses":[34]}],"verseLabel":"الأنعام: 34","question":"ما الغرض من استعمال مادة النبأ في قوله تعالى: ﴿من نبإ المرسلين﴾؟","answer":"النبأ خبر عظيم له شأن وفائدة وعاقبة، فناسب أخبار الرسل بما فيها من تثبيت ووعد بالنصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص558، تحت عنوان «الغرض من استعمال مادة النبأ»","url":""}]},{"id":"s6-227","number":227,"surah":6,"verses":[35],"references":[{"surah":6,"verses":[35]}],"verseLabel":"الأنعام: 35","question":"ما المجاز في قوله تعالى: ﴿كبر عليك إعراضهم﴾؟","answer":"صور شدة الإعراض وألمه بأمر عظيم ثقيل على الرسول ﷺ، فدل على مبلغ حرصه على هدايتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص564، تحت عنوان «دلالة المجاز المرسل في قوله تعالى: ﴿كبر عليك إعراضهم﴾»","url":""}]},{"id":"s6-1109","number":1109,"surah":6,"verses":[35],"references":[{"surah":6,"verses":[35]}],"verseLabel":"الأنعام: 35","question":"ما نكتة تعدية ﴿كبر﴾ بـ﴿على﴾ في قوله تعالى: ﴿كبر عليك إعراضهم﴾؟","answer":"أفادت استعلاء ثقل الإعراض عليه وتمكن مشقته منه، فكأنه حمل واقع فوقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص564–565، تحت عنوان «نكتة تعدية الفعل (كبر) بأداة الاستعلاء (على) في الآية الكريمة»","url":""}]},{"id":"s6-228","number":228,"surah":6,"verses":[35],"references":[{"surah":6,"verses":[35]}],"verseLabel":"الأنعام: 35","question":"ما بلاغة المقابلة بين ﴿في الأرض﴾ و﴿في السماء﴾؟","answer":"جمعت طرفي المكان: أقصى النزول وأقصى الصعود، لتستوعب كل سبيل متوهم في طلب آية توافق اقتراحهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص568، تحت عنوان «بلاغة المقابلة بين قوله تعالى: ﴿في الأرض﴾ وقوله: ﴿في السماء﴾»","url":""}]},{"id":"s6-1110","number":1110,"surah":6,"verses":[35],"references":[{"surah":6,"verses":[35]}],"verseLabel":"الأنعام: 35","question":"كيف حصرت جملة الشرط مهمة النبوة في البلاغ لا الإكراه؟","answer":"علقت الإتيان بآية مقترحة على أمر متعذر، فبينت أن حرص الرسول ﷺ لا يحول الرسالة إلى إكراه للناس على الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص568–569، تحت عنوان «دور جملة الشرط في حصر مهمة النبوة في البلاغ لا في الإكراه»","url":""}]},{"id":"s6-229","number":229,"surah":6,"verses":[35],"references":[{"surah":6,"verses":[35]}],"verseLabel":"الأنعام: 35","question":"لم قيل: ﴿أن تبتغي نفقًا﴾ بدل أن تتخذ نفقًا؟","answer":"الابتغاء يصور شدة الطلب والسعي إلى الآية، أما اتخاذ النفق فيوحي بتحقق الوسيلة. فالتعبير يلائم فرض أمر لا يستطيع الرسول ﷺ تحصيله، ويبين مبلغ حرصه على إيمانهم مع أن الإتيان بما يقترحونه لا يضمن هدايتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص569، تحت «دلالة إيثار (الابتغاء) على (الاتخاذ) في قوله تعالى: ﴿أن تبتغي نفقًا في الأرض﴾»","url":""}]},{"id":"s6-230","number":230,"surah":6,"verses":[35],"references":[{"surah":6,"verses":[35]}],"verseLabel":"الأنعام: 35","question":"ما دلالة الجار والمجرور في قوله تعالى: ﴿فتأتيهم بآية﴾؟","answer":"صورت الباء مصاحبة الرسول ﷺ للآية المقترحة عند الإتيان بها، مع أن ظهورها لا يكون إلا بإذن الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص570، تحت عنوان «دلالة الجار والمجرور في قوله تعالى: ﴿فتأتيهم بآية﴾»","url":""}]},{"id":"s6-1111","number":1111,"surah":6,"verses":[35],"references":[{"surah":6,"verses":[35]}],"verseLabel":"الأنعام: 35","question":"ما دلالة الفاء في قوله تعالى: ﴿فتأتيهم بآية﴾؟","answer":"رتبت الإتيان بالآية على استطاعة اتخاذ النفق أو السلم، فزاد الشرط إحكام تصوير تعذر ما طلبوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص570–571، تحت عنوان «دلالة الفاء في ﴿فتأتيهم﴾»","url":""}]},{"id":"s6-1112","number":1112,"surah":6,"verses":[35],"references":[{"surah":6,"verses":[35]}],"verseLabel":"الأنعام: 35","question":"ما دلالة تنوين ﴿آية﴾ في قوله تعالى: ﴿فتأتيهم بآية﴾؟","answer":"للتفخيم؛ أي آية عظيمة من جنس ما اقترحوه تعنتًا، لا نفي كون القرآن آية قائمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص571، تحت عنوان «دلالة تنوين لفظ ﴿بآية﴾»","url":""}]},{"id":"s6-231","number":231,"surah":6,"verses":[35],"references":[{"surah":6,"verses":[35]}],"verseLabel":"الأنعام: 35","question":"ما دلالة قوله تعالى: ﴿ولو شاء الله لجمعهم على الهدى﴾، دون: لهداهم؟","answer":"﴿لجمعهم على الهدى﴾ بمعنى: لهداهم أجمعين، وعدل إلى هذا التركيب للإيماء إلى أنه لو شاء لجمع من بقي من المشركين مع المؤمنين على ما هدى إليه المؤمنين؛ غير أن هذا الجمع، وإن لم يعجز المشيئة، مخالف لسنة الله في خلقه القائمة على الاختيار.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص571–572، تحت «مخالفة تركيبية في التعبير عن الهدى بقوله تعالى: ﴿لجمعهم على الهدى﴾».","url":""}]},{"id":"s6-232","number":232,"surah":6,"verses":[35],"references":[{"surah":6,"verses":[35]}],"verseLabel":"الأنعام: 35","question":"ما دلالة العدول عن الأمر بالعلم إلى قوله تعالى: ﴿فلا تكونن من الجاهلين﴾؟","answer":"جاء النهي أبلغ في التثبيت والتحذير من أن يحمل الحزن على طلب ما لا تقتضيه حكمة الله، مع تنزيه النبي ﷺ عن الجهل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص572–573، تحت عنوان «دلالة العدول عن الأمر بالعلم إلى قوله تعالى: ﴿فلا تكونن من الجاهلين﴾»","url":""}]},{"id":"s6-1113","number":1113,"surah":6,"verses":[35],"references":[{"surah":6,"verses":[35]}],"verseLabel":"الأنعام: 35","question":"ما المراد بالجاهلين في قوله تعالى: ﴿فلا تكونن من الجاهلين﴾؟","answer":"هم الذين يجهلون سنة الله في الهداية والاختيار، فالخطاب تثبيت للنبي ﷺ وتعليم للأمة حدود مهمة الرسول.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص574–575، تحت عنوان «بيان المراد بلفظ الجاهلين في سياق الآية الكريمة»","url":""}]},{"id":"s6-1114","number":1114,"surah":6,"verses":[35],"references":[{"surah":6,"verses":[35]}],"verseLabel":"الأنعام: 35","question":"لماذا قيل: ﴿من الجاهلين﴾ دون «جاهلًا»؟","answer":"نهاه عن أدنى ملابسة لطريق جماعة الجاهلين، فكان أبلغ من مجرد نفي وصف مفرد عارض.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص575، تحت عنوان «سر العدول عن: فلا تكن جاهلًا، إلى: ﴿فلا تكونن من الجاهلين﴾»","url":""}]},{"id":"s6-233","number":233,"surah":6,"verses":[35],"references":[{"surah":6,"verses":[35]}],"verseLabel":"الأنعام: 35","question":"ما الفرق بين ﴿فلا تكونن﴾ و«فلا تكن» و«أن تكون»؟","answer":"﴿فلا تكونن﴾ نهي مؤكد مباشر، و«فلا تكن» نهي بلا توكيد، و«أن تكون» مصدر مؤول لا يحمل قوة المواجهة والردع نفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص573–574، تحت عنوان «توجيه الفرق بين قوله تعالى: ﴿فلا تكونن﴾ و﴿فلا تكن﴾ و﴿أن تكون﴾»","url":""}]},{"id":"s6-1115","number":1115,"surah":6,"verses":[35],"references":[{"surah":6,"verses":[35]}],"verseLabel":"الأنعام: 35","question":"ما الغرض من توكيد النهي في قوله تعالى: ﴿فلا تكونن من الجاهلين﴾؟","answer":"شدد التثبيت ليتناسب مع شدة حرص النبي ﷺ على هدايتهم، ويقطع طريق الاسترسال مع الحزن من غير أن يدل على وقوع الجهل منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص574، تحت عنوان «بيان الغرض من توكيد النهي في قوله تعالى: ﴿فلا تكونن من الجاهلين﴾»","url":""}]},{"id":"s6-234","number":234,"surah":6,"verses":[36],"references":[{"surah":6,"verses":[36]}],"verseLabel":"الأنعام: 36","question":"ما دلالة ﴿يسمعون﴾ في قوله تعالى: ﴿إنما يستجيب الذين يسمعون﴾؟","answer":"المراد سماع القبول والتدبر الذي ينفذ إلى القلب ويثمر استجابة، لا مجرد وصول الصوت إلى الأذن.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص584، تحت عنوان «دلالة لفظ ﴿يسمعون﴾ وأثرها في السياق»","url":""}]},{"id":"s6-1116","number":1116,"surah":6,"verses":[36],"references":[{"surah":6,"verses":[36]}],"verseLabel":"الأنعام: 36","question":"لماذا عُبر بالسماع دون الإيمان في قوله تعالى: ﴿الذين يسمعون﴾؟","answer":"جعل السماع الواعي أول طريق الاستجابة، وعرض بالمكذبين الذين يسمعون الألفاظ ولا يفتحون لها قلوبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص584–585، تحت عنوان «نكتة التعبير بالسماع ﴿الذين يسمعون﴾ دون الإيمان في الآية»","url":""}]},{"id":"s6-235","number":235,"surah":6,"verses":[36],"references":[{"surah":6,"verses":[36]}],"verseLabel":"الأنعام: 36","question":"لماذا أوثر ﴿يستجيب﴾ على مرادفاته؟","answer":"الاستجابة تتضمن قبول الداعي والإقبال إلى مقتضى دعوته وامتثاله، فهي أوسع من مجرد الإجابة أو التصديق.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص583، تحت عنوان «نكتة إيثار لفظ ﴿يستجيب﴾ على مرادفاته»","url":""}]},{"id":"s6-1117","number":1117,"surah":6,"verses":[36],"references":[{"surah":6,"verses":[36]}],"verseLabel":"الأنعام: 36","question":"ما معنى السين والتاء في قوله تعالى: ﴿يستجيب﴾؟","answer":"السين والتاء زائدتان لإفادة التأكيد، فالاستجابة أخص من الإجابة؛ لأنها قبول الدعوة مع الإقبال والطاعة، ولذلك ناسبت من يسمع سماع فهم ثم يمتثل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص583، تحت عنوان «معنى السين والتاء في ﴿يستجيب﴾»","url":""}]},{"id":"s6-236","number":236,"surah":6,"verses":[36],"references":[{"surah":6,"verses":[36]}],"verseLabel":"الأنعام: 36","question":"ما دلالة المضارع في قوله تعالى: ﴿يستجيب﴾؟","answer":"يصور الاستجابة فعلًا متجددًا كلما سمع أصحاب القلوب الحية آيةً أو دعوةً إلى الحق، فهي صفة مستمرة لا واقعة ماضية منقطعة. كما يستحضر أثر السماع أمام القارئ في الحال.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص584، تحت «فائدة التعبير بصيغة المضارع ﴿يستجيب﴾»","url":""}]},{"id":"s6-237","number":237,"surah":6,"verses":[36],"references":[{"surah":6,"verses":[36]}],"verseLabel":"الأنعام: 36","question":"ما دلالة مقابلة الذين يسمعون بـ﴿الموتى﴾ مع أن الحديث عن مكذبين أحياء؟","answer":"شبّه المكذبين بالموتى لأنهم فقدوا أثر الحياة المعنوية: يسمعون الصوت ولا يملكون استجابة القلب، كما لا يجيب الميت نداءً. وحُذفت أداة التشبيه حتى صار موت القلب كأنه حقيقتهم، فاشتدت المفارقة بينهم وبين السامعين المستجيبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص586–587، تحت «بلاغة الاستعارة التصريحية في قوله: ﴿والموتى﴾»","url":""}]},{"id":"s6-238","number":238,"surah":6,"verses":[36],"references":[{"surah":6,"verses":[36]}],"verseLabel":"الأنعام: 36","question":"ما دلالة المضارع في قوله تعالى: ﴿والموتى يبعثهم الله﴾، دون: سيبعثهم؟","answer":"المضارع يقرر البعث بوصفه فعلًا داخلًا في قدرة الله وسنته المقطوع بها، ويستحضره كأنه مشاهد، فلا يحتاج إلى السين التي قد تبقيه بعيدًا في تصور السامع. وهو يشمل بعث الموتى حقيقةً، مع التلويح بأن إحياء القلوب المغلقة ليس بيد الرسول.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص588، تحت «نكتة اختيار صيغة ﴿يبعثهم﴾ دون (سيبعثهم)».","url":""}]},{"id":"s6-239","number":239,"surah":6,"verses":[36],"references":[{"surah":6,"verses":[36]}],"verseLabel":"الأنعام: 36","question":"ما دلالة إظهار اسم الله في قوله تعالى: ﴿يبعثهم الله﴾؟","answer":"إسناد البعث إلى اسم الله يقرر أن إحياء الموتى بقدرته وحده، ويثبت حقيقة البعث التي ينكرونها، وفيه تهديد ووعيد. وعلى تفسير البعث بهداية موتى القلوب، يعيد أمر هدايتهم إليه؛ ففي ذكره تعظيم للقدرة وترغيب في الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص588، تحت «بلاغة إسناد فعل ﴿يبعثهم﴾ إلى لفظ الجلالة»","url":""}]},{"id":"s6-240","number":240,"surah":6,"verses":[36],"references":[{"surah":6,"verses":[36]}],"verseLabel":"الأنعام: 36","question":"ما وجه القصر في قوله تعالى: ﴿ثم إليه يرجعون﴾؟","answer":"تقديم ﴿إليه﴾ قصر المرجع والحساب على الله وحده، فلا رجوع إلى من عبدوهم ولا ملجأ سواه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص587، تحت عنوان «وجه القصر والحصر المستفاد في جملة ﴿ثم إليه يرجعون﴾»","url":""}]},{"id":"s6-1118","number":1118,"surah":6,"verses":[36],"references":[{"surah":6,"verses":[36]}],"verseLabel":"الأنعام: 36","question":"ما دلالة ﴿ثم﴾ في قوله تعالى: ﴿ثم إليه يرجعون﴾؟","answer":"أفادت التراخي بين بعثهم وانتهاء أمرهم إلى موقف الجزاء، مع تهويل ما يعقب البعث من رجوع وحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص587–588، تحت عنوان «معنى حرف التراخي ﴿ثم﴾ ودلالته في السياق»","url":""}]},{"id":"s6-241","number":241,"surah":6,"verses":[37],"references":[{"surah":6,"verses":[37]}],"verseLabel":"الأنعام: 37","question":"ما دلالة إفراد ﴿آية﴾ مع إرادة جنس الآيات في قولهم: ﴿لولا نزل عليه آية﴾؟","answer":"أفردت لأن المراد آية واحدة من الجنس الذي يقترحونه تعنتًا، مع قيام القرآن وغيره من الدلائل بينهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص593، تحت عنوان «دلالة إفراد لفظ ﴿آية﴾ وإرادة الجمع»","url":""}]},{"id":"s6-1119","number":1119,"surah":6,"verses":[37],"references":[{"surah":6,"verses":[37]}],"verseLabel":"الأنعام: 37","question":"ما دلالة ﴿لولا﴾ في قولهم: ﴿لولا نزل عليه آية من ربه﴾؟","answer":"للتحضيض؛ حكت إلحاحهم على إنزال آية حسية مقترحة، وفيه تعريض منهم بأن الحجة القائمة لا تكفي.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص593–594، تحت عنوان «دلالة ﴿لولا﴾ على التحضيض في قوله تعالى: ﴿لولا نزل عليه آية من ربه﴾»","url":""}]},{"id":"s6-242","number":242,"surah":6,"verses":[37],"references":[{"surah":6,"verses":[37]}],"verseLabel":"الأنعام: 37","question":"ما دلالة صيغة ﴿نُزّل﴾ المشددة في حكاية طلبهم؟","answer":"تشديد ﴿نُزّل﴾ يشير إلى تكرر نزول آيات القرآن عليهم؛ وفيه كشف لتناقضهم، إذ يطلبون آية واحدة قاهرة كأن شيئًا لم ينزل، مع أن القرآن كان يتنزل عليهم آيةً بعد آية.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص594–595، تحت «نكتة إيثار صيغة (نُزّل) على (أُنزل)».","url":""}]},{"id":"s6-243","number":243,"surah":6,"verses":[37],"references":[{"surah":6,"verses":[37]}],"verseLabel":"الأنعام: 37","question":"لماذا آثروا عنوان الربوبية في قولهم: ﴿من ربه﴾؟","answer":"لأنهم كانوا يقرون بربوبية الله مع جحود استحقاقه للعبادة، فجاء اقتراحهم في صورة امتحان لما يدعيه الرسول ﷺ من رسالة ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص596، تحت عنوان «إيثار عنوان الربوبية على الألوهية ﴿من ربه﴾»","url":""}]},{"id":"s6-1120","number":1120,"surah":6,"verses":[37],"references":[{"surah":6,"verses":[37]}],"verseLabel":"الأنعام: 37","question":"ما دلالة إضافة ﴿رب﴾ إلى ضمير النبي في قولهم: ﴿من ربه﴾؟","answer":"في الإضافة تعريض وتهكم؛ أي إن كان له رب يرسله فليأت منه بآية توافق اقتراحهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص596–597، تحت عنوان «دلالة إضافة (رب) إلى ضمير النبي ﴿ربه﴾»","url":""}]},{"id":"s6-1121","number":1121,"surah":6,"verses":[37],"references":[{"surah":6,"verses":[37]}],"verseLabel":"الأنعام: 37","question":"ما دلالة العدول من قولهم ﴿من ربه﴾ إلى الجواب باسم الجلالة: ﴿قل إن الله قادر﴾؟","answer":"رد تعريضهم بالاسم الجامع لصفات الألوهية، وقرر أن القادر على إنزال الآيات هو الله المعبود بحق وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص598، تحت عنوان «دلالة العدول من لفظ ﴿ربي﴾ إلى اسم الجلالة ﴿الله﴾»","url":""}]},{"id":"s6-244","number":244,"surah":6,"verses":[37],"references":[{"surah":6,"verses":[37]}],"verseLabel":"الأنعام: 37","question":"ما غرض توكيد قوله تعالى: ﴿إن الله قادر﴾؟","answer":"أزال توهم أن عدم إنزال الآية المقترحة ناشئ عن عجز، وأثبت أن الترك جار على الحكمة والمشيئة مع تمام القدرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص597–598، تحت عنوان «غرض توكيد جملة مقول القول ﴿إن الله قادر﴾»","url":""}]},{"id":"s6-245","number":245,"surah":6,"verses":[37],"references":[{"surah":6,"verses":[37]}],"verseLabel":"الأنعام: 37","question":"ما سر استعمال حرف الاستعلاء ﴿على﴾ في قوله تعالى: ﴿قادر على أن ينزل آية﴾؟","answer":"أفادت تمكن القدرة من متعلقها واستعلاءها عليه، فأكدت أن عدم إنزال الآية المقترحة ليس عجزًا بل تابع للحكمة والمشيئة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص598، تحت عنوان «سر استعمال حرف الاستعلاء ﴿على﴾»","url":""}]},{"id":"s6-246","number":246,"surah":6,"verses":[37],"references":[{"surah":6,"verses":[37]}],"verseLabel":"الأنعام: 37","question":"ما غرض عطف جملة الاستدراك في قوله تعالى: ﴿ولكن أكثرهم لا يعلمون﴾؟","answer":"بين بعد إثبات القدرة أن أكثرهم يجهلون حكمة عدم إنزال الآية القاهرة وخطر التكذيب بها، فليس تركها عجزًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص599، تحت عنوان «غرض عطف جملة الاستدراك على مقول القول»","url":""}]},{"id":"s6-1122","number":1122,"surah":6,"verses":[37],"references":[{"surah":6,"verses":[37]}],"verseLabel":"الأنعام: 37","question":"لماذا نُفي عنهم العلم دون الإيمان في قوله تعالى: ﴿لا يعلمون﴾؟","answer":"لأن موطن الخلل هنا جهلهم بسنة الله وحكمته وعاقبة اقتراح الآيات؛ فنفي العلم يكشف أصل شبهتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص599–600، تحت عنوان «نكتة نفي العلم دون الإيمان ﴿لا يعلمون﴾»","url":""}]},{"id":"s6-247","number":247,"surah":6,"verses":[37],"references":[{"surah":6,"verses":[37]}],"verseLabel":"الأنعام: 37","question":"ما دلالة قوله تعالى: ﴿أكثرهم﴾، دون: كلهم؟","answer":"أثبت أن الجهل غالب في أصحاب الاقتراح، لكنه لم يسو بينهم جميعًا؛ ففيهم من يعلم وجه الحق ثم يكابر، أو من يمكن أن يهتدي. وهذه الدقة تمنع التعميم وتبين تفاوتهم في دوافع العداوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص600، تحت «دلالة التعبير بلفظ (أكثر) في السياق»","url":""}]},{"id":"s6-248","number":248,"surah":6,"verses":[38],"references":[{"surah":6,"verses":[38]}],"verseLabel":"الأنعام: 38","question":"ما دلالة اجتماع النفي و﴿من﴾ في قوله تعالى: ﴿وما من دابة في الأرض﴾؟","answer":"دخول ﴿من﴾ على النكرة في سياق النفي يفيد استغراق الجنس فردًا فردًا؛ فلا تخرج دابة واحدة من الحكم الآتي. فالصيغة أبلغ من ﴿وما دابة﴾ في تأكيد شمول علم الله وتدبيره لكل حي.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص607، تحت «دلالة ﴿من﴾ في قوله تعالى: ﴿وما من دابة﴾».","url":""}]},{"id":"s6-249","number":249,"surah":6,"verses":[38],"references":[{"surah":6,"verses":[38]}],"verseLabel":"الأنعام: 38","question":"ما دلالة تقييد الدابة بـ﴿في الأرض﴾ ووصف الطائر بأنه ﴿يطير﴾؟","answer":"خص كل صنف بحركته وحيزه المشاهد: الدابة تدب في الأرض، والطائر يتحرك في الجو. وفي الكلام احتباك؛ كأن التقدير: دابة تدب في الأرض، وطائر يطير في السماء، فحذف من كل جملة ما دل عليه مقابلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص609–610، تحت «بلاغة الاحتباك بين جملتي ﴿دابة في الأرض﴾ و﴿طائر يطير بجناحيه﴾»","url":""}]},{"id":"s6-250","number":250,"surah":6,"verses":[38],"references":[{"surah":6,"verses":[38]}],"verseLabel":"الأنعام: 38","question":"لماذا قيل: ﴿ولا طائر يطير﴾ بصيغة اسم الفاعل، ولم يقل: «ولا طير»؟","answer":"اسم الفاعل ﴿طائر﴾ يصور الطير حال مباشرته الطيران، فيقصر النظر على الحيوان المتصف بهذه الهيئة فعلًا، بخلاف لفظ «طير» الأعم في اسم الجنس.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص609، تحت عنوان «نكتة التعبير بصيغة اسم الفاعل ﴿طائر﴾ دون (طير)»","url":""}]},{"id":"s6-1123","number":1123,"surah":6,"verses":[38],"references":[{"surah":6,"verses":[38]}],"verseLabel":"الأنعام: 38","question":"ما فائدة تأكيد الطيران بقوله تعالى: ﴿يطير بجناحيه﴾؟","answer":"أكد حقيقة الطيران واستحضر هيئته المشاهدة، ودفع احتمال المجاز أو إطلاق الطائر على ما لا يطير بالفعل؛ فدل على الإحاطة بكل ما يطير على اختلاف أنواعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص610، تحت عنوان «نكتة تأكيد الطيران، بقوله ﴿يطير بجناحيه﴾»","url":""}]},{"id":"s6-251","number":251,"surah":6,"verses":[38],"references":[{"surah":6,"verses":[38]}],"verseLabel":"الأنعام: 38","question":"ما دلالة تقييد الطيران بقوله تعالى: ﴿بجناحيه﴾؟","answer":"في الباء وجهان: أن تكون للاستعانة، أي يطير مستعينًا بجناحيه، أو للحال المؤكدة، أي يطير حال كونه ذا جناحين؛ والقيد يرفع توهم المجاز لأن الطيران قد يستعار للسرعة، ويعين هيئة الطيران الحسي.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص610–611، تحت «معنى (الباء) في قوله تعالى: ﴿بجناحيه﴾»","url":""}]},{"id":"s6-252","number":252,"surah":6,"verses":[38],"references":[{"surah":6,"verses":[38]}],"verseLabel":"الأنعام: 38","question":"لماذا نُفي وجود الدواب بـ﴿ما﴾ في قوله: ﴿وما من دابة﴾، ونُفي الطير بـ﴿لا﴾ في قوله: ﴿ولا طائر﴾؟","answer":"ناسبت ﴿ما﴾ دخول ﴿من﴾ على النكرة لتوكيد استغراق جنس الدواب، أما ﴿لا﴾ فأكدت نفي خروج طائر متصف بالطيران بجناحيه من الحكم؛ فاختار كل تركيب ما يلائم بناؤه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص609، تحت عنوان «سر الاختلاف بين النفي بـ(ما)، والنفي بـ(لا)»","url":""}]},{"id":"s6-253","number":253,"surah":6,"verses":[38],"references":[{"surah":6,"verses":[38]}],"verseLabel":"الأنعام: 38","question":"ما التعريض في وصف الدواب والطير بأنهم ﴿أمم أمثالكم﴾؟","answer":"يعرض بالإنسان الذي ميز بالعقل ثم لم يعتبر؛ فهذه المخلوقات جماعات يجري عليها تدبير الله، وفي مساواتها له في الخضوع والتنظيم تذكير له بألا يخرج عن طاعة ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص611–612، تحت عنوان «بلاغة التعريض، في قوله تعالى: ﴿أمم أمثالكم﴾»","url":""}]},{"id":"s6-1124","number":1124,"surah":6,"verses":[38],"references":[{"surah":6,"verses":[38]}],"verseLabel":"الأنعام: 38","question":"في أي وجه شُبهت الدواب والطير بالناس في قوله تعالى: ﴿أمم أمثالكم﴾؟","answer":"المماثلة في كونها أجناسًا وجماعات لها نظم وآجال وأرزاق وأحوال يحيط الله بها ويدبرها، لا في جميع الصفات ولا في نوع التكليف الذي خُص به الإنسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص612، تحت عنوان «دلالة التشبيه، في قوله تعالى: ﴿أمم أمثالكم﴾»","url":""}]},{"id":"s6-254","number":254,"surah":6,"verses":[38],"references":[{"surah":6,"verses":[38]}],"verseLabel":"الأنعام: 38","question":"لماذا جاء الخبر جمعًا في قوله تعالى: ﴿إلا أمم أمثالكم﴾؟","answer":"لأن النكرتين ﴿دابة﴾ و﴿طائر﴾ في سياق النفي تستغرقان الأفراد والأنواع، فجاء جمع ﴿أمم﴾ مراعيًا هذا المعنى العام؛ فكل نوع أمة لها خصائصها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص611، تحت عنوان «دلالة التعبير بصيغة الجمع ﴿أمم﴾، دون الإفراد»","url":""}]},{"id":"s6-255","number":255,"surah":6,"verses":[38],"references":[{"surah":6,"verses":[38]}],"verseLabel":"الأنعام: 38","question":"ما دلالة قوله تعالى: ﴿ما فرطنا في الكتاب من شيء﴾، وما المراد بالكتاب؟","answer":"المعنى أن الكتاب لم يهمل شيئًا داخلًا في الغرض المقصود. والمراد به على قولٍ اللوح المحفوظ المشتمل على أحوال المخلوقات، وعلى قولٍ القرآن، أي إنه بيّن ما يحتاج إليه المكلف في الدين وأصول الهداية، لا أنه فصل جميع العلوم؛ وعلى القولين يفيد لفظ الكتاب توثيق المكتوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص613–614، تحت «دلالة التعبير بالكتاب عن اللوح المحفوظ أو القرآن»","url":""}]},{"id":"s6-256","number":256,"surah":6,"verses":[38],"references":[{"surah":6,"verses":[38]}],"verseLabel":"الأنعام: 38","question":"ما دلالة اختيار ﴿فرطنا﴾، دون: تركنا أو أغفلنا؟","answer":"التفريط تقصير يجاوز به الشيء قدر العناية الواجبة حتى يضيع ويفوت؛ فنفيه أبلغ من نفي مجرد الترك، لأنه ينزه الكتابة الإلهية عن النقص والإهمال والتضييع جميعًا. وقد فسره المصدر هنا بمعنى: ما أغفلنا ولا ضيعنا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص613، تحت «دلالة استعمال لفظ (فرط) دون ما يقاربها في الدلالة»","url":""}]},{"id":"s6-257","number":257,"surah":6,"verses":[38],"references":[{"surah":6,"verses":[38]}],"verseLabel":"الأنعام: 38","question":"ما دلالة قوله تعالى: ﴿من شيء﴾ بعد نفي التفريط؟","answer":"﴿من﴾ زائدة لتوكيد الاستغراق، و﴿شيء﴾ أعم النكرات؛ فاجتمعا بعد النفي لنفي أدنى فرد يمكن أن يتوهم خروجه من الكتاب. وبذلك يبلغ النص غاية الشمول من غير أن تكون العبارة حشوًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص612–613، تحت «سر النفي بـ(ما) ودخول ﴿من﴾ على ﴿شيء﴾»","url":""}]},{"id":"s6-258","number":258,"surah":6,"verses":[38],"references":[{"surah":6,"verses":[38]}],"verseLabel":"الأنعام: 38","question":"ما مناسبة ختم ذكر الحيوان بقوله تعالى: ﴿ثم إلى ربهم يحشرون﴾؟","answer":"أكمل به المماثلة في الخضوع للتدبير: كما كُتبت أحوالها في الدنيا فإنها تجمع إلى ربها، ويقتص لبعضها من بعض، ثم يصير أمرها إلى ما يشاء الله. والخاتمة دليل آخر على عموم القدرة، ورد على من أنكر حشر البشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص616، تحت «سر استعمال لفظ (الحشر) دون (الرجوع)»","url":""}]},{"id":"s6-259","number":259,"surah":6,"verses":[38],"references":[{"surah":6,"verses":[38]}],"verseLabel":"الأنعام: 38","question":"ما دلالة إضافة الرب إلى الحيوان في قوله تعالى: ﴿إلى ربهم﴾؟","answer":"أثبت أن الله رب هذه الأمم أيضًا: خلقها ورزقها ودبر أنواعها وأحوالها، فلا يخرج الحيوان عن رعايته وحكمه. والإضافة تمهد لحشرها إليه؛ فالذي رباها في الدنيا هو الذي يتولى أمرها في الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص615، تحت «دلالة إيثار عنوان الربوبية على الألوهية في قوله تعالى: ﴿إلى ربهم﴾»","url":""}]},{"id":"s6-260","number":260,"surah":6,"verses":[39],"references":[{"surah":6,"verses":[39]}],"verseLabel":"الأنعام: 39","question":"ما دلالة تصوير المكذبين بأنهم ﴿صم وبكم﴾ مع سلامة أسماعهم وألسنتهم؟","answer":"لما عطلوا السمع عن قبول الآيات واللسان عن النطق بالحق نُزلوا منزلة من فقد الحاستين حقيقةً. فالصمم والبكم استعارتان لموت الاستجابة، لا وصفان لخلقة أجسادهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص627–628، تحت «وجه حمل الوصفين ﴿صم وبكم﴾ على الاستعارة»","url":""}]},{"id":"s6-261","number":261,"surah":6,"verses":[39],"references":[{"surah":6,"verses":[39]}],"verseLabel":"الأنعام: 39","question":"ما دلالة حذف أداة التشبيه في وصفهم بـ﴿صم وبكم﴾؟","answer":"حذف الأداة والوجه فجاء التشبيه بليغًا، حتى كأنهم هم الصم والبكم لا مجرد مشابهين لهم؛ وذلك لشدة تعطيلهم أدوات الاهتداء. فالصيغة أثبتت الوصف فيهم وأقوت التوبيخ.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص627، تحت «بلاغة التشبيه في قوله تعالى: ﴿صم وبكم﴾»","url":""}]},{"id":"s6-262","number":262,"surah":6,"verses":[39],"references":[{"surah":6,"verses":[39]}],"verseLabel":"الأنعام: 39","question":"ما سرّ جمع ﴿الظلمات﴾ في قوله تعالى: ﴿في الظلمات﴾؟","answer":"جُمعت ﴿الظلمات﴾ للمبالغة في وصفهم بالعمى، ولمناسبة جمع الآيات التي كذبوا بها، وللدلالة على تعدد الظلمات التي غرقوا فيها: ظلمات الكفر والجهل والعناد، والظلمات النفسية والروحية والفكرية؛ فهي ظلمات ظاهرة وباطنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص626–627، تحت «نكتة جمع الظلمات في قوله تعالى: ﴿في الظلمات﴾»","url":""}]},{"id":"s6-263","number":263,"surah":6,"verses":[39],"references":[{"surah":6,"verses":[39]}],"verseLabel":"الأنعام: 39","question":"لماذا عُدل عن وصف المكذبين بالعمى إلى قوله تعالى: ﴿في الظلمات﴾؟","answer":"لأن الظلمات تصور البيئة التي تحيط بهم وتحجب عنهم طريق الهدى، وهي أبلغ من مجرد وصف العين بالعمى؛ إذ تجمع ظلمات الكفر والجهل والعناد.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص625–626، تحت عنوان «نكتة العدول عن وصف العمى إلى: ﴿الظلمات﴾»","url":""}]},{"id":"s6-1125","number":1125,"surah":6,"verses":[39],"references":[{"surah":6,"verses":[39]}],"verseLabel":"الأنعام: 39","question":"ما دلالة حرف الظرفية في قوله تعالى: ﴿في الظلمات﴾؟","answer":"صورهم منغمسين داخل الظلمات محاطين بها من كل جانب، حتى لا يجدوا منفذًا يبصرون منه الحق أو طريقًا يخرجون به من الضلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص626، تحت عنوان «دلالة حرف الظرفية في قوله تعالى: ﴿في الظلمات﴾»","url":""}]},{"id":"s6-264","number":264,"surah":6,"verses":[39],"references":[{"surah":6,"verses":[39]}],"verseLabel":"الأنعام: 39","question":"ما دلالة اختلاف التعبير بين ﴿يضلله﴾ و﴿يجعله على صراط مستقيم﴾؟","answer":"عُدل عن أن يقال في المقابل: يهده، إلى ﴿يجعله على صراط مستقيم﴾؛ لأن هذا التركيب أرسخ في بيان الهداية، وفيه مزيد مدح للمهتدين وتصوير لتمكينهم واستقرارهم على الطريق، بخلاف التعبير الموجز عن أهل الضلال بـ﴿يضلله﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص629–630، تحت «براعة اختلاف التعبير في التقابل اللفظي»","url":""}]},{"id":"s6-265","number":265,"surah":6,"verses":[39],"references":[{"surah":6,"verses":[39]}],"verseLabel":"الأنعام: 39","question":"لماذا قيل: ﴿يجعله على صراط مستقيم﴾ ولم يقل: «يهده»؟","answer":"الجعل يصور نقل الضال إلى حال جديدة مستقرة، كأنه وُضع على الطريق الواضح بعد التخبط في الظلمات؛ فيبرز أثر الهداية وتمكنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص629، تحت عنوان «دلالة اختيار لفظ ﴿يجعله﴾، دون (يهده)»","url":""}]},{"id":"s6-1126","number":1126,"surah":6,"verses":[39],"references":[{"surah":6,"verses":[39]}],"verseLabel":"الأنعام: 39","question":"ما دلالة حرف الاستعلاء في قوله تعالى: ﴿على صراط مستقيم﴾؟","answer":"يفيد تمكن المهتدي من طريق الهدى وثباته عليه، ويصور الصراط سبيلًا بينًا يستعلي عليه السائر ويمضي فيه على بصيرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص630، تحت عنوان «بلاغة استعمال حرف الاستعلاء»","url":""}]},{"id":"s6-266","number":266,"surah":6,"verses":[39],"references":[{"surah":6,"verses":[39]}],"verseLabel":"الأنعام: 39","question":"ماذا يضيف وصف ﴿مستقيم﴾ إلى الصراط في قوله: ﴿يجعله على صراط مستقيم﴾؟","answer":"ينفي عنه العوج والانحراف، فيطمئن السائر إلى وضوح وجهته وسلامة مسلكه. واستقامة الطريق تقرب الوصول إلى المقصود؛ فالوصف يصور الهداية طريقًا واضحًا لا يضل سالكه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص631، تحت «دلالة وصف ﴿صراط﴾ بلفظ ﴿مستقيم﴾»","url":""}]},{"id":"s6-267","number":267,"surah":6,"verses":[39],"references":[{"surah":6,"verses":[39]}],"verseLabel":"الأنعام: 39","question":"لم حذف مفعول المشيئة في قوله تعالى: ﴿من يشأ الله يضلله﴾؟","answer":"دل جواب الشرط على المحذوف، والتقدير: من يشأ الله إضلاله يضلله. وفي الحذف إيجاز، ومعه إبهام يعقبه بيان في الجواب، فيبعث السامع على التفكر ويشد انتباهه إلى ما تعلقت به المشيئة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص629، تحت «نكتة حذف مفعول المشيئة في ﴿من يشأ الله يضلله﴾»","url":""}]},{"id":"s6-268","number":268,"surah":6,"verses":[40],"references":[{"surah":6,"verses":[40]}],"verseLabel":"الأنعام: 40","question":"كيف يجعل تركيب ﴿قل أرأيتكم﴾ السؤال عن العذاب مواجهة حاضرة في نفوس المخاطبين؟","answer":"هو أسلوب يلفت المخاطب إلى أمر جدير بالتحقيق والتأمل، ويستحضر الحالة كأنها مرئية أمامه. فالسؤال يحملهم على تصور أنفسهم وقد نزل بهم العذاب، ثم يطلب منهم جوابًا تعرفه فطرتهم: من يدعون عندئذ؟","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص635–636، تحت «بلاغة تركيب ﴿أرأيتكم﴾»","url":""}]},{"id":"s6-269","number":269,"surah":6,"verses":[40],"references":[{"surah":6,"verses":[40]}],"verseLabel":"الأنعام: 40","question":"لماذا عُرّف العذاب في قوله تعالى: ﴿عذاب الله﴾ بالإضافة؟","answer":"إضافته إلى اسم الجلالة تعظم شأنه وتهول أثره؛ فهو عذاب صادر عمن لا تعجزه قوة ولا يستطيع أحد دفع ما يرسله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص637، تحت عنوان «فائدة تعريف ﴿عذاب الله﴾، بالإضافة دون (أل)»","url":""}]},{"id":"s6-1127","number":1127,"surah":6,"verses":[40],"references":[{"surah":6,"verses":[40]}],"verseLabel":"الأنعام: 40","question":"ما المجاز في قوله تعالى: ﴿إن أتاكم عذاب الله﴾؟","answer":"استعير الإتيان لحصول العذاب ووصوله إليهم، فصُور كقادم يقصدهم حتى يواجهوه ولا يجدوا مهربًا منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص637، تحت عنوان «بلاغة المجاز في لفظ ﴿أتاكم﴾»","url":""}]},{"id":"s6-270","number":270,"surah":6,"verses":[40],"references":[{"surah":6,"verses":[40]}],"verseLabel":"الأنعام: 40","question":"ما دلالة اختلاف الفعل بين ﴿أتاكم عذاب الله﴾ و﴿أتتكم الساعة﴾؟","answer":"أُعيد فعل الإتيان مع الساعة، مع إمكان عطفها على العامل الأول، لإظهار كل واحد من العذاب والساعة مستقلاً والاهتمام باستحضاره في النفس؛ وجاء كل فعل مطابقًا لفاعله، من غير فرق بينهما في تحقق الوقوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص638–639، تحت «نكتة تكرير ﴿أتتكم﴾ دون الاكتفاء بإتيان العذاب»","url":""}]},{"id":"s6-271","number":271,"surah":6,"verses":[40],"references":[{"surah":6,"verses":[40]}],"verseLabel":"الأنعام: 40","question":"ما دلالة العطف بـ﴿أو﴾ بين عذاب الله والساعة؟","answer":"جعلت كل حالة مستقلة كافية لاختبار فطرتهم: سواء نزل بهم عذاب عاجل أم فاجأتهم الساعة، فلن يجدوا من يدعونه حقًا إلا الله. فلا يلزم اجتماع الأمرين لتقوم الحجة على بطلان الشركاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص638، تحت «معنى حرف ﴿أو﴾ في الآية الكريمة»","url":""}]},{"id":"s6-272","number":272,"surah":6,"verses":[40],"references":[{"surah":6,"verses":[40]}],"verseLabel":"الأنعام: 40","question":"ما دلالة تقديم ﴿غير الله﴾ في قوله تعالى: ﴿أغير الله تدعون﴾؟","answer":"قدم المفعول للإنكار والقصر: أإلهًا غير الله تخصون بالدعاء عند انكشاف الضر؟ وتجربتهم نفسها تجيب بالنفي، لأن الشدة تسقط المعبودات المصطنعة وترد القلب إلى الله وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص639–640، تحت «سر تقديم ﴿أغير الله﴾ على فعل ﴿تدعون﴾»","url":""}]},{"id":"s6-273","number":273,"surah":6,"verses":[40],"references":[{"surah":6,"verses":[40]}],"verseLabel":"الأنعام: 40","question":"ما موقع قوله تعالى: ﴿إن كنتم صادقين﴾ مما قبله؟","answer":"جاء قيدًا يتحدى دعواهم أن آلهتهم شركاء ينفعون؛ فإن صدقوا فليدعُوها عند نزول العذاب أو قيام الساعة، والتجربة الفطرية تكشف أنهم لا يفعلون.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص640، تحت عنوان «موقع جملة ﴿إن كنتم صادقين﴾ مما قبلها»","url":""}]},{"id":"s6-1128","number":1128,"surah":6,"verses":[40],"references":[{"surah":6,"verses":[40]}],"verseLabel":"الأنعام: 40","question":"لماذا حُذف جواب الشرط في قوله تعالى: ﴿إن كنتم صادقين﴾؟","answer":"دل عليه الاستفهام السابق، أي فادعوا غير الله أو أخبروا أغير الله تدعون؛ وحذفه يوجز الكلام ويتركهم أمام الجواب الذي تلزمهم به فطرتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص641، تحت عنوان «حذف جواب جملة ﴿إن كنتم صادقين﴾»","url":""}]},{"id":"s6-274","number":274,"surah":6,"verses":[41],"references":[{"surah":6,"verses":[41]}],"verseLabel":"الأنعام: 41","question":"ما دلالة تولي الجواب في قوله تعالى: ﴿بل إياه تدعون﴾؟","answer":"أجاب عنهم لأن واقع الفطرة لا يسعهم إنكاره: عند الشدة يتركون الشركاء ويدعون الله. و﴿بل﴾ تبطل احتمال دعاء غيره الذي طرحه السؤال، ثم تثبت الحقيقة التي لا يملكون جوابًا سواها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص644، تحت «سر الإضراب بالحرف ﴿بل﴾ عن السؤال بالجواب عنه»","url":""}]},{"id":"s6-275","number":275,"surah":6,"verses":[41],"references":[{"surah":6,"verses":[41]}],"verseLabel":"الأنعام: 41","question":"ما دلالة تقديم ﴿إياه﴾ في قوله تعالى: ﴿بل إياه تدعون﴾؟","answer":"تقديم المفعول يفيد القصر الحقيقي: لا تدعون عند نزول الشدة إلا الله؛ فتتجه القلوب إلى القوة الخالقة المنجية وتغيب المعبودات المزعومة. فالتقديم يواجه الشرك بشهادة فطرتهم العملية.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص644، تحت «فائدة تقديم المفعول ﴿إياه﴾ على الفعل ﴿تدعون﴾»","url":""}]},{"id":"s6-276","number":276,"surah":6,"verses":[41],"references":[{"surah":6,"verses":[41]}],"verseLabel":"الأنعام: 41","question":"ما دلالة الفاء في قوله تعالى: ﴿فيكشف ما تدعون إليه﴾؟","answer":"رتبت كشف الضر على دعاء الله وحده، فصورت سرعة الإجابة حين تتعلق بها المشيئة، وأظهرت أن رجوعهم إليه هو السبب الظاهر في الانفراج.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص645، تحت عنوان «دلالة العطف بحرف الفاء في ﴿فيكشف﴾»","url":""}]},{"id":"s6-1129","number":1129,"surah":6,"verses":[41],"references":[{"surah":6,"verses":[41]}],"verseLabel":"الأنعام: 41","question":"لماذا عُبر عن إزالة الضر بالكشف في قوله تعالى: ﴿فيكشف ما تدعون إليه﴾؟","answer":"الكشف إزالة غطاء ساتر، فصور الضر شيئًا أحاط بهم وغطاهم ثم يرفعه الله؛ فتظهر شدة الإحاطة أولًا وتمام الانفراج بعدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص645، تحت عنوان «بلاغة استعمال فعل (يكشف)، دون ما يقاربه في المعنى»","url":""}]},{"id":"s6-277","number":277,"surah":6,"verses":[41],"references":[{"surah":6,"verses":[41]}],"verseLabel":"الأنعام: 41","question":"ما دلالة تعدية الدعاء بـ﴿إلى﴾ في قوله تعالى: ﴿ما تدعون إليه﴾؟","answer":"ضُمّن ﴿تدعون﴾ معنى تتضرعون؛ أي يكشف ما تدعون الله متضرعين إليه من أجله. فحرف الانتهاء يصور توجه الدعاء والافتقار إلى الله، وجمع التضمين في لفظ واحد معنى الدعاء ومعنى التضرع الخالص.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص646، تحت «بلاغة استعمال حرف (إلى) في قوله: ﴿تدعون إليه﴾»","url":""}]},{"id":"s6-278","number":278,"surah":6,"verses":[41],"references":[{"surah":6,"verses":[41]}],"verseLabel":"الأنعام: 41","question":"ما غرض تقييد كشف الضر بقوله تعالى: ﴿إن شاء﴾؟","answer":"ليبين أن الدعاء لا يوجب على الله شيئًا، وأن الكشف تابع لحكمته ومشيئته؛ فقد يكشف الضر وقد يبقيه لحكمة يعلمها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص646–647، تحت عنوان «غرض قيد ﴿إن شاء﴾»","url":""}]},{"id":"s6-1130","number":1130,"surah":6,"verses":[41],"references":[{"surah":6,"verses":[41]}],"verseLabel":"الأنعام: 41","question":"لماذا حُذف جواب الشرط في قوله تعالى: ﴿إن شاء﴾؟","answer":"دل عليه ما تقدم من فعل الكشف، أي إن شاء كشفه؛ فالحذف يجنب تكرار اللفظ ويركز على تعلق الفرج بالمشيئة الإلهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص647، تحت عنوان «دلالة حذف جواب الشرط ﴿إن شاء﴾»","url":""}]},{"id":"s6-279","number":279,"surah":6,"verses":[41],"references":[{"surah":6,"verses":[41]}],"verseLabel":"الأنعام: 41","question":"ما دلالة قوله تعالى: ﴿وتنسون ما تشركون﴾، وهل المراد النسيان الحقيقي؟","answer":"يحتمل النسيان الحقيقي؛ إذ تذهلهم الشدة عن أصنامهم وينشغلون بمن يملك كشفها، ويحتمل النسيان المجازي بمعنى الترك والإعراض. وكلا الوجهين يكشف أن المعبودات تغيب عن القلوب في الموضع الذي يُختبر فيه صدق الألوهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص647–648، تحت «دقة التعبير بفعل النسيان ﴿تنسون﴾»","url":""}]},{"id":"s6-280","number":280,"surah":6,"verses":[41],"references":[{"surah":6,"verses":[41]}],"verseLabel":"الأنعام: 41","question":"ما دلالة التعبير بـ﴿ما تشركون﴾، دون: مَن تشركون؟","answer":"﴿ما﴾ تعم كل ما أشركوه، وتنزل معبوداتهم منزلة غير العاقل تحقيرًا لها وإظهارًا لعجزها عن فهم الدعاء أو كشف الضر. فهي أوسع من ﴿من﴾ التي يغلب استعمالها في العقلاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص646، تحت «نكتة التعبير بـ﴿ما﴾ بدلًا من الاسم الموصول الظاهر»","url":""}]},{"id":"s6-281","number":281,"surah":6,"verses":[42],"references":[{"surah":6,"verses":[42]}],"verseLabel":"الأنعام: 42","question":"ما دلالة حذف المرسلين في قوله تعالى: ﴿ولقد أرسلنا إلى أمم من قبلك﴾؟","answer":"التقدير: أرسلنا رسلًا، وحذف المفعول لأن فعل الإرسال والسياق يدلان عليه. فاتجهت العناية إلى الأمم وموقفها من التكذيب والأخذ، وهو المقصود في مقام التهديد والوعيد، دون حاجة إلى تعيين الرسل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص651، تحت «نكتة حذف مفعول ﴿أرسلنا﴾».","url":""}]},{"id":"s6-282","number":282,"surah":6,"verses":[42],"references":[{"surah":6,"verses":[42]}],"verseLabel":"الأنعام: 42","question":"ما دلالة جمع ﴿أمم﴾ وتنكيرها؟","answer":"الجمع والتنكير يدلان على أمم كثيرة متنوعة تعاقبت قبل بعثة النبي ﷺ، فالسنة التي تذكرها الآية ليست حادثة منفردة. وفي عدم تسميتها توجيه النظر إلى القانون الجامع: إرسال، ثم ابتلاء، ثم موقف من التضرع.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص652، تحت «دلالة الجمع والتنكير في لفظ ﴿أمم﴾»","url":""}]},{"id":"s6-283","number":283,"surah":6,"verses":[42],"references":[{"surah":6,"verses":[42]}],"verseLabel":"الأنعام: 42","question":"ما دلالة تقديم ﴿إلى أمم﴾ على ﴿من قبلك﴾؟","answer":"جاء ﴿من قبلك﴾ وصفًا للأمم، فترتيبه بعد الموصوف مناسب لأصل التركيب. وفي البدء بـ﴿إلى أمم﴾ عناية بما سيخبر عنه من تاريخها وعاقبتها، ثم يصل القيد الزمني ذلك التاريخ برسالة النبي ﷺ، تسليةً له وإنذارًا لمعاصريه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص652–653، تحت «وجه تقديم ﴿إلى أمم﴾ على ﴿من قبلك﴾»","url":""}]},{"id":"s6-284","number":284,"surah":6,"verses":[42],"references":[{"surah":6,"verses":[42]}],"verseLabel":"الأنعام: 42","question":"ما دلالة توجيه الخطاب إلى النبي ﷺ في قوله تعالى: ﴿من قبلك﴾، دون: من قبلهم؟","answer":"بعد حذف مفعول ﴿أرسلنا﴾، أشارت إضافة ﴿قبل﴾ إلى ضمير النبي ﷺ إلى الرسل السابقين؛ فهو رسول جاء بعدهم وخاتم النبيين. وبذلك اتصل خبر الأمم السابقة برسالته، وفيه تسلية له وتثبيت.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص653، تحت «بلاغة الإشارة إلى المرسلين في قوله: ﴿قبلك﴾»","url":""}]},{"id":"s6-285","number":285,"surah":6,"verses":[42],"references":[{"surah":6,"verses":[42]}],"verseLabel":"الأنعام: 42","question":"ما نوع الفاء في قوله تعالى: ﴿فأخذناهم بالبأساء والضراء﴾؟","answer":"هي فاء فصيحة تكشف كلامًا مطويًا، أي أرسلنا إليهم الرسل فكذبوهم فأخذناهم؛ فربطت الأخذ بسبب التكذيب بعد قيام الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص653–654، تحت عنوان «نوع الفاء في قوله: ﴿فأخذناهم﴾»","url":""}]},{"id":"s6-1131","number":1131,"surah":6,"verses":[42],"references":[{"surah":6,"verses":[42]}],"verseLabel":"الأنعام: 42","question":"لماذا قيل: ﴿فأخذناهم﴾ دون «فعاقبناهم»؟","answer":"الأخذ يصور التمكن والإحاطة بهم تحت سلطان الشدة، وهو أنسب بابتلاء يراد منه الإيقاظ والتضرع؛ أما العقاب فيوحي ابتداءً بجزاء نهائي.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص654، تحت عنوان «سر استعمال لفظ ﴿فأخذناهم﴾، دون (فعاقبناهم)»","url":""}]},{"id":"s6-286","number":286,"surah":6,"verses":[42],"references":[{"surah":6,"verses":[42]}],"verseLabel":"الأنعام: 42","question":"ما نكتة ذكر البأساء والضراء متعلقًا للأخذ في قوله تعالى: ﴿فأخذناهم بالبأساء والضراء﴾؟","answer":"بين نوع الأخذ وأنه ابتلاء يمس أحوالهم وأبدانهم ليكسر الغفلة ويحملهم على التضرع، كما استوعب جهات الشدة التي توقظ الإنسان عادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص655، تحت عنوان «نكتة ذكر متعلق الأخذ، وهو البأساء والضراء»","url":""}]},{"id":"s6-1132","number":1132,"surah":6,"verses":[42],"references":[{"surah":6,"verses":[42]}],"verseLabel":"الأنعام: 42","question":"ما الفرق بين البأساء والبأس؟","answer":"البأساء تستعمل في شدة الحال والفقر وما يمس المال والمعاش، أما البأس فيكثر في القوة وشدة الحرب والعذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص659–660، تحت عنوان «البأساء والبأس»","url":""}]},{"id":"s6-1133","number":1133,"surah":6,"verses":[42],"references":[{"surah":6,"verses":[42]}],"verseLabel":"الأنعام: 42","question":"ما الفرق بين الضراء والضر؟","answer":"الضراء شدة تمس البدن كالمرض والوجع، أما الضر فأعم في كل أذى ونقص؛ فاختيرت الضراء هنا لمقابلة البأساء واستيعاب جهة البدن.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص660، تحت عنوان «الضراء والضر»","url":""}]},{"id":"s6-287","number":287,"surah":6,"verses":[42],"references":[{"surah":6,"verses":[42]}],"verseLabel":"الأنعام: 42","question":"ما دلالة ﴿لعلهم يتضرعون﴾ مع علم الله بما سيكون؟","answer":"ليست ﴿لعل﴾ للشك في علم الله، بل تبين الغاية التي من أجلها وقع الابتلاء، وتعرض التضرع نتيجةً مرجوة بحسب ما تقتضيه الأسباب ويعرفه المخاطبون. وفيها إبقاء باب الرجوع مفتوحًا لهم قبل حلول العقوبة القاطعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص656–657، تحت «دلالة حرف الترجي (لعل) في سياق الآية»","url":""}]},{"id":"s6-288","number":288,"surah":6,"verses":[43],"references":[{"surah":6,"verses":[43]}],"verseLabel":"الأنعام: 43","question":"ما دلالة ﴿لولا﴾ في قوله تعالى: ﴿فلولا إذ جاءهم بأسنا تضرعوا﴾؟","answer":"خرجت من أصل امتناع الشيء إلى التوبيخ والتحضيض: هلا تضرعوا حين جاءهم البأس؟ فهي تنكر عليهم ترك ما كان جديرًا أن يقع.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص662–663، تحت عنوان «دلالة حرف (لولا) بين النفي والتحضيض»","url":""}]},{"id":"s6-1134","number":1134,"surah":6,"verses":[43],"references":[{"surah":6,"verses":[43]}],"verseLabel":"الأنعام: 43","question":"لماذا قُدم قوله تعالى: ﴿إذ جاءهم بأسنا﴾ على ﴿تضرعوا﴾؟","answer":"لإبراز الظرف الذي كان يقتضي التضرع؛ فقد حضر سبب الانكسار ثم لم تقع نتيجته، فكان تقديمه أشد في التوبيخ والتعجيب من قسوتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص663–664، تحت عنوان «دلالة تقديم ﴿إذ جاءهم بأسنا﴾ على ﴿تضرعوا﴾»","url":""}]},{"id":"s6-289","number":289,"surah":6,"verses":[43],"references":[{"surah":6,"verses":[43]}],"verseLabel":"الأنعام: 43","question":"ما المجاز في قوله تعالى: ﴿جاءهم بأسنا﴾؟","answer":"استعير المجيء لوصول البأس وحلوله بهم، فصُور العذاب كقادم قصدهم حتى أحاط بهم، مما يشخص الشدة ويقرب مشهدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص664، تحت عنوان «بلاغة المجاز في قوله: ﴿جاءهم بأسنا﴾»","url":""}]},{"id":"s6-1135","number":1135,"surah":6,"verses":[43],"references":[{"surah":6,"verses":[43]}],"verseLabel":"الأنعام: 43","question":"ما دلالة إضافة البأس إلى ضمير العظمة في قوله تعالى: ﴿بأسنا﴾؟","answer":"تعظم البأس ببيان مصدره؛ فهو صادر عن قدرة الله التي لا تقاوم، وفي الإضافة تهويل لما نزل بهم وتنبيه إلى أنه لم يكن حادثًا عابرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص664، تحت عنوان «دلالة إضافة (البأس) إلى ضمير العظمة في ﴿بأسنا﴾»","url":""}]},{"id":"s6-290","number":290,"surah":6,"verses":[43],"references":[{"surah":6,"verses":[43]}],"verseLabel":"الأنعام: 43","question":"ما دلالة تكرار مادة التضرع بعد قوله تعالى: ﴿لعلهم يتضرعون﴾؟","answer":"تكرر لفظ التضرع للتأكيد على أن ما عولجوا بالبأساء والضراء لأجله هو رجوعهم إلى الله، وأن امتناعهم عنه عند مجيء البأس كان سبب النقمة ودليل كبرهم وكفرهم واستحقاقهم العذاب الشديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص664–665، تحت «دلالة تكرار لفظ ﴿تضرعوا﴾».","url":""}]},{"id":"s6-291","number":291,"surah":6,"verses":[43],"references":[{"surah":6,"verses":[43]}],"verseLabel":"الأنعام: 43","question":"ما دلالة الاستدراك بـ﴿ولكن﴾ في قوله تعالى: ﴿ولكن قست قلوبهم﴾؟","answer":"استدرك بها على النتيجة المنتظرة من البأس؛ فبدل أن تلين قلوبهم ويتضرعوا حالت القسوة بينهم وبين الانتفاع بالشدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص665–666، تحت عنوان «بلاغة استعمال حرف الاستدراك ﴿ولكن﴾ معطوفًا»","url":""}]},{"id":"s6-1136","number":1136,"surah":6,"verses":[43],"references":[{"surah":6,"verses":[43]}],"verseLabel":"الأنعام: 43","question":"ما الاستعارة في قوله تعالى: ﴿قست قلوبهم﴾؟","answer":"استعيرت صلابة الأجسام للقلوب التي لا تنفذ إليها الموعظة ولا تلين عند البلاء؛ فصورت غلظها المعنوي بصورة حجر لا يتأثر.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص666–667، تحت عنوان «بلاغة الاستعارة في لفظ ﴿قست﴾»","url":""}]},{"id":"s6-292","number":292,"surah":6,"verses":[43],"references":[{"surah":6,"verses":[43]}],"verseLabel":"الأنعام: 43","question":"ما دلالة الماضي في قوله تعالى: ﴿قست قلوبهم﴾؟","answer":"دل الماضي على تحقق القسوة وثبوتها قبل مجيء البأس، ولذلك بقيت القلوب على صلابتها حين طرأ الابتلاء فلم تنتفع به. فهو يسجل علةً راسخة لا انفعالًا عابرًا وقع بعد الشدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص667، تحت «دلالة المضي في ﴿قست﴾»","url":""}]},{"id":"s6-293","number":293,"surah":6,"verses":[43],"references":[{"surah":6,"verses":[43]}],"verseLabel":"الأنعام: 43","question":"ما دلالة عطف قوله تعالى: ﴿وزين لهم الشيطان﴾ على قسوة قلوبهم؟","answer":"جمع سببين لترك التضرع: قلوبًا لا تلين، وشيطانًا يجمل لها الباطل؛ فكان التزيين متممًا لبيان إصرارهم بعد نزول البأس.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص667–668، تحت عنوان «بلاغة عطف ﴿وزين لهم الشيطان﴾ على الجملة السابقة»","url":""}]},{"id":"s6-1137","number":1137,"surah":6,"verses":[43],"references":[{"surah":6,"verses":[43]}],"verseLabel":"الأنعام: 43","question":"لماذا اختير فعل ﴿زين﴾ في قوله تعالى: ﴿وزين لهم الشيطان﴾؟","answer":"لأنه يدل على إلباس القبيح صورة الحسن حتى تميل إليه النفس، فيكشف أن أعمالهم لم تتغير حقيقتها وإنما تغيرت صورتها في أعينهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص668، تحت عنوان «نكتة استعمال ﴿زين﴾ دون مرادفاتها»","url":""}]},{"id":"s6-1138","number":1138,"surah":6,"verses":[43],"references":[{"surah":6,"verses":[43]}],"verseLabel":"الأنعام: 43","question":"ما نكتة تقديم ﴿لهم﴾ في قوله تعالى: ﴿وزين لهم الشيطان﴾؟","answer":"قدم الجار والمجرور للعناية بحالهم والتنبيه إلى اختصاصهم بقبول هذا التزيين؛ إذ لم يستجب له من عصمه الإيمان والبصيرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص668، تحت عنوان «نكتة تقديم الجار والمجرور على المسند إليه»","url":""}]},{"id":"s6-1139","number":1139,"surah":6,"verses":[43],"references":[{"surah":6,"verses":[43]}],"verseLabel":"الأنعام: 43","question":"ما دلالة تعريف ﴿الشيطان﴾ في قوله تعالى: ﴿وزين لهم الشيطان﴾؟","answer":"يفيد الجنس، فيشمل كل متمرد يزين الباطل من شياطين الجن والإنس، مع استحضار رأس الشر المعروف بهذه الصفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص669، تحت عنوان «معنى التعريف في لفظ ﴿الشيطان﴾»","url":""}]},{"id":"s6-294","number":294,"surah":6,"verses":[43],"references":[{"surah":6,"verses":[43]}],"verseLabel":"الأنعام: 43","question":"ما دلالة ﴿ما﴾ في قوله تعالى: ﴿ما كانوا يعملون﴾؟","answer":"تحتمل المصدرية، فيكون المعنى تزيين عملهم على العموم، وتحتمل الموصولية، فيراد الشيء الذي اعتادوا عمله؛ وفي الوجهين يعم التزيين مسلكهم الباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص669، تحت عنوان «دلالة ﴿ما﴾ في قوله: ﴿ما كانوا يعملون﴾»","url":""}]},{"id":"s6-1140","number":1140,"surah":6,"verses":[43],"references":[{"surah":6,"verses":[43]}],"verseLabel":"الأنعام: 43","question":"لماذا قيل: ﴿يعملون﴾ دون «يفعلون» أو «يصنعون»؟","answer":"العمل أعم في السلوك المكتسب المتكرر، بخلاف الصنع الذي يغلب فيه الإتقان والحرفة، والفعل الذي يصدق على مجرد وقوع الحدث؛ فناسب أعمال عامة المكلفين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص669–670، تحت عنوان «دلالة استعمال فعل ﴿يعملون﴾ دون (يفعلون) أو (يصنعون)»","url":""}]},{"id":"s6-295","number":295,"surah":6,"verses":[44],"references":[{"surah":6,"verses":[44]}],"verseLabel":"الأنعام: 44","question":"ما أثر الفاء الفصيحة في قوله تعالى: ﴿فلما نسوا ما ذكروا به﴾؟","answer":"أفصحت عن كلام محذوف دل عليه السياق، أي ذُكروا وحُذروا فلم ينتفعوا، ثم ربطت إعراضهم بما تلاه من فتح أبواب النعم استدراجًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص673، تحت عنوان «أثر الفاء الفصيحة في تقدير المحذوف في قوله: ﴿فلما نسوا﴾»","url":""}]},{"id":"s6-1141","number":1141,"surah":6,"verses":[44],"references":[{"surah":6,"verses":[44]}],"verseLabel":"الأنعام: 44","question":"ما المجاز في استعمال النسيان في قوله تعالى: ﴿نسوا ما ذكروا به﴾؟","answer":"أطلق النسيان وأريد الترك والإعراض المتعمد؛ لأنهم عاملوا التذكير معاملة الشيء المنسي الذي لا يلتفت إليه، مع قيام الحجة في نفوسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص674، تحت عنوان «بلاغة المجاز المرسل في استعمال مادة النسيان»","url":""}]},{"id":"s6-296","number":296,"surah":6,"verses":[44],"references":[{"surah":6,"verses":[44]}],"verseLabel":"الأنعام: 44","question":"ما دلالة بناء ﴿ذُكّروا به﴾ للمفعول؟","answer":"بُني الفعل للمفعول للاهتمام بما ذُكِّروا به، لا بتعيين من ذكّرهم؛ فالمقصود أنهم أغفلوا مضمون الدعوة، وفي ذلك تأكيد استقلال الرسالة ورفعة مكانتها وأن قيمتها لذاتها لا لشخص المبلّغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص675، تحت «دلالة بناء فعل ﴿ذُكّروا﴾ للمفعول، وتعديته بحرف الباء».","url":""}]},{"id":"s6-297","number":297,"surah":6,"verses":[44],"references":[{"surah":6,"verses":[44]}],"verseLabel":"الأنعام: 44","question":"لماذا قيل: ﴿فتحنا عليهم أبواب كل شيء﴾ دون «بسطنا عليهم» أو «رزقناهم»؟","answer":"الفتح يصور النعم كأبواب مغلقة أزيلت حواجزها فتدفقت عليهم من جهات كثيرة، وهو أبلغ في السعة والتتابع من مجرد البسط أو الرزق.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص675–676، تحت عنوان «براعة استعمال ﴿فتحنا﴾ دون (بسطنا عليهم) أو (رزقناهم)»","url":""}]},{"id":"s6-298","number":298,"surah":6,"verses":[44],"references":[{"surah":6,"verses":[44]}],"verseLabel":"الأنعام: 44","question":"ما دلالة تعدية الفتح بـ﴿على﴾ في قوله تعالى: ﴿فتحنا عليهم﴾، دون: فتحنا لهم؟","answer":"اختيرت ﴿على﴾ لتصوير إقبال الدنيا عليهم من جميع أقطارها بألوان النعم، وللإشعار باستعلاء الفاتح وتمكنه؛ وكان ظاهر الفتح امتنانًا يدعو إلى الشكر، لكنهم حولوه بإعراضهم إلى استدراج.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص676، تحت «بلاغة تعدية ﴿فتحنا﴾ بحرف الاستعلاء ﴿عليهم﴾ دون اللام».","url":""}]},{"id":"s6-299","number":299,"surah":6,"verses":[44],"references":[{"surah":6,"verses":[44]}],"verseLabel":"الأنعام: 44","question":"ما دلالة جمع ﴿أبواب﴾ في قوله تعالى: ﴿فتحنا عليهم أبواب كل شيء﴾؟","answer":"يدل الجمع على تعدد جهات النعم والخيرات وتتابعها عليهم، فكأن لكل نوع منها بابًا فتح حتى اتسعت عليهم الدنيا من وجوه كثيرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص677، تحت عنوان «دلالة جمع أبواب المضافة لمضاف»","url":""}]},{"id":"s6-1142","number":1142,"surah":6,"verses":[44],"references":[{"surah":6,"verses":[44]}],"verseLabel":"الأنعام: 44","question":"كيف يُفهم عموم ﴿كل شيء﴾ في قوله تعالى: ﴿أبواب كل شيء﴾؟","answer":"العموم مقيد بالسياق، أي كل شيء من النعم التي يرغبون فيها وتصلح لاستدراجهم، لا كل موجود على الإطلاق؛ فالسياق يحدد دائرة اللفظ.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص677، تحت عنوان «بلاغة التخصيص السياقي في ﴿أبواب كل شيء﴾»","url":""}]},{"id":"s6-300","number":300,"surah":6,"verses":[44],"references":[{"surah":6,"verses":[44]}],"verseLabel":"الأنعام: 44","question":"ما دلالة اجتماع ﴿حتى﴾ مع ﴿إذا﴾ في قوله تعالى: ﴿حتى إذا فرحوا﴾؟","answer":"جعلت ﴿حتى﴾ فرحهم غاية للإمهال وفتح النعم، ثم صورت ﴿إذا﴾ لحظة بلوغ تلك الغاية وانتقالهم المفاجئ إلى الأخذ.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص678، تحت عنوان «دلالة اجتماع (حتى) مع (إذا)، في ﴿حتى إذا﴾»","url":""}]},{"id":"s6-1143","number":1143,"surah":6,"verses":[44],"references":[{"surah":6,"verses":[44]}],"verseLabel":"الأنعام: 44","question":"كيف دل لفظ ﴿فرحوا﴾ على تحقق مقصود فتح الأبواب؟","answer":"كشف فرح البطر أنهم اطمأنوا إلى النعم وغفلوا عن المنعم والتحذير، فبلغ الاستدراج غايته وصار الأخذ عند شدة أمنهم أوقع.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص678، تحت عنوان «دلالة لفظ ﴿فرحوا﴾ على تحقق مقصود فتح الأبواب»","url":""}]},{"id":"s6-1144","number":1144,"surah":6,"verses":[44],"references":[{"surah":6,"verses":[44]}],"verseLabel":"الأنعام: 44","question":"ما سر التعبير بالماضي في قوله تعالى: ﴿فرحوا بما أوتوا﴾؟","answer":"صور بلوغ الفرح وتحققه منهم كمرحلة مكتملة قبل الأخذ، فثبتت عليهم حال البطر التي استحقوا عندها المباغتة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص678–679، تحت عنوان «سر التعبير بصيغة الماضي ﴿فرحوا﴾»","url":""}]},{"id":"s6-301","number":301,"surah":6,"verses":[44],"references":[{"surah":6,"verses":[44]}],"verseLabel":"الأنعام: 44","question":"لماذا بُني ﴿أوتوا﴾ للمجهول مع أن المعطي هو الله؟","answer":"بُني ﴿أوتوا﴾ للمجهول تصويرًا لنظرتهم إلى النعم مقطوعة عن واهبها؛ كأنهم تلقوها باستحقاقهم أو علمهم، فدل التعبير على كمال إعراضهم ونسيانهم أن الله هو الذي ابتلاهم بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص679، تحت «بلاغة التعبير عن فتح الأبواب ﴿بما أوتوا﴾»","url":""}]},{"id":"s6-302","number":302,"surah":6,"verses":[44],"references":[{"surah":6,"verses":[44]}],"verseLabel":"الأنعام: 44","question":"ما دلالة إسناد الأخذ إلى ضمير العظمة في قوله تعالى: ﴿أخذناهم﴾؟","answer":"يعظم الأخذ ببيان أنه صادر عن قدرة الله القاهرة، فيصور تمام التمكن منهم واستحالة إفلاتهم بعد طول الإمهال.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص679، تحت عنوان «دلالة فعل الأخذ المسند إلى ضمير العظمة»","url":""}]},{"id":"s6-1145","number":1145,"surah":6,"verses":[44],"references":[{"surah":6,"verses":[44]}],"verseLabel":"الأنعام: 44","question":"لماذا حُذف متعلق فعل الأخذ في قوله تعالى: ﴿أخذناهم بغتة﴾؟","answer":"أطلق الأخذ من غير تقييده بنوع عذاب ليشمل كل ما يتصور من العقوبة والاستئصال، وليذهب ذهن السامع في تهويله كل مذهب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص679–680، تحت عنوان «دلالة حذف متعلق فعل (أخذنا)»","url":""}]},{"id":"s6-1146","number":1146,"surah":6,"verses":[44],"references":[{"surah":6,"verses":[44]}],"verseLabel":"الأنعام: 44","question":"لماذا قيل: ﴿بغتة﴾ دون «فجأة»؟","answer":"البغتة تجمع سرعة الوقوع وخفاء مقدماته مع عدم الاستعداد له، أما المفاجأة فقد تقع بعد أمارات؛ فكانت أبلغ في تصوير أخذهم وهم آمنون.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص680، تحت عنوان «نكتة استعمال ﴿بغتة﴾ دون فجأة»","url":""}]},{"id":"s6-303","number":303,"surah":6,"verses":[44],"references":[{"surah":6,"verses":[44]}],"verseLabel":"الأنعام: 44","question":"ما سرّ التعبير في قوله تعالى: ﴿فإذا هم مبلسون﴾ بالجملة الاسمية؟","answer":"الجملة الاسمية في ﴿فإذا هم مبلسون﴾ تثبت عليهم حال الإبلاس وتصور استقرارها عقب الأخذ؛ انتقلوا في لحظة من فرح البطر إلى حيرة ويأس لا يجدون منه مخرجًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص681، تحت «دلالة التعبير بالجملة الاسمية ﴿هم مبلسون﴾»","url":""}]},{"id":"s6-304","number":304,"surah":6,"verses":[44],"references":[{"surah":6,"verses":[44]}],"verseLabel":"الأنعام: 44","question":"لماذا اختير لفظ ﴿مبلسون﴾، لا: يائسون؟","answer":"الإبلاس أخص من مجرد اليأس؛ فهو يأس يصحبه تحير وانقطاع حجة وسكوت من شدة الصدمة. لذلك صورت ﴿مبلسون﴾ ما أحدثته الأخذة المفاجئة في ظاهرهم وباطنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص680–681، تحت «سر استعمال ﴿مبلسون﴾ دون ما يقاربها في المعنى»","url":""}]},{"id":"s6-305","number":305,"surah":6,"verses":[45],"references":[{"surah":6,"verses":[45]}],"verseLabel":"الأنعام: 45","question":"لماذا عبّر عن استئصالهم بقوله: ﴿فقطع دابر القوم﴾؟","answer":"الدابر آخر القوم ومن يأتي في أثرهم، وقطعه كناية عن الاستئصال الكامل؛ فلم يُهلك بعضهم ويُبق بعضًا، بل انقطع امتدادهم وآثار ظلمهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص687، تحت «بلاغة الكناية عن الاستئصال بقطع الدابر»","url":""}]},{"id":"s6-306","number":306,"surah":6,"verses":[45],"references":[{"surah":6,"verses":[45]}],"verseLabel":"الأنعام: 45","question":"ما دلالة إيثار الاسم الموصول في قوله تعالى: ﴿القوم الذين ظلموا﴾؟","answer":"جعلت الصلة علة قطع دابرهم، فليس الاستئصال لمجرد ذواتهم وإنما لما تحقق فيهم من الظلم واستمروا عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص688، تحت عنوان «دلالة إيثار التعبير بالموصول»","url":""}]},{"id":"s6-1147","number":1147,"surah":6,"verses":[45],"references":[{"surah":6,"verses":[45]}],"verseLabel":"الأنعام: 45","question":"لماذا عُبر عنهم بلفظ ﴿القوم﴾ في قوله تعالى: ﴿القوم الذين ظلموا﴾؟","answer":"استوعب اللفظ جماعتهم الذين تمالؤوا على الظلم، وأظهر أنهم صاروا فريقًا متصفًا به فاستحقوا عاقبة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص690، تحت عنوان «علة التعبير بلفظ القوم»","url":""}]},{"id":"s6-307","number":307,"surah":6,"verses":[45],"references":[{"surah":6,"verses":[45]}],"verseLabel":"الأنعام: 45","question":"لماذا عُدل عن وصفهم بالكفر إلى ﴿الذين ظلموا﴾؟","answer":"الظلم أعم من الكفر؛ فهو يشمل الشرك وتكذيب الآيات والمعاصي ووضع الأشياء في غير مواضعها. فالوصف يجمع وجوه جرمهم ويبين أن الهلاك جزاء ظلمهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص690–691، تحت «دلالة اختيار الوصف بالظلم دون الكفر»","url":""}]},{"id":"s6-308","number":308,"surah":6,"verses":[45],"references":[{"surah":6,"verses":[45]}],"verseLabel":"الأنعام: 45","question":"لماذا عُطف الحمد على هلاك الظالمين: ﴿والحمد لله رب العالمين﴾؟","answer":"عُقِّب هلاك الظالمين بالحمد لأن قطع دابرهم نعمة تستوجب الشكر؛ ففيه نجاة الرسل والمؤمنين، وكفاية شر الظالمين، وتخليص الأرض من فسادهم، وإنجاز وعد الله بالنصر وإعلاء كلمة الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص691–692، تحت «فائدة التعقيب بالحمد على إهلاك الظالمين»","url":""}]},{"id":"s6-309","number":309,"surah":6,"verses":[45],"references":[{"surah":6,"verses":[45]}],"verseLabel":"الأنعام: 45","question":"ما سر وصف الله بـ﴿رب العالمين﴾ بعد ذكر استئصال الظالمين؟","answer":"لأن قطع دابرهم بعد تنوع الابتلاء من مقتضى تدبير الربوبية وحكمتها، وفي زوالهم رحمة بالعالمين تستوجب الحمد.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص693، تحت عنوان «سر الوصف بـ﴿رب العالمين﴾ بعد ذكر العذاب»","url":""}]},{"id":"s6-1148","number":1148,"surah":6,"verses":[45],"references":[{"surah":6,"verses":[45]}],"verseLabel":"الأنعام: 45","question":"لماذا قيل: ﴿رب العالمين﴾ دون «رب الناس»؟","answer":"لأن الحمد على عدله ورحمته لا يختص بالناس، بل يشمل جميع الأجناس والعوالم التي تنتفع بزوال الفساد والظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص693، تحت عنوان «علة التعبير بـ﴿رب العالمين﴾ دون (رب الناس)»","url":""}]},{"id":"s6-310","number":310,"surah":6,"verses":[46],"references":[{"surah":6,"verses":[46]}],"verseLabel":"الأنعام: 46","question":"ما سرّ التعبير في قوله تعالى: ﴿إن أخذ الله سمعكم وأبصاركم﴾، فعبّر عن سلب الحواس بالأخذ؟","answer":"الأخذ يصور السمع والأبصار نعمًا في ملك الله، متى شاء قبضها وسلب الانتفاع بها؛ فيوقظ الإنسان إلى أنه لا يملك حواسه استقلالًا ولا يستطيع ردها إذا أخذها الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص697، تحت «دلالة التعبير بالأخذ دون السلب».","url":""}]},{"id":"s6-311","number":311,"surah":6,"verses":[46],"references":[{"surah":6,"verses":[46]}],"verseLabel":"الأنعام: 46","question":"لماذا أُفرد ﴿سمعكم﴾ وجُمعت ﴿أبصاركم﴾؟","answer":"أُفرد السمع لأنه مصدر يدل على الجنس، ولأن المسموع الواحد يصل إلى جماعة من جهة واحدة؛ وجُمعت الأبصار لتعدد العيون وجهات النظر والمدركات المرئية باختلاف الأشخاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص698، تحت «السر في إفراد السمع وجمع الأبصار».","url":""}]},{"id":"s6-312","number":312,"surah":6,"verses":[46],"references":[{"surah":6,"verses":[46]}],"verseLabel":"الأنعام: 46","question":"لماذا أُسند الأخذ إلى السمع والبصر دون القلب؟","answer":"لأن سلب السمع والبصر يبقي أصل التكليف قائمًا، أما القلب فهو مناط العقل؛ فناسب أن يفرض أخذ الحاستين مع إبقاء القلب موجودًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص697، تحت عنوان «نكتة إسناد الأخذ للسمع والبصر دون القلب»","url":""}]},{"id":"s6-1149","number":1149,"surah":6,"verses":[46],"references":[{"surah":6,"verses":[46]}],"verseLabel":"الأنعام: 46","question":"ما دلالة إسناد الختم إلى القلوب في قوله تعالى: ﴿وختم على قلوبكم﴾؟","answer":"الختم يصور منع الحق من النفاذ إليها مع بقائها، فلا تعقل الدليل ولا تنتفع به؛ وبذلك يستمر التكليف وتظهر شدة الحرمان من الهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص697–698، تحت عنوان «دلالة إسناد الختم على القلوب»","url":""}]},{"id":"s6-313","number":313,"surah":6,"verses":[46],"references":[{"surah":6,"verses":[46]}],"verseLabel":"الأنعام: 46","question":"لم استعمل ﴿وختم على قلوبكم﴾ هنا بدل الطبع على القلوب؟","answer":"جاء الختم ملائمًا للتهديد والتخويف؛ فهو يصور المنع من نفاذ الحق، من غير أن يقتضي وحده ثبات ذلك المنع ولزومه كما يفيده الطبع في هذا الفرق. فالسياق يحذرهم مما قد يحل بهم ليبقى باب الرجوع حاضرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص699–700، تحت «نكتة إيثار الختم على الطبع»","url":""}]},{"id":"s6-314","number":314,"surah":6,"verses":[46],"references":[{"surah":6,"verses":[46]}],"verseLabel":"الأنعام: 46","question":"ما سرّ التعبير في قوله تعالى: ﴿من إله غير الله يأتيكم به﴾؛ وإلى ماذا يعود ضمير ﴿به﴾ مع تعدد المذكورات؟","answer":"يجوز أن يعود ﴿به﴾ إلى المأخوذ المفهوم من الكلام، فيجمع السمع والبصر وإدراك القلب في معنى واحد، أو أن يجري مجرى الإشارة إلى المذكور كله. وقيل يعود إلى السمع وحده، فتوافقه الباء في الإفراد؛ وكل وجه يرد القدرة على إعادة النعمة إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص700–701، تحت «علة إفراد الضمير ومرجعه جمع»","url":""}]},{"id":"s6-315","number":315,"surah":6,"verses":[46],"references":[{"surah":6,"verses":[46]}],"verseLabel":"الأنعام: 46","question":"لماذا قيل: ﴿من إله غير الله يأتيكم به﴾ بطريق الاستفهام بدل النفي الصريح؟","answer":"الاستفهام الإنكاري يلزمهم أن يجيبوا بأن لا إله غير الله يرد السمع والبصر ويفتح القلوب؛ فيصبح إقرارهم نفسه حجة على بطلان شركهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص701، تحت عنوان «سر إيثار النفي والإنكار بالاستفهام دون النفي الصريح»","url":""}]},{"id":"s6-316","number":316,"surah":6,"verses":[46],"references":[{"surah":6,"verses":[46]}],"verseLabel":"الأنعام: 46","question":"ما دلالة الأمر بالنظر في قوله تعالى: ﴿انظر كيف نصرف الآيات﴾؟","answer":"يوجه إلى تأمل كيفية تنويع الحجج، لا إلى مجرد رؤيتها؛ وفيه تعجيب من وضوحها ومن استمرار الإعراض عنها مع ذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص703، تحت عنوان «دلالة الأمر بالنظر إلى كيفية التصريف»","url":""}]},{"id":"s6-1150","number":1150,"surah":6,"verses":[46],"references":[{"surah":6,"verses":[46]}],"verseLabel":"الأنعام: 46","question":"ما فائدة تصريف الآيات في قوله تعالى: ﴿نصرف الآيات﴾؟","answer":"التصريف تنويع الدلائل والأساليب وتكرارها بين ترغيب وترهيب ونعمة ونقمة، لتقوم الحجة وتناسب تفاوت مدارك المخاطبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص704، تحت عنوان «فائدة تصريف الآيات في قوله: ﴿نصرف الآيات﴾»","url":""}]},{"id":"s6-317","number":317,"surah":6,"verses":[46],"references":[{"surah":6,"verses":[46]}],"verseLabel":"الأنعام: 46","question":"ما دلالة عطف قوله تعالى: ﴿ثم هم يصدفون﴾ على تصريف الآيات؟","answer":"كشف العطف النتيجة المستغربة: تتنوع لهم الآيات وتوضح، ثم يقابلون هذا البيان بالإعراض؛ فاشتد التفاوت بين المقدم والنتيجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص704، تحت عنوان «دلالة عطف قوله: ﴿ثم هم يصدفون﴾»","url":""}]},{"id":"s6-1151","number":1151,"surah":6,"verses":[46],"references":[{"surah":6,"verses":[46]}],"verseLabel":"الأنعام: 46","question":"لماذا عُطف قوله تعالى: ﴿ثم هم يصدفون﴾ بـ﴿ثم﴾؟","answer":"أفادت الاستبعاد والتعجيب من صدوفهم بعد وضوح الآيات، فالبعد معنوي بين ما يقتضيه البيان من قبول وما وقع منهم من إعراض.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص704–705، تحت عنوان «إيثار التعبير بحرف العطف ﴿ثم﴾»","url":""}]},{"id":"s6-318","number":318,"surah":6,"verses":[46],"references":[{"surah":6,"verses":[46]}],"verseLabel":"الأنعام: 46","question":"لماذا أظهر الضمير ﴿هم﴾ في ﴿ثم هم يصدفون﴾؟","answer":"إظهار ﴿هم﴾ يقوي إسناد الصدوف إليهم ويخصهم به؛ فالآيات صُرفت ووضحت، وهم أنفسهم الذين اختاروا الانصراف عنها، وفيه تقريع وتعجيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص705، تحت «بلاغة التعبير عن إعراضهم بالجملة الاسمية»","url":""}]},{"id":"s6-319","number":319,"surah":6,"verses":[46],"references":[{"surah":6,"verses":[46]}],"verseLabel":"الأنعام: 46","question":"لماذا اختير ﴿يصدفون﴾، لا: يعرضون؟","answer":"الصدوف إعراض مع ميل وانصراف عن الشيء، فهو يصور حركة المتولي بجانبه بعد أن تبين له وجه الحق؛ لذلك كان أبلغ من مطلق الإعراض.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص705–706، تحت «(يعرضون) و(يصدفون)»","url":""}]},{"id":"s6-320","number":320,"surah":6,"verses":[47],"references":[{"surah":6,"verses":[47]}],"verseLabel":"الأنعام: 47","question":"لم قيل في الوعيد بالعذاب: ﴿قل أرأيتكم﴾، بعد قوله في سلب الحواس: ﴿قل أرأيتم﴾؟","answer":"زادت كاف الخطاب توكيد المواجهة والتنبيه؛ فالوعيد هنا بعذاب أشد من سلب السمع والبصر، فناسبه مزيد تأكيد. أما في فرض سلب الحواس فاكتفي بالخطاب في ﴿أرأيتم﴾، فجاء اختلاف الصياغة موافقًا لدرجة التهديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص709، تحت «دلالة كاف الخطاب»","url":""}]},{"id":"s6-321","number":321,"surah":6,"verses":[47],"references":[{"surah":6,"verses":[47]}],"verseLabel":"الأنعام: 47","question":"ما دلالة الجمع بين ﴿بغتة﴾ و﴿جهرة﴾ في وصف مجيء العذاب؟","answer":"استوعب حالتي مجيئه: أن يفجأهم خفي المقدمات، أو يأتيهم ظاهرًا يعاينون أماراته؛ فلا نجاة لهم في أي صورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص710، تحت عنوان «دلالة الجمع بين البغتة والجهرة»","url":""}]},{"id":"s6-1152","number":1152,"surah":6,"verses":[47],"references":[{"surah":6,"verses":[47]}],"verseLabel":"الأنعام: 47","question":"ما سر المقابلة بين البغتة والجهرة؟","answer":"قابل خفاء المجيء بظهوره ليحيط بطرفي الاحتمال ويقرر أن اختلاف طريقة نزول العذاب لا يغير مصير الظالمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص711، تحت عنوان «سر المقابلة بين البغتة والجهرة»","url":""}]},{"id":"s6-322","number":322,"surah":6,"verses":[47],"references":[{"surah":6,"verses":[47]}],"verseLabel":"الأنعام: 47","question":"ما الغرض البلاغي من الاستفهام في قوله تعالى: ﴿هل يهلك إلا القوم الظالمون﴾؟","answer":"هو استفهام تقريري إنكاري يلزمهم بالإقرار بأن الهلاك عقوبة للظالمين، ويحمل في الوقت نفسه تحذيرًا لهم من البقاء على ظلمهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص711–712، تحت عنوان «بلاغة الاستفهام في الآية»","url":""}]},{"id":"s6-1153","number":1153,"surah":6,"verses":[47],"references":[{"surah":6,"verses":[47]}],"verseLabel":"الأنعام: 47","question":"لماذا عُبر بالاستفهام عن النفي في قوله تعالى: ﴿هل يهلك إلا القوم الظالمون﴾؟","answer":"لأن الاستفهام يجعل المخاطب يشارك في تقرير الجواب، فيكون إقراره بأن غير الظالم لا يهلك أوقع عليه من مجرد إخباره بذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص712، تحت عنوان «فائدة التعبير بالاستفهام عن النفي»","url":""}]},{"id":"s6-1154","number":1154,"surah":6,"verses":[47],"references":[{"surah":6,"verses":[47]}],"verseLabel":"الأنعام: 47","question":"كيف خُص الهلاك بالظالمين مع أن البلاء قد يصيب غيرهم؟","answer":"المراد هلاك العقوبة والخسران؛ فما يصيب المؤمن من بلاء يكون رفعة أو اختبارًا، أما الظالم فيصيبه وبالًا جزاءً على ظلمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص713–714، تحت عنوان «وجه تخصيص العذاب بالظالمين»","url":""}]},{"id":"s6-323","number":323,"surah":6,"verses":[47],"references":[{"surah":6,"verses":[47]}],"verseLabel":"الأنعام: 47","question":"ما بلاغة العدول من الضمير إلى الاسم الظاهر في قوله تعالى: ﴿القوم الظالمون﴾؟","answer":"عدل عن «أنتم» أو «هم» إلى الاسم الظاهر ليعمم الحكم ويجعله قاعدة تشمل كل قوم تحقق فيهم الظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص713، تحت عنوان «بلاغة العدول من الإضمار إلى الإظهار»","url":""}]},{"id":"s6-1155","number":1155,"surah":6,"verses":[47],"references":[{"surah":6,"verses":[47]}],"verseLabel":"الأنعام: 47","question":"لماذا وُصف القوم بالظلم بدل الاكتفاء بضميرهم؟","answer":"ليصرح بعلة الهلاك؛ فوصف الظلم يسجل سبب العقوبة عليهم وينبه المخاطبين إلى طريق النجاة منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص713، تحت عنوان «سر التعبير بالوصف دون الضمير»","url":""}]},{"id":"s6-324","number":324,"surah":6,"verses":[48],"references":[{"surah":6,"verses":[48]}],"verseLabel":"الأنعام: 48","question":"ما دلالة القصر في قوله تعالى: ﴿وما نرسل المرسلين إلا مبشرين ومنذرين﴾؟","answer":"قصر وظيفتهم في البلاغ الذي يجمع البشارة والإنذار، فرد مطالبة المعاندين لهم بما ليس من شأن الرسالة كإنزال العذاب المقترح.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص717، تحت عنوان «دلالة القصر في الآية»","url":""}]},{"id":"s6-1156","number":1156,"surah":6,"verses":[48],"references":[{"surah":6,"verses":[48]}],"verseLabel":"الأنعام: 48","question":"لماذا وُصف الرسل بالمبشرين والمنذرين؟","answer":"لأن الدعوة تستجمع ترغيب المطيع في الوعد وتحذير العاصي من الوعيد، فتقيم الحجة وتفتح للإنسان طريق الاختيار.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص718، تحت عنوان «علة وصف الرسل بالبشارة والإنذار»","url":""}]},{"id":"s6-325","number":325,"surah":6,"verses":[48],"references":[{"surah":6,"verses":[48]}],"verseLabel":"الأنعام: 48","question":"ما سرّ تقديم التبشير على الإنذار؟","answer":"قُدمت البشارة لإظهار حرص الرسل على إيمان من يدعونهم، وتقديم الأدلة لهم، وتعريفهم بما أعده الله من الثواب؛ وفي ذلك تعليم للدعاة أن يبدؤوا بالبشارة قبل النذارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص719، تحت «القصد إلى البشارة قبل النذارة دعوة لتوقيتها شرعة»","url":""}]},{"id":"s6-326","number":326,"surah":6,"verses":[48],"references":[{"surah":6,"verses":[48]}],"verseLabel":"الأنعام: 48","question":"ما سرّ التعبير في قوله تعالى: ﴿فمن آمن وأصلح﴾، ولم يكتف بالإيمان؟","answer":"الإيمان يصحح الاعتقاد، والإصلاح يظهر أثره في العمل ويزيل الفساد من النفس والسلوك؛ فلا يكفي ادعاء الإيمان مع الإصرار على ما يناقضه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص719، تحت «دلالة الجمع بين ﴿آمن﴾ و﴿وأصلح﴾»","url":""}]},{"id":"s6-327","number":327,"surah":6,"verses":[48],"references":[{"surah":6,"verses":[48]}],"verseLabel":"الأنعام: 48","question":"لماذا اختير ﴿أصلح﴾، لا: عمل صالحًا؟","answer":"يلائم ﴿أصلح﴾ حال قوم أفسدوا فطرتهم بالشرك وعدم الانتفاع بالآيات؛ فالمطلوب إزالة هذا الفساد وإصلاح النفس والعمل. لذلك أبرز الفعل التحول عما كانوا عليه، تمهيدًا للعمل الصالح، فالتخلية مقدمة على التحلية.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص719، تحت «دلالة اختيار ﴿وأصلح﴾ دون (وعمل صالحًا)»","url":""}]},{"id":"s6-328","number":328,"surah":6,"verses":[48],"references":[{"surah":6,"verses":[48]}],"verseLabel":"الأنعام: 48","question":"لماذا عُبر عن الخوف بالاسم وعن الحزن بالفعل في قوله تعالى: ﴿فلا خوف عليهم ولا هم يحزنون﴾؟","answer":"نفي اسم الخوف ينفي جنسه وثبوته عليهم، ونفي الفعل المضارع يصور استمرار عدم تجدد الحزن؛ فاجتمع عموم الأمن ودوامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص720، تحت عنوان «سر التعبير عن الخوف بالاسم والحزن بالفعل»","url":""}]},{"id":"s6-1157","number":1157,"surah":6,"verses":[48],"references":[{"surah":6,"verses":[48]}],"verseLabel":"الأنعام: 48","question":"لماذا قُدم نفي الخوف على نفي الحزن؟","answer":"لأن الخوف يتعلق بما يستقبل، والمقام مقام إنذار بما ينتظر الناس، فكان تأمين المؤمنين من المستقبل أولى بالتقديم ثم نفي حزنهم على ما مضى.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص720، تحت عنوان «دلالة تقديم الخوف على الحزن في الآية»","url":""}]},{"id":"s6-329","number":329,"surah":6,"verses":[48],"references":[{"surah":6,"verses":[48]}],"verseLabel":"الأنعام: 48","question":"ما دلالة الجملة الاسمية في قوله تعالى: ﴿فلا خوف عليهم﴾؟","answer":"تفيد ثبات الأمن لهم واستقراره، وتنفي جنس الخوف عنهم نفيًا شاملًا لا يقتصر على لحظة عابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص720، تحت عنوان «إيثار التعبير بالجملة الاسمية»","url":""}]},{"id":"s6-1158","number":1158,"surah":6,"verses":[48],"references":[{"surah":6,"verses":[48]}],"verseLabel":"الأنعام: 48","question":"ما دلالة المضارع المنفي في قوله تعالى: ﴿ولا هم يحزنون﴾؟","answer":"يصور استمرار انتفاء الحزن وعدم تجدده في مستقبل أحوالهم، فتكتمل لهم الطمأنينة مع نفي الخوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص720، تحت عنوان «دلالة التعبير بالفعل المضارع المنفي»","url":""}]},{"id":"s6-330","number":330,"surah":6,"verses":[49],"references":[{"surah":6,"verses":[49]}],"verseLabel":"الأنعام: 49","question":"لماذا عُبر عن إصابة العذاب بالمس في قوله تعالى: ﴿يمسهم العذاب﴾؟","answer":"المس يدل على مباشرة الأثر واتصاله بالبدن، فاختير لتقريب إحساس الألم وشدة ملازمة العذاب لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص724، تحت عنوان «إيثار التعبير عن العذاب بالمس دون غيره»","url":""}]},{"id":"s6-1159","number":1159,"surah":6,"verses":[49],"references":[{"surah":6,"verses":[49]}],"verseLabel":"الأنعام: 49","question":"ما فائدة المضارع في قوله تعالى: ﴿يمسهم العذاب﴾؟","answer":"يستحضر مشهد العذاب ويفيد تجدد وقوعه واستمراره، فكأنه يقع أمام السامع مرة بعد مرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص724، تحت عنوان «فائدة التعبير عن المس بالفعل المضارع»","url":""}]},{"id":"s6-1160","number":1160,"surah":6,"verses":[49],"references":[{"surah":6,"verses":[49]}],"verseLabel":"الأنعام: 49","question":"ما الاستعارة في إسناد المس إلى العذاب؟","answer":"صُور العذاب بكائن يباشرهم ويمد أثره إليهم، فأسند إليه المس لتشخيصه وجعل ملاحقته لهم محسوسة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص724، تحت عنوان «بلاغة الاستعارة في إسناد المس إلى العذاب»","url":""}]},{"id":"s6-331","number":331,"surah":6,"verses":[49],"references":[{"surah":6,"verses":[49]}],"verseLabel":"الأنعام: 49","question":"لماذا أضيفت الآيات إلى ضمير العظمة: ﴿بآياتنا﴾؟","answer":"إضافة الآيات إلى ضمير العظمة تشرفها وتبين عظم جناية المكذبين؛ فهم لم يكذبوا كلامًا بشريًا، بل دلائل الله المنسوبة إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص723، تحت «نكتة إضافة الآيات إلى ضمير الجمع»","url":""}]},{"id":"s6-332","number":332,"surah":6,"verses":[49],"references":[{"surah":6,"verses":[49]}],"verseLabel":"الأنعام: 49","question":"ما دلالة الباء في قوله تعالى: ﴿بما كانوا يفسقون﴾؟","answer":"هي للسببية، فربطت مس العذاب بفسقهم وكشفت أن ما أصابهم ثمرة لاختيارهم وخروجهم عن الطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص724، تحت عنوان «دلالة الباء في قوله جل شأنه: ﴿بما كانوا يفسقون﴾»","url":""}]},{"id":"s6-1161","number":1161,"surah":6,"verses":[49],"references":[{"surah":6,"verses":[49]}],"verseLabel":"الأنعام: 49","question":"لماذا قيل: ﴿يفسقون﴾ دون «يكذبون»؟","answer":"الفسق أعم؛ فهو خروج عن طاعة الله يشمل التكذيب وما يتولد عنه من المعاصي، فبين اتساع جرمهم واستمراره.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص725، تحت عنوان «نكتة التعبير بالفسق دون التكذيب»","url":""}]},{"id":"s6-1162","number":1162,"surah":6,"verses":[49],"references":[{"surah":6,"verses":[49]}],"verseLabel":"الأنعام: 49","question":"ما فائدة قوله تعالى: ﴿كانوا﴾ في ﴿بما كانوا يفسقون﴾؟","answer":"دل على رسوخ الفسق في ماضيهم واعتيادهم له، فلم يكن زلة عارضة بل سيرة لازمتهم واستحقوا بها العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص725، تحت عنوان «فائدة التعبير بالفعل (كانوا)»","url":""}]},{"id":"s6-1163","number":1163,"surah":6,"verses":[49],"references":[{"surah":6,"verses":[49]}],"verseLabel":"الأنعام: 49","question":"لماذا جاء خبر ﴿كان﴾ جملة مضارعية في قوله تعالى: ﴿كانوا يفسقون﴾؟","answer":"ليجمع بين ثبوت عادتهم في الماضي وتجدد أفراد الفسق منهم، فتُصور المعصية سلوكًا مستمرًا متكررًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص725–726، تحت عنوان «توجيه مجيء خبر (كان) جملة مضارعية»","url":""}]},{"id":"s6-333","number":333,"surah":6,"verses":[49],"references":[{"surah":6,"verses":[49]}],"verseLabel":"الأنعام: 49","question":"لماذا اختير ﴿يفسقون﴾، لا: يكفرون؟","answer":"اختير ﴿يفسقون﴾ لأنه أعم من الكفر والتكذيب؛ فالفسق خروج يشمل الكفر والشرك والتكذيب، وكل كافر فاسق وليس كل فاسق كافرًا، فعمم التعبير سبب العذاب ليجمع أنواع خروجهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص725، تحت «نكتة التعبير بالفسق دون التكذيب»","url":""}]},{"id":"s6-334","number":334,"surah":6,"verses":[50],"references":[{"surah":6,"verses":[50]}],"verseLabel":"الأنعام: 50","question":"لماذا عُبر عن مقدورات الله وأرزاقه بلفظ ﴿خزائن الله﴾؟","answer":"الخزائن مواضع النفائس المدخرة، فصور اللفظ سعة ما عند الله وحفظه ونفاد ما سواه دونه؛ ونفي كونها عند الرسول يرد اقتراحاتهم التي تطالبه بالتصرف فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص735، تحت عنوان «وجه اصطفاء لفظ ﴿خزائن الله﴾»","url":""}]},{"id":"s6-335","number":335,"surah":6,"verses":[50],"references":[{"surah":6,"verses":[50]}],"verseLabel":"الأنعام: 50","question":"كيف يصور لفظ ﴿خزائن الله﴾ سعة ما عند الله من الخير؟","answer":"شبهت مقدورات الله وتعلقها بالإنعام وإعطاء الخيرات بخزائن أهل اليسار التي تجمع الأموال والأطعمة ونحوها. فالصورة تقرب المعنى إلى الحس، مع بيان أن تلك الخيرات بيد الله، ولا يملك الرسول ﷺ التصرف فيها من عند نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص735، تحت «وجه اصطفاء لفظ ﴿خزائن الله﴾»","url":""}]},{"id":"s6-336","number":336,"surah":6,"verses":[50],"references":[{"surah":6,"verses":[50]}],"verseLabel":"الأنعام: 50","question":"ما سرّ تقديم ﴿عندي﴾ على ﴿خزائن الله﴾؟","answer":"قُدمت ﴿عندي﴾ للعناية بدفع ما يطلبه المشركون مما ليس في قدرة الرسول ﷺ؛ فالإنكار موجه إلى أن تكون خزائن الله تحت تصرفه. وبذلك يبرز التقديم موضع تصحيح دعواهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص735–736، تحت «نكتة تقديم لفظة ﴿عندي﴾»","url":""}]},{"id":"s6-337","number":337,"surah":6,"verses":[50],"references":[{"surah":6,"verses":[50]}],"verseLabel":"الأنعام: 50","question":"لماذا نفى النبي ﷺ علم الغيب مباشرة فقال: ﴿ولا أعلم الغيب﴾؟","answer":"لأن نفي العلم أصرح في رد توهم استقلاله بالغيب من مجرد نفي ادعائه، مع بقاء ما يعلمه بإعلام الله ووحيه خارج هذا الاستقلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص731، تحت عنوان «علة نفي النبي ﷺ معرفة الغيب، دون نفي القول بمعرفته»","url":""}]},{"id":"s6-1164","number":1164,"surah":6,"verses":[50],"references":[{"surah":6,"verses":[50]}],"verseLabel":"الأنعام: 50","question":"لماذا أُفرد لفظ ﴿الغيب﴾ في قوله تعالى: ﴿ولا أعلم الغيب﴾؟","answer":"أريد به اسم الجنس الشامل لكل ما غاب، فإفراده أوجز وأدل على استغراق جنس الغيب من غير حاجة إلى جمعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص736، تحت عنوان «سر إفراد الغيب دون جمعه»","url":""}]},{"id":"s6-338","number":338,"surah":6,"verses":[50],"references":[{"surah":6,"verses":[50]}],"verseLabel":"الأنعام: 50","question":"لماذا نُفي القول بالملكية في قوله تعالى: ﴿ولا أقول لكم إني ملك﴾ بدل نفي الملكية فقط؟","answer":"لأن المقام رد على دعاواهم ومطالبهم، فنفى النبي ﷺ أن يكون قد ادعى هذه المنزلة أصلًا؛ ويلزم من صدقه في النفي أنه ليس ملكًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص731، تحت عنوان «توجيه نفي القول دون نفي النسبة»","url":""}]},{"id":"s6-339","number":339,"surah":6,"verses":[50],"references":[{"surah":6,"verses":[50]}],"verseLabel":"الأنعام: 50","question":"ما بلاغة تكرار النفي في قوله تعالى: ﴿لا أقول لكم... ولا أعلم... ولا أقول لكم﴾؟","answer":"استقل كل ادعاء بنفيه حتى لا يحمل الكلام على نفي مجموع الصفات مع احتمال بعضها، فأحكم الرد على مقترحاتهم واحدًا واحدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص730، تحت عنوان «بلاغة تكرار النفي»","url":""}]},{"id":"s6-1165","number":1165,"surah":6,"verses":[50],"references":[{"surah":6,"verses":[50]}],"verseLabel":"الأنعام: 50","question":"لماذا خُصت الخزائن وعلم الغيب والملكية بالنفي؟","answer":"لأن اعتراضاتهم على الرسول كانت تدور حول طلب التصرف في الأرزاق والخوارق ومعرفة المغيبات وأن يكون ملكًا، فنفى ما تعلق بشبهاتهم مباشرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص731، تحت عنوان «السر في تخصيص المذكورات بالنفي دون غيرها»","url":""}]},{"id":"s6-1166","number":1166,"surah":6,"verses":[50],"references":[{"surah":6,"verses":[50]}],"verseLabel":"الأنعام: 50","question":"ما القصر في قوله تعالى: ﴿إن أتبع إلا ما يوحى إلي﴾؟","answer":"قصر شأن الرسول ﷺ على اتباع الوحي، فبين مصدر قوله ووظيفته ورد كل توهم بأنه يتصرف في خصائص الربوبية أو يتبع أهواء المقترحين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص732–733، تحت عنوان «بلاغة الحصر والقصر في الآية»","url":""}]},{"id":"s6-340","number":340,"surah":6,"verses":[50],"references":[{"surah":6,"verses":[50]}],"verseLabel":"الأنعام: 50","question":"لماذا حصر منهجه في قوله: ﴿إن أتبع إلا ما يوحى إلي﴾؟","answer":"القصر بـ﴿إن... إلا﴾ يحدد منهج الرسول في اتباع الوحي وحده؛ فلا يدعي من خصائص الربوبية شيئًا، ولا يجيب اقتراحاتهم من عند نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص732–733، تحت «بلاغة الحصر والقصر»","url":""}]},{"id":"s6-341","number":341,"surah":6,"verses":[50],"references":[{"surah":6,"verses":[50]}],"verseLabel":"الأنعام: 50","question":"ماذا يبرز فعل ﴿أتبع﴾ في قوله: ﴿إن أتبع إلا ما يوحى إلي﴾؟","answer":"يصور الوحي طريقًا يقتفي الرسول ﷺ أثره في قوله وعمله وحكمه؛ فلا ينشئ الرسالة من عند نفسه، ولا يتصرف فيها استجابة لأهواء المقترحين. فالاتباع يبين جهة قيادته ومرجع تصرفه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص736، تحت «سر التعبير بلفظ ﴿أتبع﴾»","url":""}]},{"id":"s6-342","number":342,"surah":6,"verses":[50],"references":[{"surah":6,"verses":[50]}],"verseLabel":"الأنعام: 50","question":"لماذا مثّل المؤمن والكافر بـ﴿الأعمى والبصير﴾؟","answer":"الأعمى مثل لمن حُجب عن دلائل الوحي فلم يهتد بها، والبصير مثل لمن أبصر الحق واتبعه؛ فالصورة تجعل الفرق بين الكافر والمؤمن كفرق محسوس لا يشتبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص733–734، تحت «بلاغة الاستعارة في ﴿الأعمى والبصير﴾»","url":""}]},{"id":"s6-343","number":343,"surah":6,"verses":[50],"references":[{"surah":6,"verses":[50]}],"verseLabel":"الأنعام: 50","question":"ما سرّ تقديم ﴿الأعمى﴾ على ﴿البصير﴾؟","answer":"قُدِّم الأعمى لأن المشركين، مع ضلالهم وجهلهم، كانوا يزعمون أنهم أعلى من المؤمنين لكثرة أموالهم؛ فجاء الاستفهام لينفي مساواة الأعمى بالبصير، فضلًا عن علوه عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص735، تحت «نكتة تقديم العمى في الذكر على البصر»","url":""}]},{"id":"s6-344","number":344,"surah":6,"verses":[50],"references":[{"surah":6,"verses":[50]}],"verseLabel":"الأنعام: 50","question":"لم جاء نفي المساواة في صورة سؤال: ﴿هل يستوي الأعمى والبصير﴾؟","answer":"يحمل الاستفهام السامع على تقرير نفي المساواة بنفسه، إذ الفرق بين العمى والبصر بديهي محسوس. وبهذا يقرب الفرق بين الضال والمهتدي ويجعل إنكار التسوية بينهما أوقع في النفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص733، تحت «بلاغة الاستفهام في الآية»","url":""}]},{"id":"s6-345","number":345,"surah":6,"verses":[50],"references":[{"surah":6,"verses":[50]}],"verseLabel":"الأنعام: 50","question":"ما دلالة الحض على التفكر في قوله تعالى: ﴿أفلا تتفكرون﴾؟","answer":"جاء الاستفهام توبيخًا وتحريضًا على إعمال العقل في الفرق الظاهر بين الأعمى والبصير وبين الضلال والهدى.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص734، تحت عنوان «بيان الحض على التفكر في الفاصلة»","url":""}]},{"id":"s6-1167","number":1167,"surah":6,"verses":[50],"references":[{"surah":6,"verses":[50]}],"verseLabel":"الأنعام: 50","question":"لماذا خُتمت الآية بالتفكر بدل الدعوة المباشرة إلى الإيمان؟","answer":"لأن التفكر هو الطريق الذي يكشف صدق الوحي والفرق بين البصيرة والعمى، فإذا صح النظر قاد صاحبه إلى الإيمان عن بينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص735، تحت عنوان «إيثار لفظ التفكير على لفظ الإيمان»","url":""}]},{"id":"s6-346","number":346,"surah":6,"verses":[50],"references":[{"surah":6,"verses":[50]}],"verseLabel":"الأنعام: 50","question":"لم رُتبت المنفيات: خزائن الله، ثم علم الغيب، ثم كون الرسول ملكًا؟","answer":"بدأ بما يتصل بالأرزاق التي يتشوفون إليها، ثم بمعرفة الغيب الذي يجهلونه، ثم بدعوى الملكية التي تخرجه عن حقيقة البشر. فتدرج الرد في نقض ما توهموه من لوازم الرسالة، تمهيدًا لإثبات حقيقتها: اتباع الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص732، تحت «براعة الترتيب في الجمل المنفية»","url":""}]},{"id":"s6-347","number":347,"surah":6,"verses":[51],"references":[{"surah":6,"verses":[51]}],"verseLabel":"الأنعام: 51","question":"ما سرّ التعبير في قوله تعالى: ﴿وأنذر به﴾، وإلى ماذا يعود الضمير في ﴿به﴾؟","answer":"الضمير في ﴿به﴾ يعود إلى القرآن المفهوم من قوله قبلها ﴿ما يوحى إلي﴾؛ أي أنذر بالوحي الذين يخافون الحشر. والإضمار يصل الكلام بما قبله ويبين أن أداة الإنذار هي الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص738–739، تحت «بيان مرجع الضمير في قوله ﴿به﴾»","url":""}]},{"id":"s6-348","number":348,"surah":6,"verses":[51],"references":[{"surah":6,"verses":[51]}],"verseLabel":"الأنعام: 51","question":"لماذا خُصّ بالإنذار ﴿الذين يخافون أن يحشروا إلى ربهم﴾؟","answer":"خُصوا بالإنذار لأن خوف الحشر يجعلهم أقرب إلى الانتفاع بالموعظة والاستعداد للقاء الله؛ فالمراد من يتوقع الحشر ويهابه، لا من يجحده فلا يصغي إلى الإنذار.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص739، تحت «السر بذكر الذين يخافون الحشر دون غيرهم».","url":""}]},{"id":"s6-349","number":349,"surah":6,"verses":[51],"references":[{"surah":6,"verses":[51]}],"verseLabel":"الأنعام: 51","question":"ما سرّ التعبير في قوله تعالى: ﴿أن يحشروا إلى ربهم﴾ بالبناء للمجهول؟","answer":"بُني ﴿يُحشروا﴾ للمفعول للدلالة على أن نفس الحشر هو المرْهوب، فهو جدير بأن يُخشى لذاته من غير تقييد بمن يقع منه الحشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص740، تحت «إيثار صيغة الفعل المبني للمفعول»","url":""}]},{"id":"s6-350","number":350,"surah":6,"verses":[51],"references":[{"surah":6,"verses":[51]}],"verseLabel":"الأنعام: 51","question":"ما سر العدول عن ذكر المحشر في قوله تعالى: ﴿أن يحشروا إلى ربهم﴾؟","answer":"صرف النظر من مكان الحشر إلى من يقفون بين يديه؛ فموطن الخوف الحقيقي هو عرضهم على ربهم للحساب والجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص741، تحت عنوان «سر العدول عن ذكر المحشر»","url":""}]},{"id":"s6-1168","number":1168,"surah":6,"verses":[51],"references":[{"surah":6,"verses":[51]}],"verseLabel":"الأنعام: 51","question":"لماذا قيل: ﴿إلى ربهم﴾ دون «إلى الله»؟","answer":"استحضر وصف الربوبية الذي يجمع الملك والتربية والرعاية؛ فإذا خاف العباد مقام ربهم مع ما فيه من الرحمة كان ذلك أبلغ في المهابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص741، تحت عنوان «إيثار التعبير بلفظ الربوبية»","url":""}]},{"id":"s6-351","number":351,"surah":6,"verses":[51],"references":[{"surah":6,"verses":[51]}],"verseLabel":"الأنعام: 51","question":"لماذا قُدم الولي على الشفيع في قوله تعالى: ﴿ليس لهم من دونه ولي ولا شفيع﴾؟","answer":"لأن الولي أقرب إلى المنصور وأقوى اتصالًا به، فنفي النصير القريب أولًا ثم نفي من يتوسط له من خارج.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص741، تحت عنوان «نكتة تقديم الولي على الشفيع»","url":""}]},{"id":"s6-1169","number":1169,"surah":6,"verses":[51],"references":[{"surah":6,"verses":[51]}],"verseLabel":"الأنعام: 51","question":"ما فائدة الجمع بين نفي الولي والشفيع؟","answer":"قطع جميع جهات النجاة المتوهمة: نصرة من يتولى أمرهم، ووساطة من يشفع لهم؛ فلا يملكون من دون الله حماية مستقلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص742، تحت عنوان «فائدة نفي الولي والشفيع عنهم»","url":""}]},{"id":"s6-352","number":352,"surah":6,"verses":[51],"references":[{"surah":6,"verses":[51]}],"verseLabel":"الأنعام: 51","question":"ما سرّ التعبير في قوله تعالى: ﴿من دونه﴾ بين نفي الولي والشفيع؟","answer":"في ﴿من دونه﴾ تحقير لما سوى الله وبيان لسفوله؛ فكل ما عُبد من دونه لا يستحق العبادة، لأنه تحت قهر عظمته ومتضائل عن رتبته، فلا يصلح وليًا ولا شفيعًا يُتعلق به.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص741، تحت «فائدة التعبير بـ﴿من دونه﴾»","url":""}]},{"id":"s6-353","number":353,"surah":6,"verses":[51],"references":[{"surah":6,"verses":[51]}],"verseLabel":"الأنعام: 51","question":"لماذا خُتمت الآية بـ﴿لعلهم يتقون﴾ لا: لعلهم يؤمنون؟","answer":"خُتم بالتقوى لأنها الغاية الأعلى التي يُراد بلوغها بالإنذار، ولا تتأتى إلا بعد الإيمان؛ فالإيمان الصحيح يثمر الخوف، والتقوى أعم لأنها تشمل الإسلام والإيمان، ولذلك كانت أبلغ هنا من الاقتصار على ﴿يؤمنون﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص742، تحت «التعبير بالفعل ﴿يتقون﴾ دون (يؤمنون)»","url":""}]},{"id":"s6-354","number":354,"surah":6,"verses":[52],"references":[{"surah":6,"verses":[52]}],"verseLabel":"الأنعام: 52","question":"لماذا نُهي عن طرد المؤمنين ولم يقل: «لا تبعدهم»؟","answer":"الطرد إبعاد يصحبه زجر وإهانة، فاختير اللفظ الذي يصور ما طلبه المستكبرون من احتقار الضعفاء ليأتي النهي في غاية الحسم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص746، تحت عنوان «دلالة التعبير بالنهي عن الطرد دون الإبعاد»","url":""}]},{"id":"s6-1170","number":1170,"surah":6,"verses":[52],"references":[{"surah":6,"verses":[52]}],"verseLabel":"الأنعام: 52","question":"ما فائدة النهي في قوله تعالى: ﴿ولا تطرد الذين يدعون ربهم﴾؟","answer":"صان المؤمنين المخلصين وأبطل ميزان الجاه والمال في مجلس النبوة، وفيه رد على المستكبرين الذين أرادوا إقصاءهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص746–747، تحت عنوان «فائدة النهي في قوله: ﴿ولا تطرد﴾»","url":""}]},{"id":"s6-355","number":355,"surah":6,"verses":[52],"references":[{"surah":6,"verses":[52]}],"verseLabel":"الأنعام: 52","question":"لماذا وصفهم بقوله: ﴿الذين يدعون ربهم﴾، لا: المؤمنين أو الفقراء؟","answer":"وُصفوا بعبادتهم لا بفقرهم لأن قيمتهم في إخلاصهم واتصالهم بربهم، لا في منزلتهم الاجتماعية. والصلة نفسها تقيم الحجة على بطلان طردهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص745، تحت «دلالة التعبير بالموصول»","url":""}]},{"id":"s6-356","number":356,"surah":6,"verses":[52],"references":[{"surah":6,"verses":[52]}],"verseLabel":"الأنعام: 52","question":"لماذا اختير ﴿يدعون﴾، لا: يعبدون؟","answer":"الدعاء يجمع دعاء العبادة ودعاء المسألة، فيصور توجههم الدائم إلى ربهم افتقارًا وعبادة؛ فهو في هذا المقام أوسع تصويرًا لحالهم من مجرد تسمية العبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص745، تحت «نكتة إيثار ﴿يدعون﴾ على (يعبدون)».","url":""}]},{"id":"s6-357","number":357,"surah":6,"verses":[52],"references":[{"surah":6,"verses":[52]}],"verseLabel":"الأنعام: 52","question":"ما سرّ التعبير في قوله تعالى: ﴿ربهم﴾، دون أن يقال: الله؟","answer":"عُبّر بالربوبية لأن المقام مقام إنعام وتفضل من الله عليهم؛ فقد نهى رسوله ﷺ عن طردهم، وفي إضافته إليهم إشعار بعلو قدرهم ورفعة مكانتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص746، تحت «سر إيثار الربوبية على الألوهية»","url":""}]},{"id":"s6-358","number":358,"surah":6,"verses":[52],"references":[{"surah":6,"verses":[52]}],"verseLabel":"الأنعام: 52","question":"لماذا خُصّ الدعاء بـ﴿الغداة والعشي﴾ مع أنهم يعبدونه في سائر الأوقات؟","answer":"الغداة والعشي طرفا النهار، وذكرهما كناية عن المواظبة واستغراق الأوقات، كما أنه يشير إلى أوقات العبادة الظاهرة التي لزموا عليها؛ فلا يراد حصر دعائهم فيهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص747، تحت «السر في ذكر وقتي الغداة والعشي».","url":""}]},{"id":"s6-359","number":359,"surah":6,"verses":[52],"references":[{"surah":6,"verses":[52]}],"verseLabel":"الأنعام: 52","question":"ما سرّ التعبير في قوله تعالى: ﴿يريدون وجهه﴾، وهل المراد الوجه حقيقة في هذا السياق؟","answer":"المراد أنهم يريدون ما عند الله؛ أي يعبدونه مخلصين له، صحيحة نياتهم، متوجهين إليه وحده، لا يريدون بعبادتهم عرضًا من الدنيا ولا رياء.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص748، تحت «سر التعبير بقوله ﴿يريدون وجهه﴾»","url":""}]},{"id":"s6-360","number":360,"surah":6,"verses":[52],"references":[{"surah":6,"verses":[52]}],"verseLabel":"الأنعام: 52","question":"ما دلالة قوله تعالى: ﴿ما عليك من حسابهم من شيء﴾؟","answer":"نفى أن يتحمل النبي ﷺ شيئًا من حساب المؤمنين أو أن يفتش عن سرائرهم؛ فحسابهم على الله ولا مسوغ لطردهم بظن الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص748، تحت عنوان «دلالة الإخبار بنفي حسابهم عنه»","url":""}]},{"id":"s6-1171","number":1171,"surah":6,"verses":[52],"references":[{"surah":6,"verses":[52]}],"verseLabel":"الأنعام: 52","question":"ما موقع جملة الحساب بين النهي عن الطرد وجوابه؟","answer":"جاءت اعتراضًا يعلل النهي ويزيل سببه المتوهم، ثم عاد السياق إلى نتيجة الطرد في قوله: ﴿فتطردهم فتكون من الظالمين﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص748، تحت عنوان «توجيه جملة الحساب بين النهي وجوابه»","url":""}]},{"id":"s6-361","number":361,"surah":6,"verses":[52],"references":[{"surah":6,"verses":[52]}],"verseLabel":"الأنعام: 52","question":"ما دلالة تقديم ما يعود إلى المخاطب في جملتي الحساب؟","answer":"قدم ﴿عليك﴾ في الأولى و﴿من حسابك﴾ في الثانية اعتناءً بمقام النبي ﷺ وتشريفًا للمخاطب مع إحكام المقابلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص750، تحت عنوان «دلالة تقديم كاف الخطاب في الجملتين»","url":""}]},{"id":"s6-1172","number":1172,"surah":6,"verses":[52],"references":[{"surah":6,"verses":[52]}],"verseLabel":"الأنعام: 52","question":"ما فائدة تقديم المسند على المسند إليه في جملتي الحساب؟","answer":"قدم الجار والمجرور محل العناية ليقوى نفي التبعة عن الجانبين، ويظهر أن الحساب لا يتعلق بأحدهما على الآخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص750، تحت عنوان «فائدة تقديم المسند على المسند إليه»","url":""}]},{"id":"s6-362","number":362,"surah":6,"verses":[52],"references":[{"surah":6,"verses":[52]}],"verseLabel":"الأنعام: 52","question":"ما دلالة الإتيان بـ﴿من﴾ في جملتي الحساب؟","answer":"دخلت على الحساب وشيء لتفيد استغراق النفي، فلا يتحمل النبي ﷺ أدنى جزء من حسابهم ولا يتحملون أدنى جزء من حسابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص749، تحت عنوان «دلالة الإتيان بـ(من)»","url":""}]},{"id":"s6-1173","number":1173,"surah":6,"verses":[52],"references":[{"surah":6,"verses":[52]}],"verseLabel":"الأنعام: 52","question":"كيف تأكد النفي في قوله تعالى: ﴿ما عليك من حسابهم من شيء﴾؟","answer":"تكرر حرف ﴿من﴾ مع النكرة ﴿شيء﴾ في سياق النفي، فنص التركيب على انتفاء كل مقدار من التبعة ولو كان يسيرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص749، تحت عنوان «وجه تأكيد النفي»","url":""}]},{"id":"s6-363","number":363,"surah":6,"verses":[52],"references":[{"surah":6,"verses":[52]}],"verseLabel":"الأنعام: 52","question":"ما معنى الفاء في قوله تعالى: ﴿فتطردهم﴾؟","answer":"هي فاء السببية في جواب النفي؛ أي لا شيء من حسابهم عليك يكون سببًا يبيح طردهم، فانتفى المسوغ الذي توهمه المعترضون.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص751، تحت عنوان «معنى الفاء في الآية»","url":""}]},{"id":"s6-1174","number":1174,"surah":6,"verses":[52],"references":[{"surah":6,"verses":[52]}],"verseLabel":"الأنعام: 52","question":"ما دلالة الفاء في قوله تعالى: ﴿فتكون من الظالمين﴾؟","answer":"رتبت الوقوع في الظلم على طردهم، فبينت العاقبة المباشرة لهذا الفعل وحذرت من ميزان يفضل الناس بالجاه والمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص752، تحت عنوان «دلالة الفاء في قوله: ﴿فتكون﴾»","url":""}]},{"id":"s6-364","number":364,"surah":6,"verses":[52],"references":[{"surah":6,"verses":[52]}],"verseLabel":"الأنعام: 52","question":"لم وصف طرد هؤلاء المؤمنين بأنه ظلم في ﴿فتكون من الظالمين﴾؟","answer":"لأنه وضع للأمر في غير موضعه: يُبعد المخلصون إرضاءً لمن استكبر عنهم، مع أن حسابهم على الله. فالآية تصون حقهم في مجلس الرسالة، وتبطل جعل المال والجاه سببًا لتقديم غيرهم عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص752، تحت «علة جعل الطرد ظلمًا»","url":""}]},{"id":"s6-365","number":365,"surah":6,"verses":[53],"references":[{"surah":6,"verses":[53]}],"verseLabel":"الأنعام: 53","question":"ما الغرض من استئناف قوله تعالى: ﴿وكذلك فتنا بعضهم ببعض﴾؟","answer":"جاء بيانًا لسر مطالبة المتكبرين بطرد المؤمنين؛ فتفاوتهم في الغنى والسبق إلى الإيمان كان ابتلاء كشف حسدهم واستكبارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص754–755، تحت عنوان «الغرض من الاستئناف»","url":""}]},{"id":"s6-1175","number":1175,"surah":6,"verses":[53],"references":[{"surah":6,"verses":[53]}],"verseLabel":"الأنعام: 53","question":"ما التشبيه في قوله تعالى: ﴿وكذلك فتنا بعضهم ببعض﴾؟","answer":"شبه فتنة هؤلاء بعضهم ببعض بما عرف من سنن الله في ابتلاء الناس بتفاوت الأحوال؛ فكل فريق ممتحن بموقفه من الآخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص755–756، تحت عنوان «بلاغة التشبيه في الآية»","url":""}]},{"id":"s6-366","number":366,"surah":6,"verses":[53],"references":[{"surah":6,"verses":[53]}],"verseLabel":"الأنعام: 53","question":"لماذا كرر ﴿بعض﴾ فقال: ﴿بعضهم ببعض﴾؟","answer":"تكرار ﴿بعض﴾ يبرز تبادل الفتنة بين فريقين؛ فكل بعض ممتحن بالبعض الآخر من جهة مختلفة، لا أن فريقًا واحدًا هو موضع الامتحان وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص755–756، تحت «بلاغة التشبيه في الآية»","url":""}]},{"id":"s6-367","number":367,"surah":6,"verses":[53],"references":[{"surah":6,"verses":[53]}],"verseLabel":"الأنعام: 53","question":"لماذا كانت نتيجة الفتنة قولهم: ﴿أهؤلاء من الله عليهم من بيننا﴾؟","answer":"كشفت الفتنة ما في نفوس المستكبرين؛ فقد قاسوا فضل الله بموازين المال والجاه، فاستبعدوا أن يختص بالإيمان من رأوهم دونهم منزلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص756–757، تحت «دلالة اللام على العاقبة والصيرورة»","url":""}]},{"id":"s6-368","number":368,"surah":6,"verses":[53],"references":[{"surah":6,"verses":[53]}],"verseLabel":"الأنعام: 53","question":"لماذا أشاروا إلى المؤمنين بـ﴿هؤلاء﴾؟","answer":"أشاروا إليهم بـ﴿هؤلاء﴾ احتقارًا لهم؛ إذ استنكفوا أن يخاطبوهم بالضمير لأنهم لا يرونهم أكفاء للمخاطبة، فجاء اسم الإشارة مرسخًا للاستخفاف والتحقير الظاهرين في استفهامهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص757–758، تحت «نكتة التعريف باسم الإشارة»","url":""}]},{"id":"s6-369","number":369,"surah":6,"verses":[53],"references":[{"surah":6,"verses":[53]}],"verseLabel":"الأنعام: 53","question":"لماذا عبّر عن الهداية بقوله: ﴿من الله عليهم﴾؟","answer":"جاء ذكر المنّ عقب الاستفهام الإنكاري ليكشف أنهم استبعدوا وقوع منة الله على هؤلاء، بل أنكروا وقوعها أصلًا بغضًا واستكبارًا؛ فزاد التعبير كشف نظرتهم الطبقية المستعلية لفقراء المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص758، تحت «دلالة إرداف الاستفهام بالفعل ﴿من﴾»","url":""}]},{"id":"s6-370","number":370,"surah":6,"verses":[53],"references":[{"surah":6,"verses":[53]}],"verseLabel":"الأنعام: 53","question":"ما دلالة قولهم: ﴿من بيننا﴾؟","answer":"قولهم ﴿من بيننا﴾ يكشف اعتدادهم بأنفسهم؛ استبعدوا أن يتجاوزهم الفضل إلى من عدوهم أقل شأنًا، فجعلوا منزلتهم الدنيوية مقياسًا للاختيار الإلهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص758–759، تحت «دلالة التعبير بالظرف»","url":""}]},{"id":"s6-371","number":371,"surah":6,"verses":[53],"references":[{"surah":6,"verses":[53]}],"verseLabel":"الأنعام: 53","question":"ما الغرض من الاستفهام في قوله تعالى: ﴿أليس الله بأعلم بالشاكرين﴾؟","answer":"هو للتقرير والإنكار على المعترضين، فيلزمهم بالإقرار بأن الله أعلم بمن يستحق مزيد الهداية والفضل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص759، تحت عنوان «الغرض من الاستفهام في: ﴿أليس الله بأعلم بالشاكرين﴾»","url":""}]},{"id":"s6-1176","number":1176,"surah":6,"verses":[53],"references":[{"surah":6,"verses":[53]}],"verseLabel":"الأنعام: 53","question":"لماذا قيل: ﴿أليس الله بأعلم بالشاكرين﴾ بطريق الاستفهام بدل الخبر؟","answer":"لأن الاستفهام ينتزع منهم الاعتراف بعلم الله وحكمته، فيكون إقرارهم نفسه جوابًا عن اعتراضهم وأوقع من مجرد الإخبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص759، تحت عنوان «سر إيثار الاستفهام المجازي على الإخبار»","url":""}]},{"id":"s6-372","number":372,"surah":6,"verses":[53],"references":[{"surah":6,"verses":[53]}],"verseLabel":"الأنعام: 53","question":"ما سرّ التعبير في قوله تعالى: ﴿بأعلم﴾ بصيغة التفضيل؟","answer":"جاء ﴿أعلم﴾ لتقرير علم الله البالغ بمن يستحق الهداية ومن لا يستحقها، وتشير صيغة التفضيل إلى أنه خير من يجزي الشاكرين ويكافئهم بأفضل العطاء والخير والإنعام.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص760، تحت «علة إيثار الوصف بالشاكرين»","url":""}]},{"id":"s6-373","number":373,"surah":6,"verses":[53],"references":[{"surah":6,"verses":[53]}],"verseLabel":"الأنعام: 53","question":"لماذا وُصف المؤمنون بالشاكرين بدل «المؤمنين»؟","answer":"لأنهم عرفوا نعمة الهداية وقابلوها بالقبول والطاعة، فناسب وصف الشكر مقام الامتنان عليهم بالإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص760، تحت عنوان «علة إيثار الوصف بالشاكرين»","url":""}]},{"id":"s6-1177","number":1177,"surah":6,"verses":[53],"references":[{"surah":6,"verses":[53]}],"verseLabel":"الأنعام: 53","question":"ما دلالة ذكر الشكر بعد إنكار المشركين تفضيل المؤمنين؟","answer":"كشف أن مناط الفضل حسن تلقي نعمة الله لا المال والجاه، وعرّض بالمستكبرين الذين جحدوا النعمة واعترضوا على قسمتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص760، تحت عنوان «دلالة ذكر الشكر بعد إنكار المشركين»","url":""}]},{"id":"s6-374","number":374,"surah":6,"verses":[54],"references":[{"surah":6,"verses":[54]}],"verseLabel":"الأنعام: 54","question":"ما سرّ التعبير في قوله تعالى: ﴿وإذا جاءك الذين يؤمنون بآياتنا﴾، فعرّفهم بصلة الإيمان؟","answer":"عُرّفوا بصلة الإيمان زيادة في إكرامهم، وتنبيهًا إلى أن الإيمان بآيات الله هو الصفة التي نالوا بها التكريم والتشريف، وجيء بالموصول ليعم الحكم غير أولئك الذين نُهي عن طردهم ممن تحققت فيه الصلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص764–765، تحت «فائدة التعريف بالاسم الموصول»","url":""}]},{"id":"s6-375","number":375,"surah":6,"verses":[54],"references":[{"surah":6,"verses":[54]}],"verseLabel":"الأنعام: 54","question":"لماذا أُمر النبي أن يبدأهم بقوله: ﴿سلام عليكم﴾؟","answer":"السلام تكريم وأمان يقابلان ما طلبه المشركون من طردهم؛ فأُمر النبي أن يستقبلهم بالتحية والطمأنينة، تمهيدًا لبشارة الرحمة والتوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص766، تحت «فائدة الأمر بالبدء بالسلام»","url":""}]},{"id":"s6-376","number":376,"surah":6,"verses":[54],"references":[{"surah":6,"verses":[54]}],"verseLabel":"الأنعام: 54","question":"لماذا جاء ﴿سلام﴾ نكرة، لا: السلام عليكم؟","answer":"التنكير في ﴿سلام﴾ للتعظيم والعموم؛ أي سلام عظيم شامل ثابت لكم، لا مجرد تحية معهودة عابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص766، تحت «فائدة التنكير في لفظ (سلام)»","url":""}]},{"id":"s6-377","number":377,"surah":6,"verses":[54],"references":[{"surah":6,"verses":[54]}],"verseLabel":"الأنعام: 54","question":"ما دلالة إسناد كتابة الرحمة إلى الرب في قوله تعالى: ﴿كتب ربكم على نفسه الرحمة﴾؟","answer":"أبرز وصف الربوبية عنايته بعباده وتربيته لهم، وجعل وعد الرحمة صادرًا منه سبحانه تفضلًا والتزامًا كريمًا لا بإيجاب أحد عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص768، تحت عنوان «علة إسناد الكتابة للرب سبحانه»","url":""}]},{"id":"s6-378","number":378,"surah":6,"verses":[54],"references":[{"surah":6,"verses":[54]}],"verseLabel":"الأنعام: 54","question":"لماذا جاء قوله تعالى: ﴿بجهالة﴾ حالًا شبه جملة بدل وصف العامل بالجهل؟","answer":"ألصق الجهالة بظرف ارتكاب السوء، فدل على أن الذنب وقع في حال غلبة السفه والهوى، من غير أن يجعل الجهل صفة ثابتة لصاحبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص769، تحت عنوان «العدول عن الحال الصفة إلى الحال شبه الجملة»","url":""}]},{"id":"s6-1178","number":1178,"surah":6,"verses":[54],"references":[{"surah":6,"verses":[54]}],"verseLabel":"الأنعام: 54","question":"ما دلالة تنكير ﴿جهالة﴾ وتقييد السوء بها؟","answer":"عمم التنكير كل حال يغلب فيها الهوى الرشد، وقيد بها السوء لأن المؤمن لا يقدم عليه إلا في حالة تناقض مقتضى العلم والحكمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص769، تحت عنوان «إيثار التنكير في (جهالة)، وفائدة التقييد بها»","url":""}]},{"id":"s6-379","number":379,"surah":6,"verses":[54],"references":[{"surah":6,"verses":[54]}],"verseLabel":"الأنعام: 54","question":"لماذا نُكّرت ﴿جهالة﴾؟","answer":"نُكرت ﴿جهالة﴾ لتبقى مطلقة غير مقيدة؛ فسواء أكانت الجهالة ضئيلة أم كبيرة فهي معتبرة في مغفرة الذنوب، وفي ذلك مبالغة في سعة الرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص769، تحت «إيثار التنكير في جهالة وفائدة التقييد بها»","url":""}]},{"id":"s6-380","number":380,"surah":6,"verses":[54],"references":[{"surah":6,"verses":[54]}],"verseLabel":"الأنعام: 54","question":"ما سرّ التعبير في قوله تعالى: ﴿ثم تاب من بعده وأصلح﴾، وما دلالة ﴿ثم﴾؟","answer":"تفيد ﴿ثم﴾ التراخي وطول الفاصل بين السوء والتوبة، للدلالة على قبول الرجوع بالندم والإقلاع وإن طال الزمان؛ وهذا أدل على سعة رحمة الله في قبول التوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص769–770، تحت «إيثار عطف التوبة بـ﴿ثم﴾»","url":""}]},{"id":"s6-381","number":381,"surah":6,"verses":[54],"references":[{"surah":6,"verses":[54]}],"verseLabel":"الأنعام: 54","question":"لماذا عطف ﴿وأصلح﴾ على التوبة؟","answer":"عُطف الإصلاح على التوبة للدلالة على أن استدامة الإصلاح في الشيء الذي تاب منه شرط لقبول التوبة، وأن العمل الصالح يؤكد صدق رجوعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص770، تحت «علة عطف الإصلاح على التوبة»","url":""}]},{"id":"s6-382","number":382,"surah":6,"verses":[54],"references":[{"surah":6,"verses":[54]}],"verseLabel":"الأنعام: 54","question":"لماذا خُتمت الآية بـ﴿فأنه غفور رحيم﴾ بصيغتي المبالغة؟","answer":"جاء ﴿غفور﴾ بصيغة المبالغة للدلالة على أن الله بالغ الستر والمحو لذنوب عباده؛ فالذنوب وإن عظمت فمغفرته أعظم ورحمته أوسع، عند تحقق شروط التوبة والإصلاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص770، تحت «سر التعبير بصيغة المبالغة ﴿غفور رحيم﴾»","url":""}]},{"id":"s6-383","number":383,"surah":6,"verses":[55],"references":[{"surah":6,"verses":[55]}],"verseLabel":"الأنعام: 55","question":"ما دلالة المضارع في قوله تعالى: ﴿وكذلك نفصل الآيات﴾؟","answer":"يدل على تجدد تفصيل الآيات واستمراره، فيشمل ما تقدم بيانه وما يتنزل بعده. فإيضاح الحق وتمييزه متتابع، وليس مقصورًا على البيان المذكور في هذا الموضع.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص774–775، تحت «سر التعبير بالفعل المضارع»","url":""}]},{"id":"s6-384","number":384,"surah":6,"verses":[55],"references":[{"surah":6,"verses":[55]}],"verseLabel":"الأنعام: 55","question":"ما دلالة اللام في قوله تعالى: ﴿ولتستبين سبيل المجرمين﴾؟","answer":"هي لام الغاية؛ فإبانة طريق المجرمين مقصد من تفصيل الآيات، ليعرف المؤمن الباطل ويتجنبه كما يعرف الحق ويسلكه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص775، تحت عنوان «دلالة اللام في فعل الإبانة»","url":""}]},{"id":"s6-1179","number":1179,"surah":6,"verses":[55],"references":[{"surah":6,"verses":[55]}],"verseLabel":"الأنعام: 55","question":"ما بلاغة عطف قوله تعالى: ﴿ولتستبين سبيل المجرمين﴾؟","answer":"عطف غاية خاصة ظاهرة الأثر على الغاية العامة المفهومة من تفصيل الآيات، فخص كشف طريق الإجرام بالعناية والتحذير.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص775، تحت عنوان «بلاغة العطف في جملة ﴿ولتستبين﴾»","url":""}]},{"id":"s6-385","number":385,"surah":6,"verses":[55],"references":[{"surah":6,"verses":[55]}],"verseLabel":"الأنعام: 55","question":"لم ذكر ﴿سبيل المجرمين﴾ دون أن يذكر معها سبيل المؤمنين؟","answer":"بيان أحد الطريقين يكشف ضده، والأشياء تتبين بأضدادها. وخص سبيل المجرمين بالتصريح للتحذير منها وكشف فسادها وقطع حجتهم، بعد أن أوضحت الآيات طريق الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص776–777، تحت «علة ذكر التصريح بسبيل المجرمين»","url":""}]},{"id":"s6-386","number":386,"surah":6,"verses":[55],"references":[{"surah":6,"verses":[55]}],"verseLabel":"الأنعام: 55","question":"لم صُرح بـ﴿المجرمين﴾ بدل أن يقال: ولتستبين سبيلهم؟","answer":"التصريح يسجل عليهم وصف الإجرام ويبين سبب ذم طريقهم، كما يجعل الحكم شاملًا لكل من اتصف بهذا الوصف. أما الضمير فيكتفي بالإحالة إلى المذكورين دون إبراز هذه العلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص775، تحت «بلاغة الإظهار موضع الإضمار»","url":""}]},{"id":"s6-387","number":387,"surah":6,"verses":[56],"references":[{"surah":6,"verses":[56]}],"verseLabel":"الأنعام: 56","question":"ما سرّ التعبير في قوله تعالى: ﴿إني نهيت أن أعبد﴾، دون أن يقال: لا أعبد؟","answer":"﴿إني نهيت﴾ يبين أن ترك عبادتهم امتثال لوحي الله وحكم ملزم، لا موقف شخصي قابل للمساومة؛ وفيه إعلان براءة حاسمة من الشرك.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص780، تحت «علة التعبير بالنهي دون النفي»","url":""}]},{"id":"s6-388","number":388,"surah":6,"verses":[56],"references":[{"surah":6,"verses":[56]}],"verseLabel":"الأنعام: 56","question":"لماذا عُبر عن الأصنام بالاسم الموصول في قوله تعالى: ﴿الذين تدعون﴾؟","answer":"جاء على وفق زعم عابديها حين أنزلوها منزلة العقلاء، فحاجهم القرآن بلغتهم وكشف عجز من منحوه تلك المنزلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص781، تحت عنوان «إيثار التعبير عن الأصنام بالاسم الموصول»","url":""}]},{"id":"s6-1180","number":1180,"surah":6,"verses":[56],"references":[{"surah":6,"verses":[56]}],"verseLabel":"الأنعام: 56","question":"ما دلالة قوله تعالى: ﴿من دون الله﴾؟","answer":"يبين أنهم تركوا الأعلى المستحق للعبادة إلى ما هو أدنى منه منزلة وعاجز، فيستجهل اختيارهم ويكشف فساد عبادتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص781، تحت عنوان «إيثار التعبير بلفظ ﴿من دون﴾»","url":""}]},{"id":"s6-389","number":389,"surah":6,"verses":[56],"references":[{"surah":6,"verses":[56]}],"verseLabel":"الأنعام: 56","question":"ما نكتة فصل الأمر الثاني ﴿قل لا أتبع أهواءكم﴾ عن الأول؟","answer":"جاء استئنافًا يبين علة النهي عن عبادة معبوداتهم؛ فباطن الشرك اتباع الهوى من غير برهان، واستقل هذا المعنى بالعناية.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص781، تحت عنوان «نكتة فصل الأمر الثاني ﴿قل لا أتبع﴾ عن الأول»","url":""}]},{"id":"s6-1181","number":1181,"surah":6,"verses":[56],"references":[{"surah":6,"verses":[56]}],"verseLabel":"الأنعام: 56","question":"لماذا تكرر الأمر بـ﴿قل﴾ مع قرب ذكره؟","answer":"ليدل على استقلال المقول الثاني وأهميته واختلافه عن الأول، وليشعر بأن كل جواب وحي مأمور بتبليغه صراحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص781–782، تحت عنوان «علة تكرار الأمر بالقول مع قرب ذكره»","url":""}]},{"id":"s6-390","number":390,"surah":6,"verses":[56],"references":[{"surah":6,"verses":[56]}],"verseLabel":"الأنعام: 56","question":"ما المجاز في قوله تعالى: ﴿ولا أتبع أهواءكم﴾ بعد النهي عن عبادة آلهتهم؟","answer":"أطلق اتباع الأهواء وأريد عبادة ما اختاروه بلا حجة؛ لأن الشرك ناشئ عن ميل النفس وتقليد الموروث، فكشف التعبير باطن عبادتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص782، تحت عنوان «بلاغة المجاز المرسل ومزيته»","url":""}]},{"id":"s6-391","number":391,"surah":6,"verses":[56],"references":[{"surah":6,"verses":[56]}],"verseLabel":"الأنعام: 56","question":"لماذا جُمعت ﴿أهواءكم﴾؟","answer":"جُمعت ﴿أهواءكم﴾ لتعدد ميول المشركين وتناقض معبوداتهم ودوافعهم؛ فالحق واحد، أما الهوى فطرق متفرقة بتفرق أصحابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص782، تحت «إيثار الجمع على الإفراد في لفظ الأهواء»","url":""}]},{"id":"s6-392","number":392,"surah":6,"verses":[56],"references":[{"surah":6,"verses":[56]}],"verseLabel":"الأنعام: 56","question":"ما سرّ التعبير في قوله تعالى: ﴿قد ضللت إذًا﴾ بالماضي مع أن الضلال مفترض؟","answer":"الماضي مع ﴿قد﴾ يصور الضلال المفروض متحققًا لا شك فيه إن وقع اتباع أهوائهم؛ فجواب الشرط مقدر المعنى كأنه حدث لتيقن نتيجته.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص783، تحت «نكتة تصدير الجملة بقد»","url":""}]},{"id":"s6-393","number":393,"surah":6,"verses":[56],"references":[{"surah":6,"verses":[56]}],"verseLabel":"الأنعام: 56","question":"ما فائدة نفي الاهتداء بعد قوله تعالى: ﴿قد ضللت إذًا﴾؟","answer":"جمع بين إثبات الوقوع في الضلال ونفي الدخول في زمرة المهتدين لو اتبع أهواءهم، فسد طريق التأويل وأكد تباعد الحالين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص783، تحت عنوان «فائدة نفي الاهتداء بعد ذكر الضلال»","url":""}]},{"id":"s6-1182","number":1182,"surah":6,"verses":[56],"references":[{"surah":6,"verses":[56]}],"verseLabel":"الأنعام: 56","question":"لماذا قيل: ﴿وما أنا من المهتدين﴾ بالجملة الاسمية؟","answer":"لأنها أبلغ في نفي ثبوت صفة الاهتداء واستقرارها من نفي فعل عابر، فتبين أن اتباع الهوى يناقض الانتماء إلى أهل الهدى.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص784، تحت عنوان «بيان العدول عن الجملة الفعلية إلى الجملة الاسمية»","url":""}]},{"id":"s6-394","number":394,"surah":6,"verses":[57],"references":[{"surah":6,"verses":[57]}],"verseLabel":"الأنعام: 57","question":"ما سرّ التعبير في قوله تعالى: ﴿إني على بينة من ربي﴾ بحرف الاستعلاء ﴿على﴾؟","answer":"﴿على﴾ للاستعلاء والتمكن؛ تصور النبي ثابتًا مستمسكًا ببينة تحمل حجته، وفيها ثقته بنصر الله ووضوح ما جاءه من الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص788، تحت «فائدة التعبير بحرف الاستعلاء».","url":""}]},{"id":"s6-395","number":395,"surah":6,"verses":[57],"references":[{"surah":6,"verses":[57]}],"verseLabel":"الأنعام: 57","question":"لماذا نُكرت ﴿بينة﴾ في قوله تعالى: ﴿إني على بينة من ربي﴾؟","answer":"للتفخيم، أي على حجة عظيمة واضحة يميز بها الحق من الباطل، لا على دعوى مجردة كما يزعم المكذبون.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص788، تحت عنوان «بيان التنكير في ﴿على بينة﴾»","url":""}]},{"id":"s6-1183","number":1183,"surah":6,"verses":[57],"references":[{"surah":6,"verses":[57]}],"verseLabel":"الأنعام: 57","question":"ما دلالة نسبة البينة إلى الرب في قوله تعالى: ﴿من ربي﴾؟","answer":"بينت مصدر الحجة وسلطانها، فهي وحي من الرب المربي الهادي، لا فكرة ابتدعها الرسول من عند نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص788، تحت عنوان «توجيه نسبة البينة إلى الرب»","url":""}]},{"id":"s6-396","number":396,"surah":6,"verses":[57],"references":[{"surah":6,"verses":[57]}],"verseLabel":"الأنعام: 57","question":"ما سرّ التعبير في قوله تعالى: ﴿وكذبتم به﴾، وإلى ماذا يعود الضمير؟","answer":"اختلف في مرجع الضمير: فالظاهر عوده إلى ﴿ربي﴾ لقربه، أي كذبتم بالله، وقيل يعود إلى ﴿بينة﴾ لأنها بمعنى البيان والقرآن. والأولى عوده إلى الرب لقرب المرجع وعدم احتياجه إلى تأويل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص789، تحت «مرجع الضمير في بيان المكذب به»","url":""}]},{"id":"s6-397","number":397,"surah":6,"verses":[57],"references":[{"surah":6,"verses":[57]}],"verseLabel":"الأنعام: 57","question":"ما سرّ التعبير في قوله تعالى: ﴿ما عندي ما تستعجلون به﴾ بتكرار ﴿ما﴾؟","answer":"﴿ما﴾ الأولى نافية: ليس عندي، والثانية موصولة بمعنى: الذي تستعجلون به. وعُبر بالموصول بدل «العذاب» لإبراز صلة استعجالهم به، والإشارة إلى أنه مؤخر مدخر لهم وواقع بهم لا محالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص790، تحت «إيثار التعبير بالاسم الموصول»","url":""}]},{"id":"s6-398","number":398,"surah":6,"verses":[57],"references":[{"surah":6,"verses":[57]}],"verseLabel":"الأنعام: 57","question":"لماذا وصف طلبهم للعذاب بـ﴿تستعجلون﴾؟","answer":"وُصف طلبهم بالاستعجال لأن الاستعجال طلب الشيء قبل وقته، وقد طلبوا العذاب قبل حينه وجعلوا تأخره ذريعة إلى التكذيب؛ لذلك كان لفظ الاستعجال أدق من الإسراع وأناسب للمقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص792–793، تحت «الاستعجال والإسراع»","url":""}]},{"id":"s6-399","number":399,"surah":6,"verses":[57],"references":[{"surah":6,"verses":[57]}],"verseLabel":"الأنعام: 57","question":"ما دلالة الحصر في قوله تعالى: ﴿إن الحكم إلا لله﴾؟","answer":"قصر الحكم كله على الله، فرد طلبهم إلى مالك الأمر الذي يقدر وقت العذاب ويفصل بين الرسول والمكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص790–791، تحت عنوان «دلالة الحصر في قوله تعالى: ﴿إن الحكم إلا لله﴾»","url":""}]},{"id":"s6-1184","number":1184,"surah":6,"verses":[57],"references":[{"surah":6,"verses":[57]}],"verseLabel":"الأنعام: 57","question":"كيف يجتمع عموم الحكم وخصوص المقام في قوله تعالى: ﴿إن الحكم إلا لله﴾؟","answer":"اللفظ يعم كل حكم كوني وشرعي، والسياق يخص منه ما استعجلوه من الفصل وإنزال العذاب؛ فالخاص داخل تحت الأصل العام.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص791، تحت عنوان «توجيه عموم المحصور وخصوصه»","url":""}]},{"id":"s6-400","number":400,"surah":6,"verses":[57],"references":[{"surah":6,"verses":[57]}],"verseLabel":"الأنعام: 57","question":"ما دلالة المضارع في قوله تعالى: ﴿يقص الحق﴾؟","answer":"يفيد تجدد بيان الله للحق واستمرار قضائه به، فيطمئن السامع إلى صدق خبره وعدله في الفصل بين المحق والمبطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص791، تحت عنوان «إيثار التعبير بالفعل المضارع ﴿يقص﴾»","url":""}]},{"id":"s6-401","number":401,"surah":6,"verses":[57],"references":[{"surah":6,"verses":[57]}],"verseLabel":"الأنعام: 57","question":"لماذا خُتمت الآية بـ﴿وهو خير الفاصلين﴾ بعد ﴿إن الحكم إلا لله﴾؟","answer":"ختمت الآية بـ﴿وهو خير الفاصلين﴾ تذييلًا يقرر ما قبلها؛ لأن قص الحق يفضي إلى الفصل بين الحق والباطل، والله خير من يبين المحق من المبطل ويفصل بينهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص791–792، تحت «فائدة التذييل»","url":""}]},{"id":"s6-402","number":402,"surah":6,"verses":[58],"references":[{"surah":6,"verses":[58]}],"verseLabel":"الأنعام: 58","question":"ما بلاغة الفصل في قوله تعالى: ﴿لو أن عندي ما تستعجلون به لقضي الأمر بيني وبينكم﴾؟","answer":"جاءت الجملة جوابًا مستقلًا يبين أثر الفرض السابق: لو كان العذاب في قدرة الرسول لحُسمت الخصومة، لكنها قدرة لله يجريها بحكمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص795، تحت عنوان «بلاغة الفصل في الآية»","url":""}]},{"id":"s6-403","number":403,"surah":6,"verses":[58],"references":[{"surah":6,"verses":[58]}],"verseLabel":"الأنعام: 58","question":"كيف تعبر ﴿عندي﴾ عن القدرة في قوله: ﴿لو أن عندي ما تستعجلون به﴾؟","answer":"استعملت العندية مجازًا عن القدرة والتمكن من إنزال ما طلبوه؛ فما يكون عند الإنسان يتمكن عادة من التصرف فيه. والمعنى أن إنزال العذاب ليس في قدرة الرسول ﷺ، وإنما أمره إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص795–796، تحت «بلاغة المجاز في لفظ (عندي)»","url":""}]},{"id":"s6-404","number":404,"surah":6,"verses":[58],"references":[{"surah":6,"verses":[58]}],"verseLabel":"الأنعام: 58","question":"لماذا بُني الفعل للمفعول في قوله تعالى: ﴿لقضي الأمر بيني وبينكم﴾؟","answer":"لتركيز النظر على حسم الأمر ووقوع الهلاك الذي يستعجلونه، مع العلم بأن القاضي الحقيقي هو الله؛ وفيه أدب برد القدرة إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص796، تحت عنوان «إيثار التعبير بالفعل المبني للمفعول»","url":""}]},{"id":"s6-405","number":405,"surah":6,"verses":[58],"references":[{"surah":6,"verses":[58]}],"verseLabel":"الأنعام: 58","question":"لماذا عبّر بـ﴿قضي الأمر﴾ بالبناء للمجهول؟","answer":"بُني ﴿قضي الأمر﴾ للمجهول للعناية بوقوع الإهلاك نفسه، ولأن قاضيه معلوم وهو الله؛ وفي ترك التصريح أدب مع الله وتهويل للمخوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص796، تحت «إيثار التعبير بالفعل المبني للمفعول»","url":""}]},{"id":"s6-406","number":406,"surah":6,"verses":[58],"references":[{"surah":6,"verses":[58]}],"verseLabel":"الأنعام: 58","question":"كيف يفيد ﴿والله أعلم بالظالمين﴾ التهديد مع أنه خبر عن العلم؟","answer":"العلم هنا كناية عن المجازاة مع دليلها؛ فمن أحاط بظلمهم لا يفوته ما يستحقونه من عقاب. فالجملة تنبه إلى أن تأخير العذاب لا يعني خفاء حالهم، بل أمر جزائهم إلى الله العالم بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص796، تحت «فائدة التعبير بالعلم في معرض التهديد»","url":""}]},{"id":"s6-407","number":407,"surah":6,"verses":[58],"references":[{"surah":6,"verses":[58]}],"verseLabel":"الأنعام: 58","question":"لماذا أظهر اسم ﴿الظالمين﴾ ولم يقل: والله أعلم بكم؟","answer":"وُضع الظاهر موضع الضمير لكشف صفتهم وسبب الوعيد؛ فهم ظالمون بالشرك وباستعجال العذاب، والحكم يعم كل من اتصف بظلمهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص796–797، تحت «علة وضع الظاهر موضع المضمر»","url":""}]},{"id":"s6-408","number":408,"surah":6,"verses":[59],"references":[{"surah":6,"verses":[59]}],"verseLabel":"الأنعام: 59","question":"ما سرّ التعبير في قوله تعالى: ﴿وعنده مفاتح الغيب﴾ بتقديم ﴿عنده﴾؟","answer":"تقديم ﴿عنده﴾ يفيد التخصيص والحصر: مفاتح الغيب عند الله وحده لا عند غيره، ثم أكد هذا الاختصاص قوله تعالى: ﴿لا يعلمها إلا هو﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص12، تحت «سر تقديم الظرف»","url":""}]},{"id":"s6-409","number":409,"surah":6,"verses":[59],"references":[{"surah":6,"verses":[59]}],"verseLabel":"الأنعام: 59","question":"ما بلاغة الاستعارة التمثيلية في قوله تعالى: ﴿وعنده مفاتح الغيب﴾؟","answer":"صُوّر الغيب بأبواب أو خزائن مغلقة لا يملك مفاتيحها إلا الله؛ فقرّبت الصورة اختصاصه بعلم الغيب وتمكنه منه إلى الحس.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص12–13، تحت عنوان «بلاغة الاستعارة التمثيلية في المفاتح»","url":""}]},{"id":"s6-1185","number":1185,"surah":6,"verses":[59],"references":[{"surah":6,"verses":[59]}],"verseLabel":"الأنعام: 59","question":"كيف تعددت طرائق الدلالة على اختصاص الله بعلم الغيب في قوله تعالى: ﴿وعنده مفاتح الغيب لا يعلمها إلا هو﴾؟","answer":"اجتمع تقديم الظرف ﴿عنده﴾ مع إضافة المفاتح إلى الغيب والقصر بالنفي والاستثناء؛ فتآزرت هذه الأساليب على توكيد انفراد الله بعلمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص13، تحت عنوان «نكتة تعدد الكيفيات الدالة على اختصاص علم الغيب بالله تعالى»","url":""}]},{"id":"s6-410","number":410,"surah":6,"verses":[59],"references":[{"surah":6,"verses":[59]}],"verseLabel":"الأنعام: 59","question":"هل ﴿مفاتح﴾ جمع مفتاح أم جمع مَفْتَح بمعنى الخزائن، وما أثر المعنيين؟","answer":"تحتمل ﴿مفاتح﴾ أن تكون جمع مفتاح، أي وسائل فتح المغلق والوصول إلى الغيب، وأن تكون جمع مَفْتَح بمعنى الخزائن. وعلى الوجهين لا يملك طرق الغيب ولا خزائنه إلا الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص10، تحت «شرح المفردات: ﴿مفاتح الغيب﴾»","url":""}]},{"id":"s6-411","number":411,"surah":6,"verses":[59],"references":[{"surah":6,"verses":[59]}],"verseLabel":"الأنعام: 59","question":"ما براعة كمال الاتصال بين قوله تعالى: ﴿وعنده مفاتح الغيب﴾ وقوله: ﴿لا يعلمها إلا هو﴾؟","answer":"جاءت الجملة الثانية توكيدًا وبيانًا للأولى؛ فاختصاص المفاتح عنده يقتضي انفراده بعلمها، لذلك اتصلتا من غير عطف.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص13، تحت عنوان «براعة كمال الاتصال بين الجملتين»","url":""}]},{"id":"s6-412","number":412,"surah":6,"verses":[59],"references":[{"surah":6,"verses":[59]}],"verseLabel":"الأنعام: 59","question":"لماذا عُطف قوله تعالى: ﴿ويعلم ما في البر والبحر﴾ على علم مفاتح الغيب؟","answer":"انتقل السياق من الغيب المستور إلى العالم المشاهد، فجمع علم الله بما غاب وبما ظهر، ومهّد للانتقال إلى أدق الجزئيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص14، تحت عنوان «توجيه عطف علم ما في الأرض على علم الغيب»","url":""}]},{"id":"s6-1186","number":1186,"surah":6,"verses":[59],"references":[{"surah":6,"verses":[59]}],"verseLabel":"الأنعام: 59","question":"ما فائدة تخصيص البر والبحر بالذكر بعد عموم مفاتح الغيب؟","answer":"خصهما لأنهما يستوعبان جهات العالم المشاهد عند المخاطبين؛ فدل ذكرهما بعد العموم على إحاطة العلم بالكليات وتفاصيلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص14، تحت عنوان «فائدة التخصيص بعد التعميم»","url":""}]},{"id":"s6-1187","number":1187,"surah":6,"verses":[59],"references":[{"surah":6,"verses":[59]}],"verseLabel":"الأنعام: 59","question":"ما بلاغة القصر في قوله تعالى: ﴿وما تسقط من ورقة إلا يعلمها﴾؟","answer":"قصر كل سقوط لورقة على أن يكون معلومًا لله، فنفى خروج أدق الحوادث وأكثرها تكررًا عن علمه، وأكد إحاطته بالجزئيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص15–16، تحت عنوان «بلاغة القصر في قوله تعالى: ﴿وما تسقط من ورقة إلا يعلمها﴾»","url":""}]},{"id":"s6-413","number":413,"surah":6,"verses":[59,63],"references":[{"surah":6,"verses":[59,63]}],"verseLabel":"الأنعام: 59؛ الأنعام: 63","question":"ما مزية الطباق بين ﴿البر﴾ و﴿البحر﴾ في قوله تعالى: ﴿ويعلم ما في البر والبحر﴾؟","answer":"جمع الطرفين المتقابلين لاستيعاب جهات العالم المشاهد، فدل بطريق موجز على أن علم الله محيط بما فيهما ظاهرًا وخفيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص14، تحت عنوان «مزية الطباق في البر والبحر»","url":""}]},{"id":"s6-1188","number":1188,"surah":6,"verses":[59,63],"references":[{"surah":6,"verses":[59,63]}],"verseLabel":"الأنعام: 59؛ الأنعام: 63","question":"ما دلالة الحقيقة والمجاز في قوله تعالى: ﴿من ظلمات البر والبحر﴾؟","answer":"تشمل الظلمات ظلمة الحس في البر والبحر، وتستعمل مجازًا في الشدائد والحيرة التي تنقطع فيها الأسباب؛ وفي الحالين لا يلجأ المضطر إلا إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص60، تحت عنوان «دلالة الحقيقة والمجاز في قوله تعالى: ﴿من ظلمات البر والبحر﴾»","url":""}]},{"id":"s6-414","number":414,"surah":6,"verses":[59],"references":[{"surah":6,"verses":[59]}],"verseLabel":"الأنعام: 59","question":"لماذا أوثر لفظ ﴿تسقط﴾ في قوله تعالى: ﴿وما تسقط من ورقة إلا يعلمها﴾؟","answer":"اختير السقوط لأنه حادث دقيق متجدد لا يلتفت إليه الناس، فإذا كان كل وقوع لورقة معلومًا لله فما هو أعظم أولى بالإحاطة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص16، تحت عنوان «علة إيثار لفظ السقوط»","url":""}]},{"id":"s6-415","number":415,"surah":6,"verses":[59],"references":[{"surah":6,"verses":[59]}],"verseLabel":"الأنعام: 59","question":"ما سرّ التعبير في قوله تعالى: ﴿وما تسقط من ورقة إلا يعلمها﴾ بالمضارع؟","answer":"المضارع يستحضر سقوط الأوراق حادثًا متجددًا في كل لحظة ومكان، ويقرر أن علم الله يصاحبه على الدوام، لا أنه علم بجنسه مرة وانقضى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص15، تحت «نكتة التعبير عن السقوط بالمضارع»","url":""}]},{"id":"s6-416","number":416,"surah":6,"verses":[59],"references":[{"surah":6,"verses":[59]}],"verseLabel":"الأنعام: 59","question":"لماذا نُكّرت ﴿ورقة﴾ وزيدت ﴿من﴾ قبلها؟","answer":"دخلت ﴿من﴾ الزائدة بعد النفي لتأكيد الاستغراق، ونُكرت ﴿ورقة﴾ لتشمل أي ورقة مهما دقت وبعد مكانها؛ فلا تسقط واحدة إلا بعلمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص16، تحت «دلالة (من) في ﴿من ورقة﴾ وفائدة التنكير»","url":""}]},{"id":"s6-417","number":417,"surah":6,"verses":[59],"references":[{"surah":6,"verses":[59]}],"verseLabel":"الأنعام: 59","question":"لم قيل ﴿إلا يعلمها﴾ ولم يقيد العلم بسقوط الورقة؟","answer":"ليعم العلم جميع أحوالها؛ فيعلمها قبل السقوط وبعده، وفي ثباتها وسقوطها، ويعلم مكانها وهيئتها وسائر تفاصيلها. فإطلاق العلم أوسع من قصره على حادثة السقوط وحدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص16–17، تحت «فائدة إطلاق العلم بالورقة دون تقييده»","url":""}]},{"id":"s6-418","number":418,"surah":6,"verses":[59],"references":[{"surah":6,"verses":[59]}],"verseLabel":"الأنعام: 59","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا حبة في ظلمات الأرض﴾، فجعل الحبة في ظلمات جمع؟","answer":"جُمعت ﴿ظلمات﴾ للمبالغة في دقة علم الله وسعته؛ فباطن الأرض ظلمة متكاثفة متكاثرة بالنسبة إلى الإنسان لجهله بما يجري فيه حتى يظهر، ومع ذلك لا تخفى الحبة على علم الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص18، تحت «سر جمع ﴿ظلمات﴾»","url":""}]},{"id":"s6-419","number":419,"surah":6,"verses":[59],"references":[{"surah":6,"verses":[59]}],"verseLabel":"الأنعام: 59","question":"لماذا قابل بين ﴿رطب﴾ و﴿يابس﴾؟","answer":"جُمع الرطب واليابس، وهما وصفان متقابلان، لإفادة العموم والشمول؛ فكل شيء اتصف بالرطوبة أو اليبوسة داخل في علم الله تعالى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص18، تحت «فائدة تنكير الرطب واليابس».","url":""}]},{"id":"s6-420","number":420,"surah":6,"verses":[59],"references":[{"surah":6,"verses":[59]}],"verseLabel":"الأنعام: 59","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا رطب ولا يابس﴾، وكرر ﴿لا﴾؟","answer":"كُررت ﴿لا﴾ مع الرطب واليابس لتوكيد النفي والمبالغة في شمول علم الله؛ فلا يخرج عنه شيء اتصف بالرطوبة أو اليبوسة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص18، تحت «نكتة تعديد المستثنى منه في قوله تعالى: ﴿ولا رطب ولا يابس﴾».","url":""}]},{"id":"s6-421","number":421,"surah":6,"verses":[59],"references":[{"surah":6,"verses":[59]}],"verseLabel":"الأنعام: 59","question":"ما نكتة تعدد المستثنى منه في قوله تعالى: ﴿ولا رطب ولا يابس إلا في كتاب مبين﴾؟","answer":"جُمع الرطب واليابس وهما طرفان متقابلان ليستوعب التعبير الموجودات على اختلاف أحوالها، فيقرر أن شيئًا منها لا يخرج عن العلم والكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص18–19، تحت عنوان «نكتة تعدد المستثنى منه في قوله تعالى: ﴿ولا رطب ولا يابس﴾»","url":""}]},{"id":"s6-422","number":422,"surah":6,"verses":[59],"references":[{"surah":6,"verses":[59]}],"verseLabel":"الأنعام: 59","question":"ما الذي يضيفه وصف الكتاب بـ﴿مبين﴾ في مقام إحاطة علم الله؟","answer":"يدل على صحة ما أثبت فيه؛ فالأشياء تقع موافقة لما رسم في الكتاب من أعدادها وأوقاتها وأحوالها. فالوصف يؤكد أن هذا الإثبات حق يظهر صدقه بوقوع المقدور على وفقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص10–12، تحت «شرح المفردات: ﴿كتاب مبين﴾»","url":""}]},{"id":"s6-423","number":423,"surah":6,"verses":[60],"references":[{"surah":6,"verses":[60]}],"verseLabel":"الأنعام: 60","question":"لماذا عبّر عن النوم بقوله: ﴿يتوفاكم بالليل﴾؟","answer":"التوفي استيفاء الشيء وقبضه؛ والنوم قبض مؤقت لإدراك الإنسان وحركته، فشبه بالموت وسمي وفاة صغرى، ثم يكون الاستيقاظ بعثًا مصغرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص23–24، تحت «دلالة الاستعارة التبعية في قوله تعالى: ﴿يتوفاكم بالليل﴾»","url":""}]},{"id":"s6-424","number":424,"surah":6,"verses":[60],"references":[{"surah":6,"verses":[60]}],"verseLabel":"الأنعام: 60","question":"ما دلالة الباء في قوله تعالى: ﴿يتوفاكم بالليل﴾؟","answer":"جاءت الباء بمعنى الظرفية، أي يتوفاكم في الليل؛ فحدد التركيب الزمن الغالب للنوم مع إيجاز العبارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص24، تحت عنوان «دلالة الباء في قوله تعالى: ﴿بالليل﴾ على معنى (في) الظرفية»","url":""}]},{"id":"s6-1189","number":1189,"surah":6,"verses":[60],"references":[{"surah":6,"verses":[60]}],"verseLabel":"الأنعام: 60","question":"ما المراد بالليل والنهار في قوله تعالى: ﴿يتوفاكم بالليل ويعلم ما جرحتم بالنهار﴾؟","answer":"ذُكر الليل زمنًا غالبًا للنوم والسكون، والنهار زمنًا غالبًا للكسب والحركة؛ فالكلام جارٍ على المعتاد ولا ينفي نوم النهار أو العمل ليلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص25–26، تحت عنوان «المراد بالليل والنهار في قوله تعالى: ﴿يتوفاكم بالليل ويعلم ما جرحتم بالنهار﴾»","url":""}]},{"id":"s6-425","number":425,"surah":6,"verses":[60],"references":[{"surah":6,"verses":[60]}],"verseLabel":"الأنعام: 60","question":"لماذا عُدّيت الوفاة بالباء: ﴿يتوفاكم بالليل﴾، لا: في الليل؟","answer":"الباء في ﴿بالليل﴾ بمعنى ﴿في﴾؛ وأفادت الظرفية من أصل معنى الملابسة، لأن الفعل الملاصق للزمان واقع فيه. فالمعنى: يتوفاكم في الليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص24–25، تحت «دلالة الباء في قوله تعالى: ﴿بالليل﴾ على معنى (في) الظرفية»","url":""}]},{"id":"s6-426","number":426,"surah":6,"verses":[60],"references":[{"surah":6,"verses":[60]}],"verseLabel":"الأنعام: 60","question":"لماذا قابل النوم بقوله: ﴿ويعلم ما جرحتم بالنهار﴾؟","answer":"قوبل توفي الليل بكسب النهار لتصوير دورة الإنسان كاملة: يسكن فتقبض حواسه، ثم يبعث للعمل مع كون أعماله كلها معلومة لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص26–27، تحت «دلالة تخصيص التوفي بالليل والجرح بالنهار»","url":""}]},{"id":"s6-427","number":427,"surah":6,"verses":[60],"references":[{"surah":6,"verses":[60]}],"verseLabel":"الأنعام: 60","question":"لماذا عبّر عن الأعمال بـ﴿ما جرحتم﴾؟","answer":"عُبر عن الأعمال بـ﴿جرحتم﴾ لأن الجرح والاجتراح يدلان على الكسب والعمل بالجوارح، وأصلهما مستعار من تأثير الجارح؛ واختير الجرح هنا بدل الكسب، وهو أعم، لما فيه من الإيحاء بمباشرة العمل المكروه وتقوية التهديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص33–34، تحت «الجرح والكسب»","url":""}]},{"id":"s6-428","number":428,"surah":6,"verses":[60],"references":[{"surah":6,"verses":[60]}],"verseLabel":"الأنعام: 60","question":"ما سرّ التعبير في قوله تعالى: ﴿ثم يبعثكم فيه﴾، فجعل الاستيقاظ بعثًا؟","answer":"الاستيقاظ إعادة للحس والحركة بعد قبضهما في النوم، فسمي بعثًا لتمثيله البعث الأكبر وتقريب إمكانه بتجربة تتكرر كل يوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص30، تحت «أثر الاستعارة المرشحة في تجلية المعنى في قوله تعالى: ﴿ثم يبعثكم فيه﴾»","url":""}]},{"id":"s6-429","number":429,"surah":6,"verses":[60],"references":[{"surah":6,"verses":[60]}],"verseLabel":"الأنعام: 60","question":"إلى ماذا يعود الضمير في ﴿فيه﴾: إلى النهار أم إلى الزمن؟","answer":"على تفسير البعث بالإيقاظ من النوم يعود الضمير إلى النهار؛ أي يوقظكم فيه بعد توفي الليل، فتكتمل المقابلة بين النوم واليقظة. ويذكر المصدر وجهًا آخر يحمل البعث على البعث بعد الموت، فلا يصح إغفال اختلاف التفسير.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص29–30، تحت «دلالة عطف جملة: ﴿ثم يبعثكم فيه﴾»","url":""}]},{"id":"s6-430","number":430,"surah":6,"verses":[60],"references":[{"surah":6,"verses":[60]}],"verseLabel":"الأنعام: 60","question":"لم جعل تعاقب النوم واليقظة سبيلًا إلى ﴿ليقضى أجل مسمى﴾؟","answer":"تربط لام التعليل هذا النظام باستيفاء العمر المقدر؛ فكل نوم ويقظة يمضيان بالإنسان إلى تمام أجله. وبذلك ينتقل النظر من دورة اليوم والليلة إلى نهاية الحياة والرجوع إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص31، تحت «أثر لام التعليل في بيان المعنى في قوله تعالى: ﴿ليقضى أجل مسمى﴾»","url":""}]},{"id":"s6-431","number":431,"surah":6,"verses":[60],"references":[{"surah":6,"verses":[60]}],"verseLabel":"الأنعام: 60","question":"لماذا وصف الأجل بـ﴿مسمى﴾؟","answer":"المسمى هو المحدد المقدر الذي لا يتقدم ولا يتأخر؛ فالوصف ينفي العبث والجهالة عن أعمارهم ويقرر أن لكل حياة نهاية معلومة عند الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص31، تحت «أثر لام التعليل في بيان المعنى في قوله تعالى: ﴿ليقضى أجل مسمى﴾»","url":""}]},{"id":"s6-432","number":432,"surah":6,"verses":[60],"references":[{"surah":6,"verses":[60]}],"verseLabel":"الأنعام: 60","question":"ما دلالة الحصر بتقديم ﴿إليه﴾ في قوله تعالى: ﴿ثم إليه مرجعكم﴾؟","answer":"قدم الجار والمجرور فقصر المرجع على الله، ونفى أن يكون للخلق مآل أو ملجأ يستقلون به عن حكمه وحسابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص31، تحت عنوان «دلالة الحصر بتقديم المسند ﴿إليه﴾»","url":""}]},{"id":"s6-1190","number":1190,"surah":6,"verses":[60],"references":[{"surah":6,"verses":[60]}],"verseLabel":"الأنعام: 60","question":"ما دلالة ﴿ثم﴾ في قوله تعالى: ﴿ثم ينبئكم بما كنتم تعملون﴾؟","answer":"تدل على المهلة والترتيب؛ فالإنباء بالأعمال والحساب يأتي بعد الرجوع والحشر، لا في لحظة الموت نفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص32، تحت عنوان «دلالة (ثم) على المهلة في قوله تعالى: ﴿ثم ينبئكم بما كنتم تعملون﴾»","url":""}]},{"id":"s6-433","number":433,"surah":6,"verses":[60],"references":[{"surah":6,"verses":[60]}],"verseLabel":"الأنعام: 60","question":"ما سرّ تقديم ﴿إليه﴾ في ﴿ثم إليه مرجعكم﴾؟","answer":"قُدم ﴿إليه﴾ لقصر المرجع على الله وتأكيده؛ فلا تنتهي الخلائق إلى غير حكمه، كما لم تكن حياتهم وموتهم إلا بتدبيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص31، تحت «دلالة الحصر بتقديم المسند ﴿إليه﴾».","url":""}]},{"id":"s6-434","number":434,"surah":6,"verses":[60],"references":[{"surah":6,"verses":[60]}],"verseLabel":"الأنعام: 60","question":"ما سرّ التعبير في قوله تعالى: ﴿ينبئكم بما كنتم تعملون﴾، والله يعلم أعمالهم وهم يعرفونها؟","answer":"الإنباء ليس لإعلامهم بشيء مجهول، بل لمواجهتهم بأعمالهم مفصلة وإقامة الحجة والجزاء عليها؛ لذلك علق بما كانوا يعملون.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص32–33، تحت «ذكر بعض عناصر الحدث للكناية عن الكل في آخر الآية»","url":""}]},{"id":"s6-435","number":435,"surah":6,"verses":[61],"references":[{"surah":6,"verses":[61]}],"verseLabel":"الأنعام: 61","question":"كيف يتصل ﴿وهو القاهر فوق عباده﴾ بذكر النوم واليقظة ثم الموت؟","answer":"ينقل السياق من التصرف في نوم الإنسان ويقظته إلى بيان السلطان الذي تخضع له حياته ونهايته. فكما لا يستقل بالاستيقاظ من نومه، لا يمتنع عن الموت إذا جاء أجله؛ وكل ذلك من آثار قهر الله وتدبيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص38–39، تحت «العطف يبين قدرة الله على عباده في الحياة وعند الممات»","url":""}]},{"id":"s6-436","number":436,"surah":6,"verses":[61],"references":[{"surah":6,"verses":[61]}],"verseLabel":"الأنعام: 61","question":"لماذا عطف على القهر قوله: ﴿ويرسل عليكم حفظة﴾؟","answer":"إرسال الحفظة أثر من آثار قهره وتدبيره؛ فهم يراقبون أعمال العباد ويحفظون ما وُكل إليهم، فلا يخرج أحد عن سلطانه مع أن الحفظ نفسه عناية ورحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص40–41، تحت «عطف القصر على سابقه في قوله تعالى: ﴿ويرسل عليكم حفظة﴾»","url":""}]},{"id":"s6-437","number":437,"surah":6,"verses":[61],"references":[{"surah":6,"verses":[61]}],"verseLabel":"الأنعام: 61","question":"لماذا عُدّي إرسال الحفظة بـ﴿عليكم﴾، لا: إليكم؟","answer":"﴿عليكم﴾ تفيد الاستعلاء والرقابة والملازمة؛ فالحفظة موكلون بالعباد ومهيمنون على تسجيل أعمالهم، لا مجرد رسل يصلون إليهم ثم ينصرفون.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص41، تحت «دلالة حرف الاستعلاء (على) في قوله تعالى: ﴿ويرسل عليكم حفظة﴾».","url":""}]},{"id":"s6-438","number":438,"surah":6,"verses":[61],"references":[{"surah":6,"verses":[61]}],"verseLabel":"الأنعام: 61","question":"لم يذكر إرسال الحفظة مع أن الله يعلم أعمال العباد؟","answer":"في ذكرهم إشعار بالمراقبة وإقامة للشهادة على الأعمال، فيستحيي العبد أن تسجل عليه معصيته ويعرض بها يوم القيامة. فالحفظ زاجر وتنبيه له، وليس لأن علم الله يحتاج إلى من يكمله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص40، تحت «عطف القصر على سابقه في قوله تعالى: ﴿ويرسل عليكم حفظة﴾»","url":""}]},{"id":"s6-439","number":439,"surah":6,"verses":[61],"references":[{"surah":6,"verses":[61]}],"verseLabel":"الأنعام: 61","question":"ما سرّ التعبير في قوله تعالى: ﴿حتى إذا جاء أحدكم الموت﴾، فجعل الموت آتيًا؟","answer":"صُور الموت كآت يقصد كل إنسان ويصل إليه في موعده، فيجعل حتميته وقربه مشهدًا حيًا لا يستطيع أحد الهرب منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص43، تحت «تعلق الفعل بالضمير، في قوله تعالى: ﴿جاء أحدكم الموت توفته﴾».","url":""}]},{"id":"s6-440","number":440,"surah":6,"verses":[61],"references":[{"surah":6,"verses":[61]}],"verseLabel":"الأنعام: 61","question":"ما سرّ التعبير في قوله تعالى: ﴿أحدكم﴾، لا: الإنسان أو أحدهم؟","answer":"﴿أحدكم﴾ تفرد كل مخاطب بالموت وتجعله معنيًا بالإنذار، فلا يضيع الفرد في لفظ عام؛ وإضافته إلى ضميرهم تقرب المشهد منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص43، تحت «تعلق الفعل بالضمير في قوله تعالى: ﴿جاء أحدكم الموت توفته﴾»","url":""}]},{"id":"s6-441","number":441,"surah":6,"verses":[61],"references":[{"surah":6,"verses":[61]}],"verseLabel":"الأنعام: 61","question":"ما سرّ التعبير في قوله تعالى: ﴿توفته رسلنا﴾ بالجمع، مع قوله في موضع آخر: ﴿يتوفاكم ملك الموت﴾؟","answer":"لملك الموت أعوان من الملائكة؛ فيصح إسناد التوفي إليه باعتباره الموكل بقبض الأرواح، وإلى الرسل باعتبار أعوانه المشاركين في ذلك. فلا تعارض بين الإفراد والجمع، إذ ينظر كل تعبير إلى جهة من تنفيذ الأمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص43، تحت «دلالة ورود المضاف المشتق ﴿رسلنا﴾ في قوة النكرة»","url":""}]},{"id":"s6-442","number":442,"surah":6,"verses":[61],"references":[{"surah":6,"verses":[61]}],"verseLabel":"الأنعام: 61","question":"ما دلالة ﴿حتى﴾ في قوله تعالى: ﴿حتى إذا جاء أحدكم الموت﴾؟","answer":"جعلت مجيء الموت غاية لمدة حفظ الملائكة للإنسان في حياته، فإذا بلغ أجله انتقل السياق إلى مهمة قبض روحه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص42، تحت عنوان «دلالة ﴿حتى﴾ على الغاية في قوله تعالى: ﴿حتى إذا جاء أحدكم الموت﴾»","url":""}]},{"id":"s6-1191","number":1191,"surah":6,"verses":[61],"references":[{"surah":6,"verses":[61]}],"verseLabel":"الأنعام: 61","question":"ما دلالة ورود المضاف المشتق ﴿رسلنا﴾ في قوة النكرة؟","answer":"أفاد أن المتوفين رسل من رسل الله موكلون بهذه المهمة، من غير لزوم أن يكونوا الحفظة المذكورين قبلها أو رسولًا واحدًا بعينه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص43، تحت عنوان «دلالة ورود المضاف المشتق ﴿رسلنا﴾ في قوة النكرة»","url":""}]},{"id":"s6-443","number":443,"surah":6,"verses":[61],"references":[{"surah":6,"verses":[61]}],"verseLabel":"الأنعام: 61","question":"لماذا خُتمت الآية بـ﴿وهم لا يفرطون﴾؟","answer":"الخاتمة تنفي عن رسل الموت أي تقصير أو تأخير أو تجاوز؛ فتوفي كل نفس يقع على وفق الأمر والأجل المقدرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص44، تحت «بلاغة القيد بالحال في الإبانة في قوله تعالى: ﴿وهم لا يفرطون﴾»","url":""}]},{"id":"s6-444","number":444,"surah":6,"verses":[61],"references":[{"surah":6,"verses":[61]}],"verseLabel":"الأنعام: 61","question":"لم أُنث الفعل في ﴿توفته رسلنا﴾ مع أن الفاعل جمع رسل؟","answer":"روعي معنى الجماعة في جمع التكسير، فصح تأنيث الفعل. وجاءت قراءة ﴿توفاه﴾ بالتذكير مراعاةً لمعنى الجمع أيضًا؛ فتتنوع الصياغة مع بقاء المعنى: تتولى الرسل قبض الروح.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص44، تحت «توجيه المعنى وفقًا لاختلاف القراءة القرآنية في قوله تعالى: ﴿توفته﴾»","url":""}]},{"id":"s6-445","number":445,"surah":6,"verses":[62],"references":[{"surah":6,"verses":[62]}],"verseLabel":"الأنعام: 62","question":"لم انتقل من ﴿أحدكم﴾ إلى صيغة الغائب الجمع في ﴿ثم ردوا إلى الله﴾؟","answer":"جرى الرد على المعنى العام لأحدكم، إذ كل فرد من المخاطبين مردود إلى الله. والانتقال من الخطاب إلى الغيبة، ومن إفراد اللفظ إلى معنى الجمع، يوقظ السامع ويجدد انتباهه إلى مصير يشمل الجميع.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص49، تحت «دلالة أسلوب الالتفات في سياق الجمل المعطوفات»","url":""}]},{"id":"s6-446","number":446,"surah":6,"verses":[62],"references":[{"surah":6,"verses":[62]}],"verseLabel":"الأنعام: 62","question":"لماذا اختير فعل ﴿ردوا﴾، لا: رجعوا؟","answer":"اختير ﴿رُدّوا﴾ لأن الرد يتضمن معنى الغلبة والقوة، ولأنه هنا رد إلى الحياة بذوات الأشخاص؛ فكان أليق بمشهد بعث العباد وإعادتهم إلى الله من ﴿رجعوا﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص54، تحت «الرجوع والعودة والرد»","url":""}]},{"id":"s6-447","number":447,"surah":6,"verses":[62],"references":[{"surah":6,"verses":[62]}],"verseLabel":"الأنعام: 62","question":"لماذا وصف الله بعد الرد إليه بقوله: ﴿مولاهم الحق﴾؟","answer":"وصف الله عند ردهم إليه بأنه ﴿مولاهم﴾ لأن سلطان الملك والحكم يظهر يومئذ بلا منازع، وتسقط كل ولاية ادعوها لغيره؛ فهو الذي يتولى حسابهم ومصيرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص50، تحت «الصفة وأثرها في دقة المعنى في قوله تعالى: ﴿مولاهم الحق﴾»","url":""}]},{"id":"s6-448","number":448,"surah":6,"verses":[62],"references":[{"surah":6,"verses":[62]}],"verseLabel":"الأنعام: 62","question":"ما أثر وصف ﴿مولاهم﴾ بـ﴿الحق﴾ في دقة المعنى؟","answer":"قرر أن ولاية الله هي الولاية الثابتة الحقيقية، وأن ما اتخذوه من أولياء باطل زائل؛ فهو مولاهم خلقًا وملكًا وحكمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص50، تحت عنوان «الصفة وأثرها في دقة المعنى في قوله تعالى: ﴿مولاهم الحق﴾»","url":""}]},{"id":"s6-449","number":449,"surah":6,"verses":[62],"references":[{"surah":6,"verses":[62]}],"verseLabel":"الأنعام: 62","question":"لماذا وُصف المولى بـ﴿الحق﴾؟","answer":"﴿الحق﴾ يثبت أن ولايته وحدها ثابتة نافذة، ويكشف بطلان ما اتخذوه من أولياء؛ فلا ناصر ولا حاكم يومئذ إلا المولى الحقيقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص50، تحت «الصفة وأثرها في دقة المعنى في قوله تعالى: ﴿مولاهم الحق﴾»","url":""}]},{"id":"s6-450","number":450,"surah":6,"verses":[62],"references":[{"surah":6,"verses":[62]}],"verseLabel":"الأنعام: 62","question":"لماذا افتتح التذييل بـ﴿ألا﴾ في قوله: ﴿ألا له الحكم﴾؟","answer":"﴿ألا﴾ أداة استفتاح وتنبيه تستدعي السمع لما بعدها من حقيقة جليلة: الحكم كله لله وحده؛ وجاءت بعد مشهد الرد إليه لتؤكد انفراده بالحكم وترد أوهام المشركين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص51، تحت «دلالة أداة الاستفتاح في قوله تعالى: ﴿ألا له الحكم وهو أسرع الحاسبين﴾»","url":""}]},{"id":"s6-451","number":451,"surah":6,"verses":[62],"references":[{"surah":6,"verses":[62]}],"verseLabel":"الأنعام: 62","question":"ما دلالة الاختصاص بتقديم ﴿له﴾ في قوله تعالى: ﴿ألا له الحكم﴾؟","answer":"تقديم الجار والمجرور يقصر الحكم على الله وحده، وينفي أن يشاركه فيه ولي مزعوم أو معبود باطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص51، تحت عنوان «دلالة الاختصاص بالقصر في تقديم ﴿له﴾ في قوله تعالى: ﴿ألا له الحكم﴾»","url":""}]},{"id":"s6-452","number":452,"surah":6,"verses":[62],"references":[{"surah":6,"verses":[62]}],"verseLabel":"الأنعام: 62","question":"ما أثر عطف قوله تعالى: ﴿وهو أسرع الحاسبين﴾ على جملة التذييل قبلها؟","answer":"وصل سرعة الحساب برد الخلق إلى مولاهم الحق وانفراد الله بالحكم؛ فبين أن حكمه يعقبه حساب لا إبطاء فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص52، تحت عنوان «العطف على جملة التذييل وأثره في المعنى في قوله تعالى: ﴿وهو أسرع الحاسبين﴾»","url":""}]},{"id":"s6-1192","number":1192,"surah":6,"verses":[62],"references":[{"surah":6,"verses":[62]}],"verseLabel":"الأنعام: 62","question":"ما بلاغة التعبير بالجملة الاسمية في قوله تعالى: ﴿وهو أسرع الحاسبين﴾؟","answer":"تفيد ثبوت هذا الوصف لله ودوامه؛ فهو يحاسب الخلق جميعًا بلا انشغال بحساب عن حساب ولا عجز أو تأخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص53، تحت عنوان «بلاغة التعبير بالجملة الاسمية في قوله تعالى: ﴿وهو أسرع الحاسبين﴾»","url":""}]},{"id":"s6-453","number":453,"surah":6,"verses":[63],"references":[{"surah":6,"verses":[63]}],"verseLabel":"الأنعام: 63","question":"ما سرّ التعبير في قوله تعالى: ﴿من ينجيكم من ظلمات البر والبحر﴾، فجمع الظلمات؟","answer":"جُمعت ﴿الظلمات﴾ لتشمل ظلمات البر والبحر ومخاوفهما حقيقةً، كالليل والعدو والتيه والغرق، ومجازًا في الشدائد الهائلة التي تبطل الحواس وتدهش العقول؛ فالجمع بين المعنيين أبلغ في استيعاب صور الكرب.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص60، تحت «دلالة الحقيقة والمجاز في قوله تعالى: ﴿من ظلمات البر والبحر﴾».","url":""}]},{"id":"s6-454","number":454,"surah":6,"verses":[63],"references":[{"surah":6,"verses":[63]}],"verseLabel":"الأنعام: 63","question":"كيف تكون في البر ظلمات مع انكشافه واتساعه؟","answer":"تكون في البر ظلمات الليل، وما يصاحب السير فيه من مخاوف العدو والآفات والتيه والخسف؛ وتستعار الظلمات كذلك للشدائد الهائلة التي تبطل الحواس وتدهش العقول، فلا يمنع انكشاف البر نهارًا من صدق الظلمات عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص60–61، تحت «دلالة الحقيقة والمجاز في قوله تعالى: ﴿من ظلمات البر والبحر﴾»","url":""}]},{"id":"s6-456","number":456,"surah":6,"verses":[63],"references":[{"surah":6,"verses":[63]}],"verseLabel":"الأنعام: 63","question":"ما سرّ التعبير في قوله تعالى: ﴿تدعونه تضرعًا وخفية﴾، فجمع بين التضرع والخفية؟","answer":"التضرع إظهار الضعف والذلة، والخفية إسرار الدعاء وإبطان التذلل؛ فجمعهما لاستيعاب دعائهم جهرًا وسرًا، وبيان تنوع أحوالهم عند الشدائد وانقطاع الأسباب.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص61، تحت «دلالة العطف للألفاظ في قوله تعالى: ﴿تضرعًا وخفية﴾».","url":""}]},{"id":"s6-457","number":457,"surah":6,"verses":[63],"references":[{"surah":6,"verses":[63]}],"verseLabel":"الأنعام: 63","question":"لم عبر بـ﴿خفية﴾ عن دعائهم المستتر دون النجوى؟","answer":"الخفية أعم؛ فهي تشمل إسرار الدعاء في النفس أو خفض الصوت به من غير حديث مع شخص آخر. أما النجوى فحديث يناجي به المرء غيره، فكان لفظ الخفية أنسب بإقبالهم المستتر على الله وقت الشدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص67–68، تحت «الخفية والنجوى والسر»","url":""}]},{"id":"s6-458","number":458,"surah":6,"verses":[63],"references":[{"surah":6,"verses":[63]}],"verseLabel":"الأنعام: 63","question":"لماذا انتقل من خطاب الجمع إلى حكاية قولهم: ﴿لئن أنجانا من هذه﴾؟","answer":"جاءت ﴿لئن أنجانا من هذه﴾ حكايةً لقولهم حال الدعاء، أي: تدعونه قائلين ذلك؛ وحُذفت ألفاظ القول لوضوح من قال ومن حكى، فصُوّر فحوى وعدهم في موقف الكرب الشديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص62، تحت «دلالة النصب بإرادة القول: ﴿لئن أنجانا من هذه لنكونن من الشاكرين﴾».","url":""}]},{"id":"s6-459","number":459,"surah":6,"verses":[63],"references":[{"surah":6,"verses":[63]}],"verseLabel":"الأنعام: 63","question":"إلى ماذا تشير ﴿هذه﴾ في ﴿لئن أنجانا من هذه﴾؟","answer":"تشير ﴿هذه﴾ إلى الظلمات أو الشدة الحاضرة التي أحاطت بهم؛ واسم الإشارة يستحضرها كأنها ماثلة أمامهم ويبرز قربها وهولها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص63–64، تحت «اعتبارات فهم اسم الإشارة في قوله: ﴿لئن أنجانا من هذه﴾»","url":""}]},{"id":"s6-460","number":460,"surah":6,"verses":[63],"references":[{"surah":6,"verses":[63]}],"verseLabel":"الأنعام: 63","question":"لماذا أكدوا وعدهم باللام والنون: ﴿لنكونن من الشاكرين﴾؟","answer":"اللام موطئة للقسم، ونون التوكيد الثقيلة تثبت الوعد؛ فشدة الكرب حملتهم على أغلظ صيغة في التعهد بالشكر إن وقعت النجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص62، تحت «دلالة أسلوب القسم في قوله تعالى: ﴿لئن أنجانا من هذه لنكونن من الشاكرين﴾».","url":""}]},{"id":"s6-461","number":461,"surah":6,"verses":[63],"references":[{"surah":6,"verses":[63]}],"verseLabel":"الأنعام: 63","question":"ما دلالة تعبيرهم بقوله: ﴿لنكونن من الشاكرين﴾، دون: لنشكرن؟","answer":"قولهم ﴿من الشاكرين﴾ يتعهد بأن يكونوا ثابتين في زمرة عُرفت بالشكر، وهو أبلغ من وعد بفعل شكر مرة واحدة؛ ثم يكشف رجوعهم إلى الشرك كذب هذا التعهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص64، تحت «دلالة التعبير بحرف الجر ﴿من﴾ مع إمكان الاستغناء عنه لغة»","url":""}]},{"id":"s6-462","number":462,"surah":6,"verses":[64],"references":[{"surah":6,"verses":[64]}],"verseLabel":"الأنعام: 64","question":"لماذا جاء الجواب صريحًا: ﴿قل الله ينجيكم منها﴾، ولم يقل: هو ينجيكم؟","answer":"ذكر اسم الله جوابًا مباشرًا عن ﴿من ينجيكم﴾، وهو جواب يعرفه المخاطبون ويقرون به عند الشدة. فصرح به لإقامة الحجة عليهم من اعترافهم، قبل توبيخهم على عودتهم إلى الشرك.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص64، تحت «فصل جملة: ﴿قل الله ينجيكم منها﴾ لجريانها مجرى القول في المحاورة»","url":""}]},{"id":"s6-463","number":463,"surah":6,"verses":[64],"references":[{"surah":6,"verses":[64]}],"verseLabel":"الأنعام: 64","question":"ما سرّ التعبير في قوله تعالى: ﴿منها ومن كل كرب﴾، فعطف العام على الخاص؟","answer":"عطف ﴿من كل كرب﴾ تعميم بعد تخصيص؛ فبعد إنجائهم من تلك الشدة يذكرهم بأن كل ضيق سواها لا يكشفه على الحقيقة إلا الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص65، تحت «دلالة عطف شبه الجملة ﴿ومن كل كرب﴾ على الضمير في ﴿منها﴾»","url":""}]},{"id":"s6-464","number":464,"surah":6,"verses":[64],"references":[{"surah":6,"verses":[64]}],"verseLabel":"الأنعام: 64","question":"لماذا اختير لفظ ﴿كرب﴾ بعد ظلمات البر والبحر؟","answer":"الكرب هو الغم الشديد الذي يضيق به الصدر كأنه يعقد النفس؛ فناسب ظلمات البر والبحر بما تثيره من خوف واختناق وحيرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص68، تحت «الكرب والحزن»","url":""}]},{"id":"s6-465","number":465,"surah":6,"verses":[64],"references":[{"surah":6,"verses":[64]}],"verseLabel":"الأنعام: 64","question":"لماذا أعقب النجاة بقوله: ﴿ثم أنتم تشركون﴾؟","answer":"﴿ثم﴾ للتراخي الرتبي والاستبعاد؛ فبعد اعترافهم بالله ووعدهم بالشكر كان المتوقع التوحيد، فجاء الشرك بعيدًا في القبح عن مقدمة النجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص66، تحت «دلالة ﴿ثم﴾ في قوله: ﴿ثم أنتم تشركون﴾»","url":""}]},{"id":"s6-466","number":466,"surah":6,"verses":[64],"references":[{"surah":6,"verses":[64]}],"verseLabel":"الأنعام: 64","question":"لماذا أظهر الضمير ﴿أنتم﴾ في ﴿ثم أنتم تشركون﴾؟","answer":"إظهار ﴿أنتم﴾ يقوي نسبة الشرك إليهم ويعجب من فعلهم هم خاصة بعد أن دعوا الله وحده؛ فلا ينسب رجوعهم إلى غموض الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص66–67، تحت «تقديم المسند إليه على الخبر الفعلي في قوله تعالى: ﴿ثم أنتم تشركون﴾»","url":""}]},{"id":"s6-467","number":467,"surah":6,"verses":[65],"references":[{"surah":6,"verses":[65]}],"verseLabel":"الأنعام: 65","question":"ما سرّ التعبير في قوله تعالى: ﴿قل هو القادر﴾ بإظهار الضمير ﴿هو﴾؟","answer":"اجتمع تعريف المبتدأ ﴿هو﴾ والخبر ﴿القادر﴾ لإفادة الاختصاص في هذا المقام: هو وحده القادر على هذا العذاب، وأصنامهم لا تملك شيئًا منه. فالذي يملك النجاة يملك إنزال العذاب، فيجتمع الوعد والتهديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص72–73، تحت «التعبير بأسلوب القصر على كمال قدرة الله»","url":""}]},{"id":"s6-468","number":468,"surah":6,"verses":[65],"references":[{"surah":6,"verses":[65]}],"verseLabel":"الأنعام: 65","question":"لم قدم ﴿عليكم﴾ على ﴿عذابًا﴾ في قوله: ﴿أن يبعث عليكم عذابًا﴾؟","answer":"للعناية بالمخاطبين والمسارعة إلى بيان أن العذاب متوجه إليهم هم. فيبرز التقديم موضع التهديد، ويجعل السامع يترقب نوع ما قد ينزل به قبل التصريح بالعذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص73، تحت «تقديم شبه الجملة ﴿عليكم﴾ على مفعول الفعل الصريح ﴿عذابًا﴾»","url":""}]},{"id":"s6-469","number":469,"surah":6,"verses":[65],"references":[{"surah":6,"verses":[65]}],"verseLabel":"الأنعام: 65","question":"لماذا قُسّم العذاب إلى ﴿من فوقكم﴾ و﴿من تحت أرجلكم﴾؟","answer":"قسّم العذاب إلى ما يأتي من فوق وما ينبع من تحت لاستيعاب الجهات وإحاطة القدرة؛ فلا تحميهم سماء ولا أرض من أمر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص73، تحت «دلالة تصوير العذاب بأنه آتٍ من أعلى أو من أسفل».","url":""}]},{"id":"s6-470","number":470,"surah":6,"verses":[65],"references":[{"surah":6,"verses":[65]}],"verseLabel":"الأنعام: 65","question":"ما المعنى الكنائي الذي يحتمله ﴿من تحت أرجلكم﴾ في تصوير العذاب؟","answer":"يحمل على ما ينزل بهم من هوان ونكبات تأتيهم من جهة الأسفل، في مقابل عذاب يأتي من فوقهم. وتعدد الصورتين تهديد بأن عذاب الله متى نزل لم يكن لهم ملجأ يرده.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص74، تحت «دلالة الكناية في قوله تعالى: ﴿أو من تحت أرجلكم﴾»","url":""}]},{"id":"s6-471","number":471,"surah":6,"verses":[65],"references":[{"surah":6,"verses":[65]}],"verseLabel":"الأنعام: 65","question":"لماذا عطف النوعين الأولين بـ﴿أو﴾ ثم قال: ﴿أو يلبسكم شيعًا﴾؟","answer":"تكرر ﴿أو﴾ لتقسيم صور العذاب الممكنة: عذاب من فوق، أو من تحت، أو تفريق داخلي؛ وكل واحد منها مقدور لله وقد يقع مستقلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص74، تحت «دلالة العطف بالحرف ﴿أو﴾ وأثرها في المعنى»","url":""}]},{"id":"s6-472","number":472,"surah":6,"verses":[65],"references":[{"surah":6,"verses":[65]}],"verseLabel":"الأنعام: 65","question":"لماذا عبّر عن تفريق الناس بقوله: ﴿يلبسكم شيعًا﴾؟","answer":"اللبس هو الخلط والإشكال؛ فـ﴿يلبسكم شيعًا﴾ يصور الجماعة الواحدة وقد خلطت فرقًا متنازعة لا يتميز لها طريق جامع.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص74–75، تحت «بلاغة التعبير بلفظ: ﴿يلبسكم﴾»","url":""}]},{"id":"s6-473","number":473,"surah":6,"verses":[65],"references":[{"surah":6,"verses":[65]}],"verseLabel":"الأنعام: 65","question":"لم اختير لفظ ﴿شيعًا﴾ بدل فرقًا في تصوير تفرقهم؟","answer":"الشيعة جماعة يتقوى بعض أفرادها ببعض ويشدون أزر بعضهم، وقد تتبع أهواء متعددة. فالتعبير يصور جماعات متكتلة متنازعة، لا مجرد انفصال أفراد؛ أما الفرقة فيغلب فيها معنى المفارقة والانفصال.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص77، تحت «(شيعًا) و(فرقًا)»","url":""}]},{"id":"s6-474","number":474,"surah":6,"verses":[65],"references":[{"surah":6,"verses":[65]}],"verseLabel":"الأنعام: 65","question":"ما سرّ التعبير في قوله تعالى: ﴿ويذيق بعضكم بأس بعض﴾، فجعل الحرب ذوقًا؟","answer":"استعيرت الإذاقة للألم، وصُوّر التناوش والقتال بين الفرق كالمأكول الذي يذيقه بعضهم بعضًا؛ تهويلًا لأمر النزاع وتعظيمًا لألم الخصام والعذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص75، تحت «بلاغة الاستعارة المكنية في قوله تعالى: ﴿ويذيق بعضكم بأس بعض﴾»","url":""}]},{"id":"s6-475","number":475,"surah":6,"verses":[65],"references":[{"surah":6,"verses":[65]}],"verseLabel":"الأنعام: 65","question":"لماذا كرر ﴿بعض﴾ في ﴿بعضكم بأس بعض﴾؟","answer":"كرر ﴿بعض﴾ لتعيين طرفي البأس: بعضٌ يذيق، وبعضٌ آخر يذوق بأسه؛ فصوّر تسليط طائفة على أخرى بالقتل والعذاب، وفي ذلك وعيد للمعتدين ووعد للمؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص75، تحت «بلاغة الاستعارة المكنية في قوله تعالى: ﴿ويذيق بعضكم بأس بعض﴾»","url":""}]},{"id":"s6-476","number":476,"surah":6,"verses":[65],"references":[{"surah":6,"verses":[65]}],"verseLabel":"الأنعام: 65","question":"لم أُمر بالنظر في ﴿انظر كيف نصرف الآيات﴾ مع أن آيات القرآن تُسمع؟","answer":"نُزل تنوع الدلائل المعقول منزلة المشهد المحسوس، فدعا إلى تأمله كأنه يراه. والمراد التنبيه والتعجيب من عرض الحجة بوجوه من الترغيب والترهيب، ليصل المتأمل إلى الفهم والرجوع إلى الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص75–76، تحت «تنزيل المعقول منزلة المحسوس في النظر إلى تصريف الآيات»","url":""}]},{"id":"s6-477","number":477,"surah":6,"verses":[65],"references":[{"surah":6,"verses":[65]}],"verseLabel":"الأنعام: 65","question":"لم ختم تصريف الآيات بـ﴿لعلهم يفقهون﴾ بدل يعلمون؟","answer":"الفقه أخص من مطلق العلم؛ فهو فهم مقتضى الكلام عن تأمل. فالمقصود أن يتجاوزوا سماع الآيات إلى النظر في دلائلها والوصول إلى الحق والتزامه، وهو ما يناسب تنويع البيان وتصريف الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص78–79، تحت «(يفقهون) و(يعلمون)»","url":""}]},{"id":"s6-478","number":478,"surah":6,"verses":[66],"references":[{"surah":6,"verses":[66]}],"verseLabel":"الأنعام: 66","question":"ما سرّ التعبير في قوله تعالى: ﴿وكذب به قومك﴾، وإلى ماذا يعود الضمير في ﴿به﴾؟","answer":"يحتمل الضمير العذاب الموعود في الآيات السابقة، ويحتمل القرآن المتضمن خبره وسائر العقيدة والشريعة؛ والمعنيان متلازمان، إذ كذبوا بالكتاب وبوعيده.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص81، تحت «عودة الضميرين في قوله تعالى: ﴿وكذب به قومك﴾ وأثرهما في المعنى».","url":""}]},{"id":"s6-479","number":479,"surah":6,"verses":[66],"references":[{"surah":6,"verses":[66]}],"verseLabel":"الأنعام: 66","question":"ما أثر عطف المباني في تعانق معاني الآيات المتوالية؟","answer":"وصل العطف بين دلائل القدرة وموقف المكذبين وما يترتب عليه، فجعل المعاني المتتابعة بناءً واحدًا تتساند أجزاؤه في إقامة الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص81، تحت عنوان «تعانق المعاني بعطف المباني في الآيات المتوالية»","url":""}]},{"id":"s6-1193","number":1193,"surah":6,"verses":[66],"references":[{"surah":6,"verses":[66]}],"verseLabel":"الأنعام: 66","question":"إلى ماذا يعود الضميران في قوله تعالى: ﴿وكذب به قومك﴾، وما أثر ذلك؟","answer":"يعود ضمير ﴿به﴾ إلى القرآن أو الحق المعلوم من السياق، وضمير الخطاب في ﴿قومك﴾ إلى النبي ﷺ؛ وفي الإضافة تشنيع لتكذيب من عرفوا صدقه وقربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص81–82، تحت عنوان «عودة الضميرين في قوله تعالى: ﴿وكذب به قومك﴾، وأثرهما في المعنى»","url":""}]},{"id":"s6-480","number":480,"surah":6,"verses":[66],"references":[{"surah":6,"verses":[66]}],"verseLabel":"الأنعام: 66","question":"لماذا اعترض بقوله: ﴿وهو الحق﴾ بين التكذيب والأمر بالجواب؟","answer":"جملة ﴿وهو الحق﴾ اعتراض يثبت حقيقة ما كذبوا به ويعجل بيانها؛ فالتكذيب لا يغير ثبوته، بل يضاعف قبح فعلهم لأنهم قابلوا الحق المبين بالإنكار.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص82، تحت «بلاغة الاعتراض بقوله تعالى: ﴿وهو الحق﴾».","url":""}]},{"id":"s6-481","number":481,"surah":6,"verses":[66],"references":[{"surah":6,"verses":[66]}],"verseLabel":"الأنعام: 66","question":"ما سرّ التعبير في قوله تعالى: ﴿لست عليكم بوكيل﴾، دون أن يقال: لست وكيلكم؟","answer":"تدل ﴿عليكم﴾ على معنى الاستعلاء والسلطان المنفي عنه هنا؛ فليس قيّمًا يجبرهم على الإيمان أو يمنعهم من التكذيب. وإبرازها في التركيب يوجه النفي إلى هذا التسلط، مع بقاء وظيفته في البلاغ والإنذار.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص82–83، تحت «أثر أسلوب الأمر في ثراء المعنى وبيانه»","url":""}]},{"id":"s6-482","number":482,"surah":6,"verses":[66],"references":[{"surah":6,"verses":[66]}],"verseLabel":"الأنعام: 66","question":"لماذا دخلت الباء على ﴿وكيل﴾؟","answer":"تؤكد الباء نفي ملابسة صفة الوكيل له في هذا المقام؛ فكأن المعنى: لست متعلقًا بكم تعلق من يتولى أعمالكم وحسابكم. ويشرح المصدر هذا من أصل معنى الإلصاق في الباء، مع تقرير أن عليه البلاغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص82–83، تحت «أثر أسلوب الأمر في ثراء المعنى وبيانه»","url":""}]},{"id":"s6-483","number":483,"surah":6,"verses":[67],"references":[{"surah":6,"verses":[67]}],"verseLabel":"الأنعام: 67","question":"ما سرّ التعبير في قوله تعالى: ﴿لكل نبإ مستقر﴾، دون أن يقال: لكل خبر؟","answer":"النبأ خبر عظيم له شأن ونتيجة، وهو أنسب بالوعيد والوحي من مطلق الخبر؛ فلكل نبأ إلهي وقت يظهر فيه صدقه ويقع مضمونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص85، تحت «ما ورد من توجيه لغوي في قوله تعالى: ﴿لكل نبإ مستقر﴾».","url":""}]},{"id":"s6-484","number":484,"surah":6,"verses":[67],"references":[{"surah":6,"verses":[67]}],"verseLabel":"الأنعام: 67","question":"لم قدم ﴿لكل نبإ﴾ على ﴿مستقر﴾؟","answer":"للعناية بالنبأ وتأكيد أن لكل خبر من أخبار الوحي حقيقة وغاية ينتهي إليها. فالتقديم يربط كل نبأ بتحققه، ويطمئن إلى أن تأخر وقوع الوعيد لا يبطله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص85، تحت «ما ورد من توجيه لغوي في قوله تعالى: ﴿لكل نبإ مستقر﴾»","url":""}]},{"id":"s6-485","number":485,"surah":6,"verses":[67],"references":[{"surah":6,"verses":[67]}],"verseLabel":"الأنعام: 67","question":"ما التوجيه اللغوي لقوله تعالى: ﴿لكل نبإ مستقر﴾؟","answer":"مستقر النبأ وقت تحقق مضمونه أو غايته التي ينتهي إليها؛ فصوّر الخبر كأنه يسير إلى موضع يستقر فيه صدقه واقعًا مشهودًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص85، تحت عنوان «ما ورد من توجيه لغوي في قوله تعالى: ﴿لكل نبإ مستقر﴾»","url":""}]},{"id":"s6-486","number":486,"surah":6,"verses":[67],"references":[{"surah":6,"verses":[67]}],"verseLabel":"الأنعام: 67","question":"لماذا خُتم الوعيد بقوله: ﴿وسوف تعلمون﴾، ولم يذكر ما سيعلمونه؟","answer":"يدل المقام على ما سيعلمونه: صدق ما أخبرهم به الوحي ووقوع ما وُعدوا به من الجزاء. فالمقصود تهديدهم بأن ما ينكرونه الآن سيصير علمًا يشهدونه، وأن وعيد الله واقع لا يتخلف.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص86، تحت «دلالة ﴿وسوف﴾ في الجملة المعطوفة»","url":""}]},{"id":"s6-487","number":487,"surah":6,"verses":[67],"references":[{"surah":6,"verses":[67]}],"verseLabel":"الأنعام: 67","question":"ما دلالة الاستقبال في ﴿وسوف تعلمون﴾ بعد ﴿لكل نبإ مستقر﴾؟","answer":"يدل على تحقق العلم في وقت آت، ولا يحدد بنفسه مقدار الزمن. فهو يمهل وقوع المشهد إلى مستقره المقدر مع توكيد الوعيد؛ فلا يجعل التأخر دليلًا على عدم الوقوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص86، تحت «دلالة ﴿وسوف﴾ في الجملة المعطوفة»","url":""}]},{"id":"s6-488","number":488,"surah":6,"verses":[68],"references":[{"surah":6,"verses":[68]}],"verseLabel":"الأنعام: 68","question":"ما سرّ التعبير في قوله تعالى: ﴿وإذا رأيت الذين يخوضون في آياتنا﴾، فعبّر عن كلامهم بالخوض؟","answer":"الخوض أصله الدخول في الماء والاضطراب فيه بلا ثبات، فاستعير لحديثهم في الآيات بالباطل؛ يصورهم منغمسين في جدل مضطرب لا يقصد الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص90، تحت «دلالة الاستعارة في قوله تعالى: ﴿يخوضون في آياتنا﴾»","url":""}]},{"id":"s6-489","number":489,"surah":6,"verses":[68],"references":[{"surah":6,"verses":[68]}],"verseLabel":"الأنعام: 68","question":"ما دلالة الاستعارة في قوله تعالى: ﴿يخوضون في آياتنا﴾؟","answer":"استعير الخوض في الماء للدخول والتوغل في الحديث بالباطل؛ فصورهم منغمسين فيه من غير تثبت أو هدى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص90، تحت عنوان «دلالة الاستعارة في قوله تعالى: ﴿يخوضون في آياتنا﴾»","url":""}]},{"id":"s6-490","number":490,"surah":6,"verses":[68],"references":[{"surah":6,"verses":[68]}],"verseLabel":"الأنعام: 68","question":"ما سرّ التعبير في قوله تعالى: ﴿فأعرض عنهم﴾، ولم يأمره بالرد عليهم؟","answer":"أُمر بالإعراض لأن مجلس الاستهزاء ليس مقام طلب حق ينفع معه الجدل؛ ومفارقته إنكار عملي يحفظ حرمة الآيات ولا يمنح باطلهم شرعية الإصغاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص88–89، تحت «دلالة الاسم الموصول في الجملة المعطوفة على الآيات السابقة»","url":""}]},{"id":"s6-491","number":491,"surah":6,"verses":[68],"references":[{"surah":6,"verses":[68]}],"verseLabel":"الأنعام: 68","question":"لماذا جعل غاية الإعراض: ﴿حتى يخوضوا في حديث غيره﴾؟","answer":"جعل الإعراض مؤقتًا بانتهاء الخوض ليبين أن المنهي عنه مجالستهم حال الاستهزاء لا مقاطعتهم مطلقًا؛ فإذا انتقلوا إلى حديث غيره زال سبب الحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص90–91، تحت «دلالة ﴿حتى﴾ على الغاية في قوله تعالى: ﴿حتى يخوضوا في حديث غيره﴾»","url":""}]},{"id":"s6-492","number":492,"surah":6,"verses":[68],"references":[{"surah":6,"verses":[68]}],"verseLabel":"الأنعام: 68","question":"لماذا أعاد فعل ﴿يخوضوا﴾ مع الحديث الآخر؟","answer":"أعيد ﴿يخوضوا﴾ لأن الخوض وصف عادتهم في الكلام، ولو انتقل متعلقه؛ لكن الممنوع هنا خوضهم في آيات الله خاصة، فيزول المنع بتغير الحديث.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص90–91، تحت «دلالة حتى على الغاية في حتى يخوضوا في حديث غيره»","url":""}]},{"id":"s6-493","number":493,"surah":6,"verses":[68],"references":[{"surah":6,"verses":[68]}],"verseLabel":"الأنعام: 68","question":"لماذا نُسب النسيان إلى الشيطان: ﴿وإما ينسينك الشيطان﴾؟","answer":"جاء إسناد الإنساء إلى الشيطان في سياق الشرط لزيادة تأكيد الأمر بالإعراض عند التذكر، مع بقاء النسيان عارضًا بشريًا لا مؤاخذة فيه، وقد عصم الله رسوله من وسوسة الشيطان في عمله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص92، تحت «عطف حالة النسيان لتأكيد الأمر بالإعراض عن الخوض المذموم»","url":""}]},{"id":"s6-494","number":494,"surah":6,"verses":[68],"references":[{"surah":6,"verses":[68]}],"verseLabel":"الأنعام: 68","question":"ما أثر عطف حالة النسيان في تأكيد الأمر بالإعراض عن الخوض المذموم؟","answer":"بيّن أن النسيان عذر عارض فقط؛ فإذا وقع التذكر وجب ترك المجلس، فشمل الأمر حال القصد وحدد انتهاء العذر.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص92، تحت عنوان «عطف حالة النسيان لتأكيد الأمر بالإعراض عن الخوض المذموم»","url":""}]},{"id":"s6-1194","number":1194,"surah":6,"verses":[68],"references":[{"surah":6,"verses":[68]}],"verseLabel":"الأنعام: 68","question":"ما بلاغة وضع الاسم الظاهر موضع الضمير في قوله تعالى: ﴿مع القوم الظالمين﴾؟","answer":"صرح بوصف الظلم بدل أن يقال «معهم»؛ ليسجل علة النهي عن القعود معهم ويعم الحكم كل من اتصف بهذا الخوض.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص93، تحت عنوان «وضع المظهر موضع المضمر في قوله تعالى: ﴿مع القوم الظالمين﴾»","url":""}]},{"id":"s6-495","number":495,"surah":6,"verses":[68],"references":[{"surah":6,"verses":[68]}],"verseLabel":"الأنعام: 68","question":"لماذا أظهر وصفهم فقال: ﴿مع القوم الظالمين﴾، ولم يقل: معهم؟","answer":"أُظهر وصفهم فقيل ﴿مع القوم الظالمين﴾ بدل: معهم، لزيادة فائدة وصفهم بالظلم وبيان أن خوضهم في آيات الله ظلم، وأن النهي عن القعود معهم معلل بهذه الحال.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص93، تحت «وضع المظهر موضع المضمر، في قوله تعالى: ﴿مع القوم الظالمين﴾».","url":""}]},{"id":"s6-496","number":496,"surah":6,"verses":[69],"references":[{"surah":6,"verses":[69]}],"verseLabel":"الأنعام: 69","question":"ما سرّ التعبير في قوله تعالى: ﴿وما على الذين يتقون من حسابهم من شيء﴾ بتكرار ﴿من﴾؟","answer":"تعلقت ﴿من حسابهم﴾ بالحساب المنفي عن المتقين، ثم زيدت ﴿من﴾ قبل ﴿شيء﴾ في سياق النفي لتأكيد الاستغراق؛ أي ليس عليهم أدنى شيء من حساب الخائضين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص98، تحت «السر في استغراق النفي والتنكير، في قوله: ﴿من شيء﴾».","url":""}]},{"id":"s6-497","number":497,"surah":6,"verses":[69],"references":[{"surah":6,"verses":[69]}],"verseLabel":"الأنعام: 69","question":"ما بلاغة الاستدراك في قوله تعالى: ﴿ولكن ذكرى﴾؟","answer":"بعد نفي تحمل المتقين شيئًا من حساب الخائضين، استدرك فأثبت عليهم التذكير والإنكار؛ فانتفاء المؤاخذة لا يعني ترك النصيحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص98، تحت عنوان «بلاغة الاستدراك في قوله: ﴿ولكن﴾»","url":""}]},{"id":"s6-1195","number":1195,"surah":6,"verses":[69],"references":[{"surah":6,"verses":[69]}],"verseLabel":"الأنعام: 69","question":"ما أثر احتمال الحالية والعطف في لفظ ﴿ذكرى﴾؟","answer":"على الحالية يكون المعنى الإعراض حال كون المقصود تذكيرهم، وعلى العطف يثبت واجب الذكرى بعد نفي الحساب؛ والوجهان يجمعان الإنكار مع المفارقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص99، تحت عنوان «لفظ ﴿ذكرى﴾ بين الحالية والعطف، وأثره في المعنى»","url":""}]},{"id":"s6-498","number":498,"surah":6,"verses":[69],"references":[{"surah":6,"verses":[69]}],"verseLabel":"الأنعام: 69","question":"لماذا حُذف فعل الأمر أو الخبر قبل ﴿ذكرى﴾؟","answer":"﴿ذكرى﴾ مصدر ناب عن فعل محذوف، والتقدير: ولكن ذكّروهم ذكرى، أو: ولكن عليهم ذكرى. وحذفه أوجز وأجمع لمعنيي التذكير والاتعاظ.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص100، تحت «دلالة اختيار المصدر: ﴿ذكرى﴾».","url":""}]},{"id":"s6-499","number":499,"surah":6,"verses":[69],"references":[{"surah":6,"verses":[69]}],"verseLabel":"الأنعام: 69","question":"ما بلاغة الاستئناف في قوله تعالى: ﴿لعلهم يتقون﴾؟","answer":"استأنف لبيان الغاية المرجوة من التذكير والإعراض، وهي أن يترك الخائضون باطلهم ويتقوا سببه وعاقبته.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص100، تحت عنوان «بلاغة الاستئناف في قوله: ﴿لعلهم يتقون﴾»","url":""}]},{"id":"s6-1196","number":1196,"surah":6,"verses":[69],"references":[{"surah":6,"verses":[69]}],"verseLabel":"الأنعام: 69","question":"لماذا عُلّق الرجاء بالخائضين في قوله تعالى: ﴿لعلهم يتقون﴾؟","answer":"لأن تذكير المتقين وامتناعهم عن مجالستهم قد يردع الخائضين ويحملهم على ترك الخوض، فالضمير يوجه الرجاء إلى من يحتاج إلى التقوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص100، تحت عنوان «علة تعليق الرجاء بالخائضين»","url":""}]},{"id":"s6-500","number":500,"surah":6,"verses":[70],"references":[{"surah":6,"verses":[70]}],"verseLabel":"الأنعام: 70","question":"ما سرّ التعبير في قوله تعالى: ﴿وذر الذين اتخذوا دينهم لعبًا ولهوًا﴾، دون أن يقال: اتركهم؟","answer":"اختير ﴿ذر﴾ لما فيه من معنى الإعراض وعدم الاعتداد: دعهم ولا تبال بتكذيبهم واستهزائهم، ولا تشغل نفسك بلغوهم، مع الاستمرار في تذكيرهم وبلاغهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص102، تحت «شرح المفردات»، مادة «﴿وذر﴾».","url":""}]},{"id":"s6-501","number":501,"surah":6,"verses":[70],"references":[{"surah":6,"verses":[70]}],"verseLabel":"الأنعام: 70","question":"كيف اتخذ الخائضون دينهم لعبًا ولهوًا؟","answer":"عاملوا ما يجب تعظيمه بالسخرية والعبث، أو جعلوا أهواءهم وعاداتهم التي يلهون بها بمنزلة الدين، فلم يحملهم على جد أو عمل للآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص108–109، تحت عنوان «كيفية اتخاذ الخائضين الدين لعبًا ولهوًا»","url":""}]},{"id":"s6-1197","number":1197,"surah":6,"verses":[70],"references":[{"surah":6,"verses":[70]}],"verseLabel":"الأنعام: 70","question":"ما سر التعبير عن الكفر باتخاذ الدين لعبًا ولهوًا؟","answer":"كشف التعبير أن كفرهم لم يكن بحثًا جادًا عن الحق، بل تحويلًا للدين عن غايته إلى العبث والانشغال بما يصد عن الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص109، تحت عنوان «سر التعبير عن الكفر باتخاذ الدين لعبًا ولهوًا»","url":""}]},{"id":"s6-502","number":502,"surah":6,"verses":[70],"references":[{"surah":6,"verses":[70]}],"verseLabel":"الأنعام: 70","question":"ما سرّ تقديم ﴿اللعب﴾ على ﴿اللهو﴾ كما في الآية 32؟","answer":"قُدّم ﴿اللعب﴾ على ﴿اللهو﴾ هنا وفي نظائره مراعاةً للترتيب الزمني؛ لأن زمن اللعب ـ وهو الصبا ـ يسبق زمن اللهو ـ وهو الشباب ـ فجاء اللفظ على ترتيب الأصل.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص126، تحت «بلاغة التشابه اللفظي».","url":""}]},{"id":"s6-503","number":503,"surah":6,"verses":[70],"references":[{"surah":6,"verses":[70]}],"verseLabel":"الأنعام: 70","question":"ما سرّ التعبير في قوله تعالى: ﴿وغرتهم الحياة الدنيا﴾، فجعل الحياة نفسها غارّة؟","answer":"أُسند الغرور إلى الحياة الدنيا على سبيل المجاز العقلي؛ لأنها بلذاتها وشهواتها كانت سبب اغترارهم بها حتى اطمأنوا إليها وظنوا ألا حياة بعدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص111، تحت «نكتة المجاز في إسناد الغرور إلى الحياة الدنيا».","url":""}]},{"id":"s6-504","number":504,"surah":6,"verses":[70],"references":[{"surah":6,"verses":[70]}],"verseLabel":"الأنعام: 70","question":"لماذا أعقب الأمر بتركهم بقوله: ﴿وذكر به﴾؟","answer":"ترك مجالس المستهزئين لا يعني ترك دعوتهم؛ لذلك عطف ﴿وذكر به﴾ ليجمع بين الإعراض عن عبثهم ومواصلة إنذارهم بالقرآن، فلا تتحول المفاصلة إلى إهمال للبلاغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص113، تحت «فائدة الأمر بالتذكير، بعد الأمر بترك الخائضين».","url":""}]},{"id":"s6-505","number":505,"surah":6,"verses":[70],"references":[{"surah":6,"verses":[70]}],"verseLabel":"الأنعام: 70","question":"إلى ماذا يعود الضمير في ﴿وذكر به﴾؟","answer":"الضمير في ﴿به﴾ يعود إلى القرآن، دل عليه السياق وإن لم يسبق له ذكر صريح؛ فهو أداة التذكير بالبعث والنعيم والعذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص112، تحت «نكتة الإضمار في محل الإظهار، في قوله: ﴿وذكر به﴾».","url":""}]},{"id":"s6-506","number":506,"surah":6,"verses":[70],"references":[{"surah":6,"verses":[70]}],"verseLabel":"الأنعام: 70","question":"ما سر بناء ﴿أبسلوا﴾ للمجهول؟","answer":"ركز البناء للمجهول على وقوع الإبسال بالنفوس وسوء مصيرها، مع العلم بأن الله هو الذي يسلمها للعذاب جزاء بما كسبت.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص120، تحت عنوان «السر في بناء ﴿أبسلوا﴾ للمجهول»","url":""}]},{"id":"s6-507","number":507,"surah":6,"verses":[70],"references":[{"surah":6,"verses":[70]}],"verseLabel":"الأنعام: 70","question":"لماذا نُكرت ﴿نفس﴾؟","answer":"نُكرت ﴿نفس﴾ للعموم؛ أي لئلا تسلم أي نفس إلى الهلاك بما كسبت، مهما كان صاحبها، فالمسؤولية فردية شاملة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص114، تحت «إيثار التنكير في قوله: ﴿نفس﴾».","url":""}]},{"id":"s6-508","number":508,"surah":6,"verses":[70],"references":[{"surah":6,"verses":[70]}],"verseLabel":"الأنعام: 70","question":"ما دلالة الباء في قوله تعالى: ﴿بما كسبوا﴾؟","answer":"هي للسببية؛ فإبسالهم وعذابهم ناشئان عن أعمالهم التي اكتسبوها باختيارهم، لا عن ظلم وقع عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص121، تحت عنوان «دلالة الباء في قوله: ﴿بما كسبوا﴾»","url":""}]},{"id":"s6-1198","number":1198,"surah":6,"verses":[70],"references":[{"surah":6,"verses":[70]}],"verseLabel":"الأنعام: 70","question":"ما فائدة التعبير بـ﴿ما﴾ في قوله تعالى: ﴿بما كسبوا﴾؟","answer":"أبهم الموصول جنس ما كسبوه ليعم أعمالهم الباطلة كلها، ويجعل الجزاء متعلقًا بكل ما دخل في هذا الكسب.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص121، تحت عنوان «فائدة التعبير بـ﴿بما﴾»","url":""}]},{"id":"s6-1199","number":1199,"surah":6,"verses":[70],"references":[{"surah":6,"verses":[70]}],"verseLabel":"الأنعام: 70","question":"ما الفرق بين الكسب والفعل؟","answer":"الفعل أعم في مجرد وقوع الحدث، أما الكسب فيلحظ قصد الفاعل وتحصيله أثرًا لنفسه؛ لذلك ناسب مقام تحميل الإنسان تبعة عمله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص127–128، تحت عنوان «الفروق المعجمية: (الكسب) و(الفعل)»","url":""}]},{"id":"s6-509","number":509,"surah":6,"verses":[70],"references":[{"surah":6,"verses":[70]}],"verseLabel":"الأنعام: 70","question":"لماذا جمع بين نفي ﴿ولي﴾ و﴿شفيع﴾؟","answer":"نُفيا معًا لإبطال ما توهمه المشركون من النصرة: فالولي ناصر مقيد بالقرب أو رابطة، وهو أخص، والشفيع ناصر مطلق قريبًا كان أو أجنبيًا، وهو أعم؛ فنفيهما يقطع تعلقهم بالأولياء والشفعاء من دون الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص116، تحت «غرض تقديم ﴿ولي﴾ على ﴿شفيع﴾».","url":""}]},{"id":"s6-510","number":510,"surah":6,"verses":[70],"references":[{"surah":6,"verses":[70]}],"verseLabel":"الأنعام: 70","question":"ما الغرض من تأكيد الفداء في قوله تعالى: ﴿وإن تعدل كل عدل لا يؤخذ منها﴾؟","answer":"بالغ في نفي النجاة بالفدية، فحتى لو بذلت النفس كل ما يمكن أن يعادلها لم يقبل منها؛ وبذلك انقطعت وسيلة النجاة المتوهمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص117، تحت عنوان «الغرض من تأكيد الفداء»","url":""}]},{"id":"s6-1200","number":1200,"surah":6,"verses":[70],"references":[{"surah":6,"verses":[70]}],"verseLabel":"الأنعام: 70","question":"ما دلالة تنكير ﴿عدل﴾ في قوله تعالى: ﴿وإن تعدل كل عدل﴾؟","answer":"أفاد العموم والتعظيم، أي أيَّ فداء مهما عظم وكثر؛ فلا يخرج من النفي بدل يمكن أن يتوهم قبوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص118، تحت عنوان «إيثار التعبير بالنكرة في لفظ ﴿عدل﴾»","url":""}]},{"id":"s6-1201","number":1201,"surah":6,"verses":[70],"references":[{"surah":6,"verses":[70]}],"verseLabel":"الأنعام: 70","question":"ما الفرق بين العدل والفداء؟","answer":"العدل هو البدل المكافئ للشيء، والفداء ما يبذل لتخليص النفس؛ فسمي الفداء عدلًا بالنظر إلى كونه معادلًا للمفدي.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص127، تحت عنوان «الفروق المعجمية: (العدل) و(الفداء)»","url":""}]},{"id":"s6-511","number":511,"surah":6,"verses":[70],"references":[{"surah":6,"verses":[70]}],"verseLabel":"الأنعام: 70","question":"لماذا أسند الأخذ إلى المجهول: ﴿لا يؤخذ منها﴾؟","answer":"بُني ﴿لا يؤخذ﴾ للمجهول لأن المقصود نفي قبول الفداء نفسه والاهتمام بعدم أخذه، لا بيان من يأخذه؛ فلا فداء يُقبل منها بحال.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص119، تحت «دلالة المبني للمجهول في قوله: ﴿لا يؤخذ منها﴾».","url":""}]},{"id":"s6-512","number":512,"surah":6,"verses":[70],"references":[{"surah":6,"verses":[70]}],"verseLabel":"الأنعام: 70","question":"لماذا كرر: ﴿أولئك الذين أبسلوا بما كسبوا﴾ بعد التحذير من أن تبسل نفس؟","answer":"الأول تحذير عام من الإبسال، ثم جاء ﴿أولئك﴾ لتعيين الذين وقع عليهم الوعيد وتقرير سببه: هم الذين سلموا للهلاك بكسبهم، لا بظلم من غيرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص119، تحت «الغرض من الاستئناف في ﴿أولئك الذين﴾».","url":""}]},{"id":"s6-513","number":513,"surah":6,"verses":[70],"references":[{"surah":6,"verses":[70]}],"verseLabel":"الأنعام: 70","question":"لماذا اختير لهم ﴿شراب من حميم﴾ في مقابلة ما كسبوا؟","answer":"خُص شراب الحميم لأنهم يعطشون فلا يجدون إلا ماء بالغ الحرارة يزيدهم حرارةً على حرارة العطش، فصار الشراب نفسه وجهًا من العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص122، تحت «العلة بتخصيص ذكر الشراب».","url":""}]},{"id":"s6-514","number":514,"surah":6,"verses":[70],"references":[{"surah":6,"verses":[70]}],"verseLabel":"الأنعام: 70","question":"لماذا وصف العذاب بـ﴿أليم﴾، مع أن الألم مفهوم من العذاب؟","answer":"وصف العذاب بالأليم لتوكيد بلوغ الألم وتمييزه بأنه عذاب يباشر إحساسهم، لا مجرد حرمان أو تهديد؛ فاجتمع شراب الحميم وسائر الألم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص123، تحت «إيثار التعبير عن المفعول بالصفة المشبهة».","url":""}]},{"id":"s6-515","number":515,"surah":6,"verses":[70],"references":[{"surah":6,"verses":[70]}],"verseLabel":"الأنعام: 70","question":"لماذا فُرّق بين سبب الإبسال وسبب العذاب الأليم؟","answer":"نسب الإبسال إلى ما كسبوا ليشمل أعمالهم، ثم نسب العذاب إلى كفرهم لأنه أصل تلك الأعمال وأشد أسباب العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص124، تحت عنوان «علة التفريق بين سبب الإبسال، وسبب العذاب الأليم»","url":""}]},{"id":"s6-1202","number":1202,"surah":6,"verses":[70],"references":[{"surah":6,"verses":[70]}],"verseLabel":"الأنعام: 70","question":"ما سر جعل العذاب مسببًا على الكفر في قوله تعالى: ﴿بما كانوا يكفرون﴾؟","answer":"صرح بالكفر لأنه الجذر الذي أفسد أعمالهم وأبقاهم على الإعراض، فناسب أن يذكر علة للعذاب الأليم خاصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص124، تحت عنوان «السر في جعل العذاب مسببًا على الكفر»","url":""}]},{"id":"s6-516","number":516,"surah":6,"verses":[71],"references":[{"surah":6,"verses":[71]}],"verseLabel":"الأنعام: 71","question":"ما الغرض المجازي من الاستفهام في قوله تعالى: ﴿قل أندعوا من دون الله﴾؟","answer":"خرج الاستفهام إلى الإنكار؛ فيرفض عبادة ما لا يملك نفعًا ولا ضرًا، ويلزم المخاطبين بالإقرار بفسادها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص133، تحت عنوان «الغرض المجازي من الاستفهام في ﴿قل أندعوا﴾»","url":""}]},{"id":"s6-1203","number":1203,"surah":6,"verses":[71],"references":[{"surah":6,"verses":[71]}],"verseLabel":"الأنعام: 71","question":"ما بلاغة التعبير بالدعاء عن العبادة في قوله تعالى: ﴿أندعوا من دون الله﴾؟","answer":"أطلق الدعاء وأريدت العبادة لأنه أبرز مظاهر الافتقار والتوجه إلى المعبود؛ فدل الجزء الظاهر على حقيقة العبادة كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص133، تحت عنوان «بلاغة التعبير بالدعاء عن العبادة»","url":""}]},{"id":"s6-517","number":517,"surah":6,"verses":[71],"references":[{"surah":6,"verses":[71]}],"verseLabel":"الأنعام: 71","question":"ما سرّ تقديم نفي النفع على نفي الضر؟","answer":"قُدّم نفي النفع لأنه أجلب لترك عبادتهم؛ إذ الداعي إنما يدعو معبوده طلبًا للنفع لا للضر، ولأن سياق السورة في تعداد النعم، فبدأ بما يلائم السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص135، تحت «علة تقديم ذكر النفع على الضر».","url":""}]},{"id":"s6-518","number":518,"surah":6,"verses":[71],"references":[{"surah":6,"verses":[71]}],"verseLabel":"الأنعام: 71","question":"ما بلاغة الاستعارة في قوله تعالى: ﴿ونرد على أعقابنا﴾؟","answer":"صوّر ترك الإيمان برجوع السائر إلى الخلف بعد تقدمه؛ فجعل الارتداد انتكاسًا محسوسًا بعد سلوك طريق الهدى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص137، تحت عنوان «بلاغة الاستعارة في قوله: ﴿ونرد على أعقابنا﴾»","url":""}]},{"id":"s6-1204","number":1204,"surah":6,"verses":[71],"references":[{"surah":6,"verses":[71]}],"verseLabel":"الأنعام: 71","question":"لماذا أوثر التعبير عن الردة بقوله تعالى: ﴿ونرد على أعقابنا﴾؟","answer":"لأن الرجوع على الأعقاب يوحي بالانتكاس والخسران بعد التقدم، فيقبح الردة ولا يجعلها انتقالًا متكافئًا بين طريقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص138، تحت عنوان «إيثار التعبير عن الردة بـ﴿ونرد على أعقابنا﴾»","url":""}]},{"id":"s6-519","number":519,"surah":6,"verses":[71],"references":[{"surah":6,"verses":[71]}],"verseLabel":"الأنعام: 71","question":"ما الفرق بين الردة والرجوع؟","answer":"الرجوع أعم في العودة إلى ما كان عليه الإنسان، أما الردة فتغلب في الرجوع عن الإسلام إلى الكفر؛ لذلك تحمل في السياق معنى الانتكاس بعد الهدى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص146، تحت عنوان «(الردة) و(الرجوع)»","url":""}]},{"id":"s6-520","number":520,"surah":6,"verses":[71],"references":[{"surah":6,"verses":[71]}],"verseLabel":"الأنعام: 71","question":"ما دلالة قوله تعالى: ﴿بعد إذ هدانا الله﴾ في إنكار الرجوع إلى الشرك؟","answer":"ذكر الهداية يؤكد نفي الارتداد وإنكاره؛ أي كيف نعود إلى الشرك بعد أن أنقذنا الله منه ومنّ علينا بالإيمان؟ فهو تشنيع للرجوع إلى الكفر بعد نعمة الهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص139، تحت «تأكيد إنكار الارتداد بذكر الهداية»","url":""}]},{"id":"s6-521","number":521,"surah":6,"verses":[71],"references":[{"surah":6,"verses":[71]}],"verseLabel":"الأنعام: 71","question":"لماذا أظهر اسم الله في ﴿هدانا الله﴾؟","answer":"أظهر اسم الجلالة ليعظم نعمة الهدى ويبين مصدرها وحده؛ فالارتداد ليس ترك رأي بشري، بل رد لهداية تفضل الله بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص139، تحت «دلالة إسناد الهداية لله تعالى».","url":""}]},{"id":"s6-522","number":522,"surah":6,"verses":[71],"references":[{"surah":6,"verses":[71]}],"verseLabel":"الأنعام: 71","question":"لماذا شُبّه المرتد بـ﴿الذي استهوته الشياطين في الأرض حيران﴾؟","answer":"شُبّه المرتد برجل أضلته الشياطين في فلاة فبقي حيران لا يهتدي، وترك رفاقه على الطريق المستقيم يدعونه إلى الرجوع فلا يستجيب؛ فالصورة تجسّد ضياع المرتد مع قيام داعي الهدى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص139، تحت «بلاغة التشبيه التمثيلي».","url":""}]},{"id":"s6-523","number":523,"surah":6,"verses":[71],"references":[{"surah":6,"verses":[71]}],"verseLabel":"الأنعام: 71","question":"ما وجه تأنيث الفعل في قوله تعالى: ﴿استهوته الشياطين﴾ مع جمع ﴿الشياطين﴾؟","answer":"جاء التأنيث مراعاةً لمعنى جماعة الشياطين؛ فجمع التكسير يجوز أن يراعى فيه معنى الجماعة، فيؤنث فعله. ووردت قراءة بالتذكير مراعاةً للفظ الجمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص140، تحت «توجيه القراءات القرآنية في استهوته»","url":""}]},{"id":"s6-524","number":524,"surah":6,"verses":[71],"references":[{"surah":6,"verses":[71]}],"verseLabel":"الأنعام: 71","question":"ما دلالة صيغة الاستفعال في قوله تعالى: ﴿استهوته الشياطين﴾؟","answer":"تصور الصيغة طلب الشياطين سقوطه وحرصها عليه حتى أوقعته في الضلال، فزادت معنى السعي والاستدراج على مجرد الإضلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص139–140، تحت عنوان «دلالة صيغة الاستفعال في الفعل ﴿استهوته﴾»","url":""}]},{"id":"s6-525","number":525,"surah":6,"verses":[71],"references":[{"surah":6,"verses":[71]}],"verseLabel":"الأنعام: 71","question":"لماذا قُيّد الحيران بقوله: ﴿في الأرض﴾؟","answer":"قُيّد الحيران بقوله ﴿في الأرض﴾ لتكتمل صورة التائه الضال عن الجادة في فلاة، لا يهتدي إلى مخرج ولا يعرف كيف يسلك وأين يذهب.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص129، 131، تحت «شرح المفردات»، مادة «﴿حيران﴾».","url":""}]},{"id":"s6-526","number":526,"surah":6,"verses":[71],"references":[{"surah":6,"verses":[71]}],"verseLabel":"الأنعام: 71","question":"ما بلاغة التشبيه التمثيلي في تصوير من استهوته الشياطين في الأرض؟","answer":"شُبه من ترك الهدى بعد معرفته بحائر أضلته الشياطين في فلاة، وأصحابه على الطريق يدعونه؛ فصورت الهيئة اضطرابه وبعده عن النجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص139، تحت عنوان «بلاغة التشبيه التمثيلي»","url":""}]},{"id":"s6-1205","number":1205,"surah":6,"verses":[71],"references":[{"surah":6,"verses":[71]}],"verseLabel":"الأنعام: 71","question":"ما دلالة مجيء الصفة جملة فعلية مضارعية في قوله تعالى: ﴿له أصحاب يدعونه إلى الهدى﴾؟","answer":"المضارع يصور دعاء أصحابه متجددًا مستمرًا، فيبرز شدة حيرته إذ يبقى معرضًا مع وضوح النداء وتكرره.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص140، تحت عنوان «دلالة مجيء الصفة جملة فعلية مضارعية ﴿يدعونه﴾»","url":""}]},{"id":"s6-527","number":527,"surah":6,"verses":[71],"references":[{"surah":6,"verses":[71]}],"verseLabel":"الأنعام: 71","question":"ما وجه الإيجاز في قوله تعالى: ﴿له أصحاب يدعونه إلى الهدى ائتنا﴾؟","answer":"حُذف فعل القول قبل ﴿ائتنا﴾ لدلالة ﴿يدعونه﴾ عليه؛ والتقدير: يقولون له ائتنا. فالأصحاب على الطريق المستقيم يدعونه أن يترك طريق الضلال ويعود إليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص141، تحت «بلاغة الإيجاز بالحذف»","url":""}]},{"id":"s6-528","number":528,"surah":6,"verses":[71],"references":[{"surah":6,"verses":[71]}],"verseLabel":"الأنعام: 71","question":"ما سرّ التعبير في قوله تعالى: ﴿إن هدى الله هو الهدى﴾ بضمير الفصل وتعريف الطرفين؟","answer":"ضمير الفصل وتعريف الطرفين يفيدان القصر: هدى الله وحده هو الهدى الكامل الحقيقي، وما عداه استهواء وحيرة وإن سماه أصحابه هداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص142، تحت «اجتماع المؤكدات والقصر في قوله: ﴿إن هدى الله هو الهدى﴾».","url":""}]},{"id":"s6-529","number":529,"surah":6,"verses":[71],"references":[{"surah":6,"verses":[71]}],"verseLabel":"الأنعام: 71","question":"ما سرّ التعبير في قوله تعالى: ﴿وأمرنا لنسلم لرب العالمين﴾ باللام؟","answer":"اللام في ﴿لنسلم﴾ للتعليل وتعيين الغاية التي وقع الأمر لأجلها؛ أي أُمرنا بما أُمرنا به لننقاد ونستسلم بإخلاص لرب العالمين، بخلاف الباء التي تدل على مجرد وقوع الأمر بالإسلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص144، تحت «إيثار التعبير بـ(لنفعل) دون (بأن نفعل)».","url":""}]},{"id":"s6-530","number":530,"surah":6,"verses":[71],"references":[{"surah":6,"verses":[71]}],"verseLabel":"الأنعام: 71","question":"ما دلالة اللام في قوله تعالى: ﴿لنسلم لرب العالمين﴾؟","answer":"تفيد التخصيص، أي نخلص الاستسلام لرب العالمين وحده، فلا نشرك معه من لا يملك نفعًا ولا ضرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص144، تحت عنوان «دلالة اللام على التخصيص في قوله: ﴿لرب العالمين﴾»","url":""}]},{"id":"s6-1206","number":1206,"surah":6,"verses":[71],"references":[{"surah":6,"verses":[71]}],"verseLabel":"الأنعام: 71","question":"ما بلاغة التعبير بالاسم الظاهر في قوله تعالى: ﴿لنسلم لرب العالمين﴾؟","answer":"أظهر وصف الربوبية موضع الضمير ليعلل الاستسلام؛ فمن يربي العالمين ويدبرهم هو وحده المستحق له.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص144، تحت عنوان «التعبير بالاسم الظاهر في ﴿لنسلم لرب العالمين﴾»","url":""}]},{"id":"s6-531","number":531,"surah":6,"verses":[72],"references":[{"surah":6,"verses":[72]}],"verseLabel":"الأنعام: 72","question":"لماذا خُصت الصلاة بالذكر بعد الأمر بالاستسلام لله؟","answer":"لأنها أعظم مظهر عملي للاستسلام وعمود العبادة، فخصت بالذكر تنويهًا بمكانتها بعد الأمر الجامع.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص150، تحت عنوان «العلة بتخصيص ذكر الصلاة»","url":""}]},{"id":"s6-532","number":532,"surah":6,"verses":[72],"references":[{"surah":6,"verses":[72]}],"verseLabel":"الأنعام: 72","question":"ما سرّ التعبير في قوله تعالى: ﴿أقيموا الصلاة﴾، دون أن يقال: صلوا؟","answer":"إقامة الصلاة أداؤها مستقيمة تامة بأوقاتها وأركانها وخشوعها والمداومة عليها؛ فهي أوسع من مجرد وقوع فعل الصلاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص151، تحت «السر بالتعبير عن الأمر بالصلاة بـ﴿أقيموا﴾».","url":""}]},{"id":"s6-533","number":533,"surah":6,"verses":[72],"references":[{"surah":6,"verses":[72]}],"verseLabel":"الأنعام: 72","question":"ما أثر عطف قوله تعالى: ﴿وأن أقيموا الصلاة واتقوه﴾ على الأمر بالاستسلام؟","answer":"فصل العطف مقتضيات الاستسلام: عبادة ظاهرة في إقامة الصلاة، وحال جامعة في التقوى؛ فبيّن العمل الذي يصدق الدعوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص149، تحت عنوان «بلاغة العطف بين الجمل وأثره في المعنى»","url":""}]},{"id":"s6-534","number":534,"surah":6,"verses":[72],"references":[{"surah":6,"verses":[72]}],"verseLabel":"الأنعام: 72","question":"ما سرّ الانتقال من ﴿وأمرنا لنسلم﴾ إلى خطاب ﴿وأن أقيموا الصلاة واتقوه﴾؟","answer":"انتقل الكلام من صيغة المتكلم إلى خطاب المواجهة تشريفًا بالقرب؛ فالاستسلام والإيمان قربٌ من الله، فناسبه خطاب الحاضر بالأمر بالصلاة والتقوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص150، تحت «بلاغة الالتفات في سياق الآيات الكريمة»","url":""}]},{"id":"s6-535","number":535,"surah":6,"verses":[72],"references":[{"surah":6,"verses":[72]}],"verseLabel":"الأنعام: 72","question":"ما دلالة الواو في قوله تعالى: ﴿وهو الذي إليه تحشرون﴾؟","answer":"عطفت تقرير الحشر على أوامر الاستسلام والصلاة والتقوى، فربطت التكليف بالمآل الذي يقع فيه الحساب والجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص151، تحت عنوان «دلالة الواو في قوله تعالى: ﴿وهو الذي إليه تحشرون﴾»","url":""}]},{"id":"s6-1207","number":1207,"surah":6,"verses":[72],"references":[{"surah":6,"verses":[72]}],"verseLabel":"الأنعام: 72","question":"لماذا جاء الحديث عن الحشر بعد جملة من الأوامر؟","answer":"ليذكر بأن امتثال الأوامر مرتبط بالرجوع إلى الله والجزاء عليها؛ فالحشر باعث على الطاعة وزاجر عن المخالفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص152، تحت عنوان «الحديث عن الحشر بعد جملة من الأوامر»","url":""}]},{"id":"s6-536","number":536,"surah":6,"verses":[72],"references":[{"surah":6,"verses":[72]}],"verseLabel":"الأنعام: 72","question":"ما سرّ تقديم ﴿إليه﴾ في ﴿إليه تحشرون﴾؟","answer":"قُدم ﴿إليه﴾ لقصر الحشر على الله وتأكيد الرجوع إلى حكمه وحده؛ فلا تنفع عنده الأرباب التي دُعيت من دونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص152، تحت «فائدة تقديم الجار والمجرور ﴿إليه﴾».","url":""}]},{"id":"s6-537","number":537,"surah":6,"verses":[72],"references":[{"surah":6,"verses":[72]}],"verseLabel":"الأنعام: 72","question":"لماذا بُني ﴿تحشرون﴾ للمجهول؟","answer":"بُني ﴿تحشرون﴾ للمفعول للاهتمام بالحشر نفسه وتعظيم شأنه، ولأن فاعله معلوم من سبق ذكر الله في قوله ﴿وهو الذي إليه﴾، فاستُغني عن تسميته.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص153، تحت «الغرض من بناء الفعل ﴿تحشرون﴾ لما لم يسم فاعله».","url":""}]},{"id":"s6-538","number":538,"surah":6,"verses":[73],"references":[{"surah":6,"verses":[73]}],"verseLabel":"الأنعام: 73","question":"ما بلاغة الباء في قوله تعالى: ﴿خلق السماوات والأرض بالحق﴾؟","answer":"تفيد الملابسة، أي خلقهما ملتبسين بالحكمة والغاية الثابتة، لا عبثًا ولا باطلًا؛ ومن هذا الحق البعث والجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص157، تحت عنوان «بلاغة التعبير بالباء، في ﴿بالحق﴾»","url":""}]},{"id":"s6-1208","number":1208,"surah":6,"verses":[73],"references":[{"surah":6,"verses":[73]}],"verseLabel":"الأنعام: 73","question":"ما أثر استئناف قوله تعالى: ﴿ويوم يقول كن فيكون﴾ بالواو؟","answer":"وصل مشهد الخلق الأول بمشهد الإيجاد يوم القيامة، فدل على أن القدرة التي أنشأت السماوات والأرض تنفذ أمر البعث كذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص158، تحت عنوان «الاستئناف بالواو في قوله تعالى: ﴿ويوم﴾»","url":""}]},{"id":"s6-539","number":539,"surah":6,"verses":[73],"references":[{"surah":6,"verses":[73]}],"verseLabel":"الأنعام: 73","question":"لماذا انتقل من خلق السماوات والأرض إلى ﴿ويوم يقول كن فيكون﴾؟","answer":"انتقل من الخلق الأول المشاهد إلى يوم البعث ليدل بالأول على الثاني؛ فمن خلق السماوات والأرض بالحق ينشئ الخلق يوم القيامة بكلمة نافذة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص158، تحت «الاستئناف بالواو في قوله تعالى: ﴿ويوم﴾».","url":""}]},{"id":"s6-540","number":540,"surah":6,"verses":[73],"references":[{"surah":6,"verses":[73]}],"verseLabel":"الأنعام: 73","question":"ما متعلق ﴿يوم﴾ في قوله: ﴿ويوم يقول كن فيكون﴾؟","answer":"﴿يوم يقول﴾ ظرف متعلق بمحذوف وقع خبرًا مقدمًا، و﴿قوله الحق﴾ مبتدأ مؤخر؛ والتقدير: قوله الحق يوم يقول للشيء كن فيكون، فخُص ذلك اليوم لظهور نفاذ قوله فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص158–159، تحت «تقديم الظرف على المبتدأ».","url":""}]},{"id":"s6-541","number":541,"surah":6,"verses":[73],"references":[{"surah":6,"verses":[73]}],"verseLabel":"الأنعام: 73","question":"ما بلاغة الخطاب بفعل الأمر ﴿كن﴾ في الخلق والإيجاد؟","answer":"مثل نفاذ الإرادة الإلهية بصورة أمر لا يتخلف عنه المأمور، فدل على كمال القدرة من غير معالجة أو آلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص159، تحت عنوان «بلاغة الخطاب بفعل الأمر ﴿كن﴾ في الخلق والإيجاد»","url":""}]},{"id":"s6-1209","number":1209,"surah":6,"verses":[73],"references":[{"surah":6,"verses":[73]}],"verseLabel":"الأنعام: 73","question":"ما الغرض من ذكر جملة ﴿كن فيكون﴾؟","answer":"تقرر سرعة نفاذ مشيئة الله وسهولة الإيجاد عليه، وتحتج بالقدرة المطلقة على إمكان البعث بعد الموت.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص160، تحت عنوان «الغرض من ذكر جملة ﴿كن فيكون﴾»","url":""}]},{"id":"s6-542","number":542,"surah":6,"verses":[73],"references":[{"surah":6,"verses":[73]}],"verseLabel":"الأنعام: 73","question":"لماذا جاء ﴿فيكون﴾ بالمضارع بعد الأمر ﴿كن﴾؟","answer":"جاء ﴿فيكون﴾ مرتبًا بالفاء على ﴿كن﴾ ليدل على أن التكوين يعقب الأمر التكويني من غير مهلة؛ فمتى قال للشيء كن وُجد، وفي السياق استحضار سرعة البعث والحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص160، تحت «دلالة الفاء في قوله: ﴿كن فيكون﴾».","url":""}]},{"id":"s6-543","number":543,"surah":6,"verses":[73],"references":[{"surah":6,"verses":[73]}],"verseLabel":"الأنعام: 73","question":"ما دلالة صيغة القصر بتعريف الطرفين في قوله تعالى: ﴿قوله الحق﴾؟","answer":"تعريف المسند إليه والمسند يفيد أن قوله هو الحق الكامل الثابت، وينفي عنه الخلف والباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص161، تحت عنوان «دلالة صيغة القصر بتعريف الطرفين»","url":""}]},{"id":"s6-1210","number":1210,"surah":6,"verses":[73],"references":[{"surah":6,"verses":[73]}],"verseLabel":"الأنعام: 73","question":"ما دلالة ﴿أل﴾ في لفظ ﴿الحق﴾ من قوله تعالى: ﴿قوله الحق﴾؟","answer":"تحتمل العهد الذهني للحق المعروف الكامل، أو الدلالة الكنائية على استغراق كماله؛ وفي الوجهين تعظم صدق قوله ونفاذه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص161، تحت عنوان «دلالة (أل) على العهد الذهني أو الكنائي في ﴿الحق﴾»","url":""}]},{"id":"s6-544","number":544,"surah":6,"verses":[73],"references":[{"surah":6,"verses":[73]}],"verseLabel":"الأنعام: 73","question":"ما سرّ التعبير في قوله تعالى: ﴿وله الملك يوم ينفخ في الصور﴾، أليس الملك له في كل يوم؟","answer":"الملك لله في كل وقت، لكن خُص يوم النفخ لأن ملكه يظهر يومئذ بلا دعوى ولا منازع، وتسقط أملاك الخلق وسلطاتهم التي توهموها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص162، تحت «السر بتخصيص الملك به يوم القيامة».","url":""}]},{"id":"s6-545","number":545,"surah":6,"verses":[73],"references":[{"surah":6,"verses":[73]}],"verseLabel":"الأنعام: 73","question":"لماذا بُني ﴿ينفخ﴾ للمجهول؟","answer":"بُني ﴿ينفخ﴾ للمجهول لتوجيه العناية إلى النفخ وهوله وآثاره، ولأن النافخ معلوم من السنة وهو إسرافيل المأمور من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص163، تحت «إيثار التعبير بالفعل المبني للمفعول ﴿ينفخ﴾».","url":""}]},{"id":"s6-546","number":546,"surah":6,"verses":[73],"references":[{"surah":6,"verses":[73]}],"verseLabel":"الأنعام: 73","question":"ما المراد بـ﴿الصور﴾، وما دلالة تعريفه في قوله تعالى: ﴿يوم ينفخ في الصور﴾؟","answer":"الصور هو القرن الذي ينفخ فيه إسرافيل بأمر الله. وتعريفه للعهد الذهني؛ إذ صار يوم النفخ فيه حاضرًا في الأذهان بما ورد من ذكره في الآيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص163، تحت «العهد الحضوري الذهني في لفظ الصور»","url":""}]},{"id":"s6-547","number":547,"surah":6,"verses":[73],"references":[{"surah":6,"verses":[73]}],"verseLabel":"الأنعام: 73","question":"لماذا عُبر عن علم الله المطلق بقوله تعالى: ﴿عالم الغيب والشهادة﴾؟","answer":"جمع ما غاب عن الخلق وما شهدوه، فاستوعب طرفا المعلومات وأثبت إحاطة علم الله بكل موجود وحال.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص164، تحت عنوان «التعبير عن علمه تعالى المطلق بكونه عالم الغيب والشهادة»","url":""}]},{"id":"s6-1211","number":1211,"surah":6,"verses":[73],"references":[{"surah":6,"verses":[73]}],"verseLabel":"الأنعام: 73","question":"ما دلالة الاستغراق في لفظي ﴿الغيب﴾ و﴿الشهادة﴾؟","answer":"استغرق التعريف كل غائب وكل مشهود، فدل مجموع اللفظين على أنه لا يخرج عن علم الله معلوم دق أو عظم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص165، تحت عنوان «دلالة الاستغراق في لفظي ﴿الغيب﴾ و﴿الشهادة﴾»","url":""}]},{"id":"s6-548","number":548,"surah":6,"verses":[73],"references":[{"surah":6,"verses":[73]}],"verseLabel":"الأنعام: 73","question":"ما سر ذكر الغيب في قوله تعالى: ﴿عالم الغيب والشهادة﴾ مع أنه لا يغيب عن الله شيء؟","answer":"سمي غيبًا بالنظر إلى المخلوقين الذين يخفى عنهم، أما الله فلا يغيب عن علمه شيء؛ فالإضافة تراعي حال المخاطبين وتثبت كمال علمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص164، تحت عنوان «السر في ذكر الغيب، ولا غيب يغيب على الله تعالى»","url":""}]},{"id":"s6-549","number":549,"surah":6,"verses":[73],"references":[{"surah":6,"verses":[73]}],"verseLabel":"الأنعام: 73","question":"لماذا خُتمت الآية بـ﴿وهو الحكيم الخبير﴾؟","answer":"هو ﴿الحكيم﴾ في خلقه وأمره وبعثه، يضع كل شيء موضعه، و﴿الخبير﴾ بدقائق الغيب والشهادة وعواقب الأمور؛ فالخاتمة تعلل ما سبق من الخلق والملك والعلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص166، تحت «تخصيص ختام الآية بصفتي الحكيم والخبير دون سواهما».","url":""}]},{"id":"s6-550","number":550,"surah":6,"verses":[74],"references":[{"surah":6,"verses":[74]}],"verseLabel":"الأنعام: 74","question":"لماذا ذُكرت قصة إبراهيم هنا دون غيرها؟","answer":"لأنها تقيم حجة التوحيد بلسان أبي الأنبياء الذي ينتسب إليه مشركو العرب، وتصل إنكار الشرك في السياق بموقفه من الأصنام.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص170–171، تحت عنوان «وجه ذكر قصة إبراهيم دون غيره»","url":""}]},{"id":"s6-551","number":551,"surah":6,"verses":[74],"references":[{"surah":6,"verses":[74]}],"verseLabel":"الأنعام: 74","question":"لماذا ذُكر اسم الأب ﴿آزر﴾ هنا؟","answer":"ذُكر اسم ﴿آزر﴾ هنا لأن سورة الأنعام هي أول موضع في ترتيب المصحف يعرض دعوة إبراهيم لأبيه، فناسب تعريفه باسمه في أول ورود، ثم حُمِل حذف الاسم في المواضع الأخرى على هذا التعريف السابق.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص174، تحت «سر انفراد موضع الأنعام بذكر ﴿آزر﴾ دون بقية المواضع».","url":""}]},{"id":"s6-552","number":552,"surah":6,"verses":[74],"references":[{"surah":6,"verses":[74]}],"verseLabel":"الأنعام: 74","question":"ما دلالة الاستفهام في قوله تعالى: ﴿أتتخذ أصنامًا آلهة﴾؟","answer":"هو للإنكار والتوبيخ؛ إذ يجعل المصنوع العاجز معبودًا، ويلزم المخاطب بمواجهة التناقض الظاهر في فعله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص175، تحت عنوان «دلالة الاستفهام في أتتخذ أصنامًا آلهة»","url":""}]},{"id":"s6-553","number":553,"surah":6,"verses":[74],"references":[{"surah":6,"verses":[74]}],"verseLabel":"الأنعام: 74","question":"ما سرّ البدء بإبطال عبادة الأصنام في قوله تعالى: ﴿أتتخذ أصنامًا آلهة﴾ قبل محاجة قومه في الكواكب؟","answer":"بدأ بالأصنام لأنها أوضح بطلانًا، ثم انتقل إلى الكواكب التي جعلوا الأصنام صورًا لها ووسائط إليها؛ فترقى في الحجة من الأجلى إلى الأخفى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص179، تحت «سر تقديم إبطال ألوهية الأصنام على ربوبية الكواكب»","url":""}]},{"id":"s6-554","number":554,"surah":6,"verses":[74],"references":[{"surah":6,"verses":[74]}],"verseLabel":"الأنعام: 74","question":"ما دلالة صيغة الافتعال في قوله تعالى: ﴿أتتخذ أصنامًا آلهة﴾؟","answer":"صيغة ﴿تتخذ﴾ تدل على التكلف والمبالغة في تحصيل الفعل؛ فكون الصنم مصنوعًا ينافي الألوهية، واتخاذه إلهًا عمل يتكلفه عابده ويصطنعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص176، تحت «سر التعبير بصيغة الافتعال الاتخاذ»","url":""}]},{"id":"s6-555","number":555,"surah":6,"verses":[74],"references":[{"surah":6,"verses":[74]}],"verseLabel":"الأنعام: 74","question":"لماذا بدأ إبراهيم بدعوة أبيه قبل دعوة قومه؟","answer":"بدأ بالأقرب الذي له حق الصلة والنصيحة، ثم انتقل منه إلى قومه؛ فجمع ترتيب الدعوة بحسب القرب مع عموم الإنذار.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص179، تحت عنوان «سر بدء إبراهيم بدعوة أبيه قبل دعوة قومه»","url":""}]},{"id":"s6-1212","number":1212,"surah":6,"verses":[74],"references":[{"surah":6,"verses":[74]}],"verseLabel":"الأنعام: 74","question":"ما دلالة عطف ﴿قومك﴾ على ضمير الخطاب في قوله تعالى: ﴿إني أراك وقومك في ضلال مبين﴾؟","answer":"أدخل قومه معه في الحكم نفسه، فانتقل من نصيحة الأب المخاطب إلى بيان ضلال الجماعة التي شاركته عبادة الأصنام.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص181، تحت عنوان «دلالة عطف القوم في ﴿وقومك﴾ على ضمير الخطاب»","url":""}]},{"id":"s6-556","number":556,"surah":6,"verses":[74],"references":[{"surah":6,"verses":[74]}],"verseLabel":"الأنعام: 74","question":"ما سرّ التعبير في قوله تعالى: ﴿في ضلال﴾، فجعل الضلال كأنه مكان يحيط بهم؟","answer":"﴿في﴾ تصور الضلال كحيز أحاط بهم واستقروا داخله، فلا يرون خارجه طريق الحق؛ وهي أبلغ من مجرد وصفهم بأنهم ضالون.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص181، تحت «نوع الظرفية في قوله ﴿في ضلال مبين﴾».","url":""}]},{"id":"s6-557","number":557,"surah":6,"verses":[74],"references":[{"surah":6,"verses":[74]}],"verseLabel":"الأنعام: 74","question":"ما فائدة وصف الضلال بالمبين في قوله تعالى: ﴿في ضلال مبين﴾؟","answer":"أظهر أن بطلان عبادة المصنوعات واضح لا خفاء فيه، فزاد الوصف في تقبيح موقفهم وإقامة الحجة عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص182، تحت عنوان «فائدة وصف الضلال بالمبين»","url":""}]},{"id":"s6-1213","number":1213,"surah":6,"verses":[74],"references":[{"surah":6,"verses":[74]}],"verseLabel":"الأنعام: 74","question":"ما نكتة التعبير باسم الفاعل ﴿مبين﴾ في وصف الضلال؟","answer":"اسم الفاعل يثبت للضلال صفة الظهور والاستقرار، فكأنه بيّن في نفسه وكاشف عن فساد معتقد أصحابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص182، تحت عنوان «نكتة التعبير باسم الفاعل ﴿مبين﴾»","url":""}]},{"id":"s6-558","number":558,"surah":6,"verses":[75],"references":[{"surah":6,"verses":[75]}],"verseLabel":"الأنعام: 75","question":"ما سرّ التعبير في قوله تعالى: ﴿وكذلك نري إبراهيم ملكوت السماوات والأرض﴾، لا: ملك السماوات والأرض؟","answer":"الملكوت صيغة تفيد سعة الملك وعظم السلطان ودقائقه، فرؤية إبراهيم لم تقف عند الأجرام بل نفذت إلى نظامها وتدبيرها ودلالتها على المالك الواحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص190، تحت «نكتة التعبير بالملكوت»","url":""}]},{"id":"s6-559","number":559,"surah":6,"verses":[75],"references":[{"surah":6,"verses":[75]}],"verseLabel":"الأنعام: 75","question":"لماذا عبّر بالمضارع ﴿نري﴾ مع أن الرؤية وقعت في الماضي؟","answer":"المضارع ﴿نري﴾ يحكي الرؤية الماضية في صورة حاضرة متجددة، ويستحضر تدرج إبراهيم في النظر كأن القارئ يشهده.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص188–189، تحت «نكتة اختيار التعبير بالمضارع ﴿نري﴾»","url":""}]},{"id":"s6-560","number":560,"surah":6,"verses":[75],"references":[{"surah":6,"verses":[75]}],"verseLabel":"الأنعام: 75","question":"ما سرّ تقديم السماوات على الأرض في قوله تعالى: ﴿ملكوت السماوات والأرض﴾؟","answer":"قُدمت السماوات لما أودع الله فيها من الكواكب والنجوم والشمس والقمر وما تكشفه من عظمة الملكوت؛ أما الأرض فهي بالنسبة إلى ذلك الملكوت العظيم بعضُ ما تحويه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص191، تحت «سر إضافة ملكوت إلى السماوات قبل الأرض»","url":""}]},{"id":"s6-561","number":561,"surah":6,"verses":[75],"references":[{"surah":6,"verses":[75]}],"verseLabel":"الأنعام: 75","question":"ما سرّ التعبير في قوله تعالى: ﴿وليكون من الموقنين﴾، دون أن يقال: ليوقن؟","answer":"﴿من الموقنين﴾ يدل على ثباته في زمرة أهل اليقين ورسوخ الصفة فيه، وهو أبلغ من حصول فعل يقين في لحظة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص193، تحت «سر إيثار التعبير بـ﴿الموقنين﴾ دون (المهتدين)».","url":""}]},{"id":"s6-562","number":562,"surah":6,"verses":[75],"references":[{"surah":6,"verses":[75]}],"verseLabel":"الأنعام: 75","question":"لماذا جيء بواو قبل ﴿ليكون﴾؟","answer":"على أبرز الأوجه عطفت الواو علة مذكورة على علة محذوفة دل عليها السياق؛ أي أريناه الملكوت ليستدل به وليكون من الموقنين، وقيل إن الجملة مستأنفة، فالرؤية ذات غايات متصلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص191، تحت «دلالة الواو بين الاستئناف والعطف».","url":""}]},{"id":"s6-563","number":563,"surah":6,"verses":[76],"references":[{"surah":6,"verses":[76]}],"verseLabel":"الأنعام: 76","question":"ما سرّ التعبير في قوله تعالى: ﴿فلما جن عليه الليل﴾، فعبّر عن إظلام الليل بالجنّ؟","answer":"﴿جن﴾ معناه ستر وغطى، فصوّر الليل غطاءً أطبق على إبراهيم وحجب ضوء النهار؛ ومن مادته الجن لاستتارهم والجَنين لخفائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص198، تحت «سر التعبير بالفعل ﴿جن﴾».","url":""}]},{"id":"s6-564","number":564,"surah":6,"verses":[76],"references":[{"surah":6,"verses":[76]}],"verseLabel":"الأنعام: 76","question":"لماذا عُدّي ﴿جن﴾ بـ﴿على﴾؟","answer":"عُدّي ﴿جن﴾ بـ﴿على﴾ لتصوير وقوع ستر الليل على إبراهيم وتغطيته له، حتى صارت الظلمة كغطاء محيط به؛ فالتعدية تقوي معنى الستر والإطباق.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص198، تحت «دلالة حرف الجر (على) في قوله تعالى: ﴿فلما جن عليه الليل﴾».","url":""}]},{"id":"s6-565","number":565,"surah":6,"verses":[76],"references":[{"surah":6,"verses":[76]}],"verseLabel":"الأنعام: 76","question":"لماذا نُكّر ﴿كوكبًا﴾، ولم يعيّن اسمه؟","answer":"نُكر ﴿كوكبًا﴾ لأن المقصود جنس الكوكب وصفته في البزوغ والأفول، لا تعيين اسمه؛ فالحجة تصح في أي جرم من هذا النوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص199، تحت «نكتة تنكير ﴿كوكبًا﴾».","url":""}]},{"id":"s6-566","number":566,"surah":6,"verses":[76],"references":[{"surah":6,"verses":[76]}],"verseLabel":"الأنعام: 76","question":"ما دلالة تعريف طرفي الجملة في قوله تعالى: ﴿هذا ربي﴾؟","answer":"أفاد تعريف المسند والمسند إليه القصر، فجارى إبراهيم قومه في افتراض استحقاق الكوكب للربوبية تمهيدًا لإبطال قولهم من داخله، ولم يكن ذلك اعتقادًا منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص201، تحت عنوان «براعة القصر بتعريف الجزأين»","url":""}]},{"id":"s6-1214","number":1214,"surah":6,"verses":[76],"references":[{"surah":6,"verses":[76]}],"verseLabel":"الأنعام: 76","question":"هل جملة ﴿هذا ربي﴾ خبر أم استفهام، وما أثر الاحتمالين؟","answer":"تحتمل الخبر على سبيل التنزل مع الخصم، وتحتمل استفهام الإنكار؛ والوجهان يستدرجان القوم إلى النظر في فساد اعتقادهم من غير أن يثبتا شركًا لإبراهيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص201–202، تحت عنوان «جملة هذا ربي بين الخبر والاستفهام»","url":""}]},{"id":"s6-567","number":567,"surah":6,"verses":[76],"references":[{"surah":6,"verses":[76]}],"verseLabel":"الأنعام: 76","question":"ما وظيفة اسم الإشارة في قول إبراهيم عن الكوكب: ﴿هذا ربي﴾؟","answer":"يميّز اسم الإشارة الكوكب المعين من بين الكواكب، لينصبّ عليه الاحتجاج ومجاراة القوم في دعواهم؛ فالإشارة تعيّن ما اتخذوه معبودًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص201، تحت «نكتة تعريف المسند إليه بالإشارة»","url":""}]},{"id":"s6-568","number":568,"surah":6,"verses":[76],"references":[{"surah":6,"verses":[76]}],"verseLabel":"الأنعام: 76","question":"لماذا جعل أفول الكوكب هو الحجة على بطلان ربوبيته؟","answer":"الأفول انتقال وغياب وتغير، ومن كان محكومًا بالحركة والاحتجاب لا يصلح أن يكون ربًا مدبرًا دائمًا؛ فاتخذ الصفة المشاهدة حجة يفهمها قومه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص204، تحت «ترتيب النتائج على (الأفول) دون الطلوع أو الظهور».","url":""}]},{"id":"s6-569","number":569,"surah":6,"verses":[76],"references":[{"surah":6,"verses":[76]}],"verseLabel":"الأنعام: 76","question":"ما سرّ التعبير في قوله تعالى: ﴿لا أحب الآفلين﴾، دون أن يقال: ليس هذا ربي؟","answer":"﴿لا أحب الآفلين﴾ ينقل الحجة من نفي ربوبية جرم واحد إلى قاعدة عامة: المعبود لا يكون غائبًا متغيرًا. وفي نفي المحبة إعلان أن القلب لا يتعلق بما يزول.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص205، تحت «إيثار الكناية بنفي حب الآفلين».","url":""}]},{"id":"s6-570","number":570,"surah":6,"verses":[76],"references":[{"surah":6,"verses":[76]}],"verseLabel":"الأنعام: 76","question":"ما سرّ التعبير بـ﴿الآفلين﴾ بصيغة جمع العقلاء؟","answer":"جارى إبراهيم اعتقاد قومه أن الكواكب عاقلة متصرفة في الكون، فعبّر عنها بصيغة جمع العقلاء؛ ثم أبطل استحقاقها العبادة بما يلحقها من الأفول، وفي ذلك تهكم بدعواهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص206، تحت «دلالة التعبير بالآفلين دون المصدر الأفول»","url":""}]},{"id":"s6-571","number":571,"surah":6,"verses":[77],"references":[{"surah":6,"verses":[77]}],"verseLabel":"الأنعام: 77","question":"لماذا وصف القمر بأنه ﴿بازغًا﴾، ولم يصف الكوكب بمثله؟","answer":"وُصف القمر بالبزوغ لأن طلوعه أوضح ونوره أعظم من الكوكب، فناسب إبراز ظهوره مرحلةً أقوى في الحجة؛ أما رؤية الكوكب فتكفي فيها تسميته من غير وصف.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص210، تحت «دلالة ذكر البزوغ مع القمر».","url":""}]},{"id":"s6-572","number":572,"surah":6,"verses":[77],"references":[{"surah":6,"verses":[77]}],"verseLabel":"الأنعام: 77","question":"ما دلالة تكرار قوله تعالى: ﴿قال هذا ربي﴾ في محاورة إبراهيم قومه؟","answer":"مثّل التكرار انتقال الحجة درجة بعد درجة من الكوكب إلى القمر ثم الشمس، مع مجاراة القوم حتى يظهر بطلان ربوبية كل جرم آفل.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص211، تحت عنوان «دلالة تكرار قوله: ﴿قال هذا ربي﴾ في المحاورة»","url":""}]},{"id":"s6-1215","number":1215,"surah":6,"verses":[77],"references":[{"surah":6,"verses":[77]}],"verseLabel":"الأنعام: 77","question":"ما سر تكرار الفعل ﴿أفل﴾ في محاورة إبراهيم مع قومه؟","answer":"كرر الأفول لأنه العلة المشتركة التي تهدم دعوى الربوبية في الأجرام كلها؛ فما يغيب ويتغير لا يصلح إلهًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص211، تحت عنوان «سر تكرار الفعل ﴿أفل﴾ في محاورة إبراهيم مع قومه»","url":""}]},{"id":"s6-573","number":573,"surah":6,"verses":[77],"references":[{"surah":6,"verses":[77]}],"verseLabel":"الأنعام: 77","question":"لماذا انتقل بعد أفول القمر إلى الدعاء: ﴿لئن لم يهدني ربي﴾؟","answer":"بعد أفول القمر أظهر افتقاره إلى هداية ربه؛ لأن الهداية الحقيقية من الله، وعرّض بأن قومه في ضلال، تمهيدًا للتصريح ببراءته من عبادة الأجرام.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص212، تحت عنوان «بلاغة التعريض في ﴿لئن لم يهدني ربي﴾»","url":""}]},{"id":"s6-574","number":574,"surah":6,"verses":[77],"references":[{"surah":6,"verses":[77]}],"verseLabel":"الأنعام: 77","question":"لماذا أسند إبراهيم الهداية إلى الربوبية في قوله تعالى: ﴿لئن لم يهدني ربي﴾؟","answer":"لأن مقام الهداية والإنعام يلائمه وصف الرب الذي يربي عبده ويوصله إلى الحق، وفيه تعريض بأن هداية قومه لا تكون من أصنامهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص214، تحت عنوان «دلالة إسناد الهداية إلى الربوبية دون الألوهية»","url":""}]},{"id":"s6-1216","number":1216,"surah":6,"verses":[77],"references":[{"surah":6,"verses":[77]}],"verseLabel":"الأنعام: 77","question":"ما فائدة إضافة لفظ ﴿ربي﴾ إلى ضمير المتكلم؟","answer":"أفادت الإضافة اختصاص إبراهيم بولاية ربه وعنايته وهدايته، وأظهرت صلته المباشرة بمن يطلب منه الهدى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص214، تحت عنوان «فائدة الإضافة في لفظ ﴿ربي﴾»","url":""}]},{"id":"s6-575","number":575,"surah":6,"verses":[77],"references":[{"surah":6,"verses":[77]}],"verseLabel":"الأنعام: 77","question":"لماذا أكد الجواب باللام والنون: ﴿لأكونن من القوم الضالين﴾؟","answer":"اللام موطئة للقسم ونون التوكيد الثقيلة تثبت الجواب؛ فبيّن أن انتفاء هداية الله يفضي حتمًا إلى الضلال، لا إلى احتمال متردد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص214، تحت «دلالة اللام والنون في ﴿لأكونن﴾».","url":""}]},{"id":"s6-576","number":576,"surah":6,"verses":[77],"references":[{"surah":6,"verses":[77]}],"verseLabel":"الأنعام: 77","question":"ما سرّ التعبير في قوله تعالى: ﴿من القوم الضالين﴾، دون أن يقال: ضالًا؟","answer":"﴿من القوم الضالين﴾ أبلغ من ﴿ضالًا﴾؛ لأنها تصور الدخول في جماعة استقر فيها الضلال، وتلمح إلى قومه الذين رأى طريقهم وعاقبته.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص215، تحت «سر التعبير بنسق ﴿من القوم الضالين﴾».","url":""}]},{"id":"s6-577","number":577,"surah":6,"verses":[78],"references":[{"surah":6,"verses":[78]}],"verseLabel":"الأنعام: 78","question":"لماذا خُصّت الشمس بقوله: ﴿هذا أكبر﴾؟","answer":"الشمس أكبر الأجرام الثلاثة في الحس وأشدها ضوءًا، فخصها بذلك ليبلغ افتراض قومه أقصى قوته؛ فإذا أفل الأكبر بطل ما دونه من باب أولى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص220، تحت «سر التعبير بقوله: ﴿أكبر﴾ مع الشمس دون غيرها».","url":""}]},{"id":"s6-578","number":578,"surah":6,"verses":[78],"references":[{"surah":6,"verses":[78]}],"verseLabel":"الأنعام: 78","question":"ما سرّ التعبير في قوله تعالى عن الشمس المؤنثة: ﴿هذا ربي﴾ لا ﴿هذه﴾؟","answer":"ذُكر اسم الإشارة على معنى: هذا الجرم أو هذا الطالع ربي، وذُكرت تأويلات أخرى منها إرادة ضوء الشمس لا عينها؛ فالمراعاة للمعنى المقصود لا لتأنيث لفظ الشمس.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص218، تحت «نكتة تذكير اسم الإشارة في قوله تعالى: ﴿هذا ربي﴾».","url":""}]},{"id":"s6-579","number":579,"surah":6,"verses":[78],"references":[{"surah":6,"verses":[78]}],"verseLabel":"الأنعام: 78","question":"ما دلالة التعبير بالفعل الماضي في قوله تعالى عن الشمس: ﴿فلما أفلت﴾؟","answer":"يفيد الماضي تحقق الأفول ووقوعه؛ فلم يعلن إبراهيم البراءة من عبادتها إلا بعد أن غاب جرمها وذهب نورها، فصارت الحجة مشاهدة متحققة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص221، تحت «دلالة التعبير بالفعل الماضي أفلت»","url":""}]},{"id":"s6-580","number":580,"surah":6,"verses":[78],"references":[{"surah":6,"verses":[78]}],"verseLabel":"الأنعام: 78","question":"لماذا نادى قومه عند أفول الشمس: ﴿يا قوم﴾ ولم ينادهم في المرحلتين السابقتين؟","answer":"نادى قومه عند اكتمال التجربة وظهور النتيجة ليعلن الحكم العام أمامهم؛ أما المرحلتان السابقتان فكانتا تمهيدًا متدرجًا للمحاجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص221، تحت «بلاغة النداء في قوله تعالى: ﴿يا قوم﴾».","url":""}]},{"id":"s6-581","number":581,"surah":6,"verses":[78],"references":[{"surah":6,"verses":[78]}],"verseLabel":"الأنعام: 78","question":"ما سرّ التعبير في قوله تعالى: ﴿إني بريء مما تشركون﴾ بالاسم، لا: أتبرأ؟","answer":"الاسم ﴿بريء﴾ يدل على ثبوت البراءة واستقرارها، لا على فعل يتجدد مرة؛ فهو إعلان قاطع لانفصاله عن الشرك وأهله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص222، تحت «دلالة التعبير بالاسمية في ﴿إني بريء﴾».","url":""}]},{"id":"s6-582","number":582,"surah":6,"verses":[78],"references":[{"surah":6,"verses":[78]}],"verseLabel":"الأنعام: 78","question":"ما سرّ التعبير في قوله تعالى: ﴿مما تشركون﴾، ولم يسم الشمس والقمر والكوكب؟","answer":"تحتمل «ما» الموصولية، فتعم الشمس والقمر والكوكب وسائر ما يشركون به، وتحتمل المصدرية، فيكون المعنى: إني بريء من إشراككم؛ فجمع التعبير البراءة من الشرك ومعبوداته.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص223، تحت «دلالة (ما) في قوله تعالى: ﴿مما تشركون﴾».","url":""}]},{"id":"s6-583","number":583,"surah":6,"verses":[79],"references":[{"surah":6,"verses":[79]}],"verseLabel":"الأنعام: 79","question":"لماذا أوثر الفعل ﴿وجهت﴾ في قوله تعالى: ﴿إني وجهت وجهي﴾؟","answer":"يدل التوجيه على قصد جهة واحدة والإقبال عليها، فعبّر عن إخلاص الدين والعبادة لله والإعراض عما سواه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص228، تحت عنوان «دلالة إيثار التعبير بقوله: ﴿وجهت﴾ دون أملت»","url":""}]},{"id":"s6-1217","number":1217,"surah":6,"verses":[79],"references":[{"surah":6,"verses":[79]}],"verseLabel":"الأنعام: 79","question":"ما سر الكناية عن الطاعة بتوجيه الوجه؟","answer":"الوجه أشرف ما يظهر من الإنسان وبه تعرف وجهته، فتوجيهه كناية عن إقبال الذات كلها بالقصد والطاعة على الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص229، تحت عنوان «سر الكناية عن الطاعة بتوجيه الوجه»","url":""}]},{"id":"s6-584","number":584,"surah":6,"verses":[79],"references":[{"surah":6,"verses":[79]}],"verseLabel":"الأنعام: 79","question":"لماذا أوثر لفظ ﴿وجهي﴾ دون قلبي في قوله تعالى: ﴿إني وجهت وجهي﴾؟","answer":"لأن الوجه مظهر الإقبال والجهة ويعبّر عن الذات الظاهرة والباطنة معًا، فدل على إخلاص الكيان كله لله، لا مجرد انفعال القلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص229، تحت عنوان «دلالة إيثار ﴿وجهي﴾ دون (قلبي)»","url":""}]},{"id":"s6-585","number":585,"surah":6,"verses":[79],"references":[{"surah":6,"verses":[79]}],"verseLabel":"الأنعام: 79","question":"ما سر التعبير بالاسم الموصول ﴿الذي﴾ في وصف الله بأنه فطر السماوات والأرض؟","answer":"وصل اسم الجلالة بصفة الخلق التي يعرفونها، فجعلها علة ظاهرة لاستحقاقه وحده التوجه والعبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص230، تحت عنوان «سر التعبير بالاسم الموصول ﴿الذي﴾»","url":""}]},{"id":"s6-1218","number":1218,"surah":6,"verses":[79],"references":[{"surah":6,"verses":[79]}],"verseLabel":"الأنعام: 79","question":"ما نكتة الكناية في قوله تعالى: ﴿فطر السماوات والأرض﴾؟","answer":"ذكر ابتداء خلق السماوات والأرض كناية عن كمال القدرة والوحدانية؛ فمن خلق الأجرام كلها لا يكون شيء منها ندًا له.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص230، تحت عنوان «نكتة الكناية في قوله: ﴿فطر السماوات والأرض﴾»","url":""}]},{"id":"s6-586","number":586,"surah":6,"verses":[79],"references":[{"surah":6,"verses":[79]}],"verseLabel":"الأنعام: 79","question":"ما سرّ التعبير في قوله تعالى: ﴿حنيفًا﴾، وما الصورة التي تحملها مادة الحنف؟","answer":"الحنف ميل عن الاعوجاج إلى الاستقامة؛ فـ﴿حنيفًا﴾ يصور إبراهيم مائلًا عن الشرك كله، متجهًا بقصد واحد إلى التوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص231–232، تحت «فائدة ذكر الحال ﴿حنيفًا﴾»؛ مع تتمة بيان معنى الحنيف في ص232.","url":""}]},{"id":"s6-587","number":587,"surah":6,"verses":[79],"references":[{"surah":6,"verses":[79]}],"verseLabel":"الأنعام: 79","question":"لماذا جاء ﴿حنيفًا﴾ مفردًا منصوبًا بعد ﴿وجهت وجهي﴾؟","answer":"﴿حنيفًا﴾ حال من فاعل ﴿وجهت﴾، فبين هيئة إبراهيم وقت توجيه وجهه؛ وجاء مفردًا لأنه وصف للمتكلم الواحد، ومنصوبًا لأنه حال.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص231، تحت «فائدة ذكر الحال ﴿حنيفًا﴾».","url":""}]},{"id":"s6-588","number":588,"surah":6,"verses":[79],"references":[{"surah":6,"verses":[79]}],"verseLabel":"الأنعام: 79","question":"لماذا ذكرت البراءة من الشرك بعد توجيه الوجه لله تعالى؟","answer":"لأن إثبات الإخلاص لله يكتمل بنفي عبادة ما سواه، فجمع الكلام بين التوحيد الإيجابي والبراءة من الشرك.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص232، تحت عنوان «دلالة ذكر البراءة من الشرك بعد توجيه الوجه لله تعالى»","url":""}]},{"id":"s6-1219","number":1219,"surah":6,"verses":[79],"references":[{"surah":6,"verses":[79]}],"verseLabel":"الأنعام: 79","question":"ما أثر النفي على جهة الجمع في قوله تعالى: ﴿وما أنا من المشركين﴾؟","answer":"نفى دخوله في جنس المشركين نفيًا ثابتًا مستمرًا، وهو أبلغ من نفي فعل إشراك عارض.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص232، تحت عنوان «نكتة التعبير بالنفي على جهة الجمع في ﴿وما أنا من المشركين﴾»","url":""}]},{"id":"s6-589","number":589,"surah":6,"verses":[80],"references":[{"surah":6,"verses":[80]}],"verseLabel":"الأنعام: 80","question":"ما دلالة اختيار مادة المحاجّة في قوله تعالى: ﴿وحاجه قومه﴾؟","answer":"المحاجة مقابلة الحجة بالحجة، فصورت قومه يخاصمونه بما يعدونه دليلًا ثم يرد عليهم ببرهان يكشف بطلانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص235–236، تحت عنوان «دلالة اختيار مادة المحاجّة»","url":""}]},{"id":"s6-1220","number":1220,"surah":6,"verses":[80],"references":[{"surah":6,"verses":[80]}],"verseLabel":"الأنعام: 80","question":"لماذا أوثر التعبير بالمحاجّة دون المناظرة والمجادلة؟","answer":"لأن المحاجة أصرح في ادعاء كل فريق إقامة الحجة، فناسبت مقام إلزام القوم وإبطال شبهتهم، لا مجرد تبادل النظر أو الكلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص236–237، تحت عنوان «دلالة إيثار التعبير بالمحاجّة دون المناظرة والمجادلة»","url":""}]},{"id":"s6-590","number":590,"surah":6,"verses":[80],"references":[{"surah":6,"verses":[80]}],"verseLabel":"الأنعام: 80","question":"ما سر التعبير بالهداية في قوله تعالى: ﴿وقد هدان﴾ جوابًا عن محاجة القوم؟","answer":"قابل إبراهيم جدلهم النظري بحقيقة هداية وقعت له وأوصلته إلى اليقين، فلا تزعزعها شبهتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص239، تحت عنوان «سر التعبير بالهداية في قوله ﴿هدان﴾»","url":""}]},{"id":"s6-1221","number":1221,"surah":6,"verses":[80],"references":[{"surah":6,"verses":[80]}],"verseLabel":"الأنعام: 80","question":"ما دلالة تقييد المحاجة بالجملة الحالية ﴿وقد هدان﴾؟","answer":"بينت الحال أن محاجتهم وقعت بعد تحقق هدايته وثباتها، فزاد ذلك إنكار جدالهم وقطع طمعهم في رده.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص239–240، تحت عنوان «دلالة التقييد بالجملة الحالية ﴿وقد هدان﴾»","url":""}]},{"id":"s6-591","number":591,"surah":6,"verses":[80],"references":[{"surah":6,"verses":[80]}],"verseLabel":"الأنعام: 80","question":"ما دلالة الظرفية في قوله تعالى: ﴿أتحاجوني في الله﴾؟","answer":"جعلت الله متعلق المحاجة، فشملت ما جادلوا فيه من ربوبيته ووحدانيته واستحقاقه العبادة من غير حصر في جانب واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص238، تحت عنوان «دلالة الظرفية في قوله تعالى: ﴿أتحاجوني في الله﴾»","url":""}]},{"id":"s6-1222","number":1222,"surah":6,"verses":[80],"references":[{"surah":6,"verses":[80]}],"verseLabel":"الأنعام: 80","question":"لماذا اختير اسم الجلالة ﴿الله﴾ دون لفظ الرب في مقام المحاجة؟","answer":"لأن اسم الجلالة جامع لمعاني الألوهية واستحقاق العبادة، وهو محور النزاع مع المشركين، فجاء أصرح في إلزامهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص238–239، تحت عنوان «سر اختيار اسم الجلالة (الله) دون الرب»","url":""}]},{"id":"s6-592","number":592,"surah":6,"verses":[80],"references":[{"surah":6,"verses":[80]}],"verseLabel":"الأنعام: 80","question":"لماذا عبّر بالماضي: ﴿وقد هدان﴾؟","answer":"الماضي مع ﴿قد﴾ يحقق وقوع الهداية وثبوتها؛ فهي نعمة حصلت واستقرت، فلا تزعزعها محاجة قومه ولا تخويفهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص239، تحت عنوان «سر دخول (قد) على الفعل الماضي ﴿هدان﴾»","url":""}]},{"id":"s6-593","number":593,"surah":6,"verses":[80],"references":[{"surah":6,"verses":[80]}],"verseLabel":"الأنعام: 80","question":"ما دلالة اختيار ﴿ما﴾ في قوله تعالى: ﴿ما تشركون به﴾؟","answer":"عم الموصول غير العاقل كل ما جعلوه شريكًا من أصنام وأجرام، وحقرها بعدم تسميتها آلهة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص242، تحت عنوان «دلالة اختيار ﴿ما﴾ في قوله: ﴿ما تشركون﴾»","url":""}]},{"id":"s6-1223","number":1223,"surah":6,"verses":[80],"references":[{"surah":6,"verses":[80]}],"verseLabel":"الأنعام: 80","question":"ما سر التعبير بلفظ الشرك عن عبادة الأصنام؟","answer":"كشف اللفظ حقيقة فعلهم: جعل مخلوق شريكًا لله في العبادة، فحكم على العبادة بالبطلان من أصل وصفها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص242، تحت عنوان «سر التعبير بلفظ الشرك عن عبادتهم للأصنام»","url":""}]},{"id":"s6-594","number":594,"surah":6,"verses":[80],"references":[{"surah":6,"verses":[80]}],"verseLabel":"الأنعام: 80","question":"ما سر الاستدراك بالاستثناء في قوله تعالى: ﴿إلا أن يشاء ربي شيئًا﴾؟","answer":"بعد نفي الخوف من شركائهم استثنى ما يشاؤه الله، فرد القدرة كلها إليه ومنع أن يفهم من النفي استقلال إبراهيم عن مشيئة ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص242، تحت عنوان «سر الاستدراك بالاستثناء»","url":""}]},{"id":"s6-1224","number":1224,"surah":6,"verses":[80],"references":[{"surah":6,"verses":[80]}],"verseLabel":"الأنعام: 80","question":"ما دلالة تعليق المشيئة بالربوبية في قوله تعالى: ﴿إلا أن يشاء ربي شيئًا﴾؟","answer":"إضافة المشيئة إلى الرب تؤكد أن تدبير ما يقع لإبراهيم بيد من يتولاه ويربيه، لا بيد المعبودات الباطلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص243، تحت عنوان «دلالة تعليق المشيئة بالربوبية»","url":""}]},{"id":"s6-595","number":595,"surah":6,"verses":[80],"references":[{"surah":6,"verses":[80]}],"verseLabel":"الأنعام: 80","question":"لماذا نُكّر ﴿شيئًا﴾ بعد مشيئة الرب؟","answer":"نُكر ﴿شيئًا﴾ للعموم؛ أي أي شيء شاءه الله قل أو عظم، فلا يخرج ممكن عن مشيئته، ولا يدل وقوعه على قدرة الشركاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص243، تحت «دلالة تنكير ﴿شيئًا﴾».","url":""}]},{"id":"s6-596","number":596,"surah":6,"verses":[80],"references":[{"surah":6,"verses":[80]}],"verseLabel":"الأنعام: 80","question":"ما سر التعبير بالفعل ﴿وسع﴾ في قوله تعالى: ﴿وسع ربي كل شيء علمًا﴾؟","answer":"دل على شمول علم الله وإحاطته بجميع الأشياء والعوالم من غير أن يخرج عنه معلوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص244، تحت عنوان «سر التعبير بالفعل ﴿وسع﴾»","url":""}]},{"id":"s6-1225","number":1225,"surah":6,"verses":[80],"references":[{"surah":6,"verses":[80]}],"verseLabel":"الأنعام: 80","question":"ما دلالة التمييز ﴿علمًا﴾ في قوله تعالى: ﴿وسع ربي كل شيء علمًا﴾؟","answer":"بيّن جهة السعة وأزال إبهامها، وأصل المعنى: وسع علم ربي كل شيء، فقدم المفعول وأبرز العلم تمييزًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص244–245، تحت عنوان «دلالة التمييز ﴿علمًا﴾»","url":""}]},{"id":"s6-597","number":597,"surah":6,"verses":[80],"references":[{"surah":6,"verses":[80]}],"verseLabel":"الأنعام: 80","question":"ما أثر التذييل بالاستفهام في قوله تعالى: ﴿أفلا تتذكرون﴾؟","answer":"أنكر عليهم استمرار الغفلة بعد وضوح الحجة، وحضهم على مراجعة ما تعرفه فطرهم وعقولهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص245، تحت عنوان «التذييل بالاستفهام ﴿أفلا تتذكرون﴾»","url":""}]},{"id":"s6-1226","number":1226,"surah":6,"verses":[80],"references":[{"surah":6,"verses":[80]}],"verseLabel":"الأنعام: 80","question":"لماذا اختيرت مادة ﴿تتذكرون﴾ دون تتفكرون؟","answer":"لأن بطلان عبادة ما لا يضر ولا ينفع معلوم مركوز في العقول، فهو محتاج إلى إيقاظ وتذكر أكثر من احتياجه إلى إنشاء نظر جديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص245–246، تحت عنوان «دلالة اختيار مادة ﴿تتذكرون﴾»","url":""}]},{"id":"s6-598","number":598,"surah":6,"verses":[80],"references":[{"surah":6,"verses":[80]}],"verseLabel":"الأنعام: 80","question":"ما الفرق بين الحجاج والجدال الذي يعين على فهم قوله تعالى: ﴿وحاجه قومه﴾؟","answer":"المطلوب بالحجاج ظهور الحجة، أما الجدال فالمطلوب به رجوع الخصم عن مذهبه وإلزامه بالحجة، وقد يستعمل في مطلق المخاصمة. فبين اللفظين فرق في الغرض مع اشتراكهما في مراجعة الكلام والحجج.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص279، تحت «الجدال والحجاج»","url":""}]},{"id":"s6-599","number":599,"surah":6,"verses":[81],"references":[{"surah":6,"verses":[81]}],"verseLabel":"الأنعام: 81","question":"ما نكتة الاستفهام بـ﴿كيف﴾ في قوله تعالى: ﴿وكيف أخاف ما أشركتم﴾؟","answer":"خرج الاستفهام إلى التعجب والإنكار من أصل تصور خوفه من معبوداتهم، وهو أبلغ من مجرد نفي الخوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص249، تحت عنوان «نكتة الاستفهام بـ﴿وكيف﴾»","url":""}]},{"id":"s6-1227","number":1227,"surah":6,"verses":[81],"references":[{"surah":6,"verses":[81]}],"verseLabel":"الأنعام: 81","question":"ما دلالة توجيه الاستفهام إلى كيفية الخوف؟","answer":"نفي الكيفية يستلزم نفي الخوف من أصله؛ إذ لا توجد صورة معقولة يخاف بها الموحد ما لا يملك ضرًا ولا نفعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص249–250، تحت عنوان «دلالة توجيه الاستفهام إلى كيفية الخوف»","url":""}]},{"id":"s6-600","number":600,"surah":6,"verses":[81],"references":[{"surah":6,"verses":[81]}],"verseLabel":"الأنعام: 81","question":"ما سرّ التعبير بالماضي في قوله تعالى: ﴿ما أشركتم﴾؟","answer":"يدل الماضي على تمكن الشرك منهم؛ فقد ألفوه حتى صار كأنه جزء من طبيعتهم جُبلوا عليه، فهم ثابتون عليه يدافعون عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص250، تحت «سر التعبير بالفعل الماضي أشركتم»","url":""}]},{"id":"s6-601","number":601,"surah":6,"verses":[81],"references":[{"surah":6,"verses":[81]}],"verseLabel":"الأنعام: 81","question":"ما سرّ التعبير في قوله تعالى: ﴿أشركتم بالله ما لم ينزل به عليكم سلطانًا﴾، فجعل البرهان سلطانًا؟","answer":"السلطان أصله القوة والقهر، وسميت الحجة سلطانًا لأن الحق يقهر الباطل ويتسلط على القلوب والعقول بقوة بيانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص252، تحت «سر التعبير بالسلطان دون الحجة».","url":""}]},{"id":"s6-602","number":602,"surah":6,"verses":[81],"references":[{"surah":6,"verses":[81]}],"verseLabel":"الأنعام: 81","question":"ما سرّ التعبير في قوله تعالى: ﴿لم ينزل به عليكم سلطانًا﴾، مع أن الحجة عقلية لا جسم ينزل؟","answer":"عبر بالإنزال لأن الحجة المعتبرة في أمر العبادة لا تكون إلا بإذن من الله ووحي منه؛ فنفى أن يكون قد نزل عليهم أي مستند يجيز الشرك.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص252، تحت «ذكر المعبودات بـ﴿ما لم ينزل به عليكم سلطانًا﴾»؛ وفيه أن المعوّل عليه في الأمور الدينية هو الحجة المنزلة من الله تعالى.","url":""}]},{"id":"s6-603","number":603,"surah":6,"verses":[81],"references":[{"surah":6,"verses":[81]}],"verseLabel":"الأنعام: 81","question":"ما دلالة وصف المعبودات بأنها مما لم ينزل الله به سلطانًا؟","answer":"بيّن أن شركهم لا أصل له ولا حجة منزلة من الله، وفي الوصف تهكم بمعبودات لا تملك برهانًا على استحقاق العبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص252، تحت عنوان «ذكر المعبودات بما لم ينزل به عليكم سلطانًا»","url":""}]},{"id":"s6-1228","number":1228,"surah":6,"verses":[81],"references":[{"surah":6,"verses":[81]}],"verseLabel":"الأنعام: 81","question":"ما بلاغة الإيجاز في قوله تعالى: ﴿ما لم ينزل به عليكم سلطانًا﴾؟","answer":"جمع التركيب القصير نفي الدليل، وبيان مصدر الحجة الحق، وكشف جرأة المشركين على دعوى لا برهان لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص252–253، تحت عنوان «بلاغة الإيجاز في الآية»","url":""}]},{"id":"s6-604","number":604,"surah":6,"verses":[81],"references":[{"surah":6,"verses":[81]}],"verseLabel":"الأنعام: 81","question":"ما دلالة سوق المعلوم مساق غيره في قوله تعالى: ﴿فأي الفريقين أحق بالأمن﴾؟","answer":"مع أن الموحد أحق بالأمن قطعًا، صيغ الحكم سؤالًا ليحمل الخصم على الإقرار به من نفسه وتقوم عليه الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص253، تحت عنوان «دلالة سوق المعلوم مساق غيره»","url":""}]},{"id":"s6-1229","number":1229,"surah":6,"verses":[81],"references":[{"surah":6,"verses":[81]}],"verseLabel":"الأنعام: 81","question":"ما براعة الإنصاف في قوله تعالى: ﴿فأي الفريقين أحق بالأمن﴾؟","answer":"لم يسم إبراهيم نفسه أحق ابتداء، بل عرض الفريقين للحكم كطالب للإنصاف، فكان ذلك أدعى لإلزام القوم بالجواب الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص253–254، تحت عنوان «براعة الإنصاف في ﴿فأي الفريقين أحق بالأمن﴾»","url":""}]},{"id":"s6-605","number":605,"surah":6,"verses":[81],"references":[{"surah":6,"verses":[81]}],"verseLabel":"الأنعام: 81","question":"ما سرّ التعبير في قوله تعالى: ﴿الفريقين﴾، دون أن يقال: أنا وأنتم؟","answer":"عبر بـ﴿الفريقين﴾ بدل «أنا وأنتم» على طريقة المنصف الذي يعرض القضية كحكم عام، فيستدرج المخالف إلى النظر بعيدًا عن المكابرة الشخصية.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص253–254، تحت «نكتة الإظهار في مقام الإضمار» في قوله: ﴿فأي الفريقين أحق بالأمن﴾.","url":""}]},{"id":"s6-606","number":606,"surah":6,"verses":[81],"references":[{"surah":6,"verses":[81]}],"verseLabel":"الأنعام: 81","question":"ما سرّ التعبير في قوله تعالى: ﴿أحق بالأمن﴾ بصيغة التفضيل؟","answer":"جاء ﴿أحق﴾ بصيغة التفضيل على أسلوب الإنصاف في المحاورة، كأن الأمن مفترض للفريقين ثم يطلب تعيين الأجدر به؛ ليكون إلزام الخصم أبلغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص254، تحت «براعة الإنصاف في ﴿فأي الفريقين أحق بالأمن﴾».","url":""}]},{"id":"s6-607","number":607,"surah":6,"verses":[81],"references":[{"surah":6,"verses":[81]}],"verseLabel":"الأنعام: 81","question":"لماذا قيل ﴿إن كنتم تعلمون﴾ بـ﴿إن﴾ دون إذا؟","answer":"أشعرت ﴿إن﴾ بأن علمهم غير متحقق أو غير راجح؛ فهم بين الجهل بالحق والتجاهل عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص254، تحت عنوان «سر التعبير بـ﴿إن﴾ دون (إذا) في قوله: ﴿إن كنتم تعلمون﴾»","url":""}]},{"id":"s6-1230","number":1230,"surah":6,"verses":[81],"references":[{"surah":6,"verses":[81]}],"verseLabel":"الأنعام: 81","question":"ما دلالة حذف جواب الشرط في قوله تعالى: ﴿إن كنتم تعلمون﴾؟","answer":"قدّر الجواب من المقام: إن كنتم تعلمون فأخبروني؛ فحذفه أوجز وحثهم على النطق بما تلزمهم به الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص254، تحت عنوان «دلالة حذف جواب الشرط»","url":""}]},{"id":"s6-608","number":608,"surah":6,"verses":[82],"references":[{"surah":6,"verses":[82]}],"verseLabel":"الأنعام: 82","question":"لماذا جاء الجواب بصفة عامة: ﴿الذين آمنوا﴾، ولم يقل: إبراهيم ومن اتبعه؟","answer":"جاء الجواب عامًا بـ﴿الذين آمنوا﴾ ليقرر قاعدة لا تختص بإبراهيم: الأمن لكل من جمع الإيمان الخالص وترك خلطه بالظلم. والموصول يبين سبب استحقاقهم الأمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص259، تحت «فائدة التعبير عن أهل الإيمان بالاسم الموصول والصلة» في ﴿الذين آمنوا﴾.","url":""}]},{"id":"s6-609","number":609,"surah":6,"verses":[82],"references":[{"surah":6,"verses":[82]}],"verseLabel":"الأنعام: 82","question":"ما بلاغة الاستعارة في الفعل ﴿يلبسوا﴾ في قوله تعالى: ﴿ولم يلبسوا إيمانهم بظلم﴾؟","answer":"صوّر إدخال الظلم على الإيمان بخلط يغطي صفاءه ويمنع تميزه، كما يلتبس الشيء بغيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص261، تحت عنوان «بلاغة الاستعارة في الفعل ﴿يلبسوا﴾»","url":""}]},{"id":"s6-1231","number":1231,"surah":6,"verses":[82],"references":[{"surah":6,"verses":[82]}],"verseLabel":"الأنعام: 82","question":"ما الفرق بين اللبس والخلط؟","answer":"الخلط جمع أشياء بعضها ببعض، أما اللبس فيزيد معنى الاشتباه والتغطية حتى يصعب التمييز؛ لذلك كان أدق في تصوير أثر الظلم في الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص266، تحت عنوان «(اللبس) و(الخلط)»","url":""}]},{"id":"s6-610","number":610,"surah":6,"verses":[82],"references":[{"surah":6,"verses":[82]}],"verseLabel":"الأنعام: 82","question":"ما نكتة إضافة الإيمان إليهم والتعبير عن الشرك بالظلم؟","answer":"أضاف الإيمان إليهم لتشريف ما تحقق فيهم منه، وسمى الشرك ظلمًا لأنه وضع العبادة في غير موضعها وأعظم الجور على حق الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص261–262، تحت عنوان «نكتة إضافة الإيمان لهم، وإيثار التعبير عن الشرك بالظلم»","url":""}]},{"id":"s6-1232","number":1232,"surah":6,"verses":[82],"references":[{"surah":6,"verses":[82]}],"verseLabel":"الأنعام: 82","question":"ما فائدة تنكير لفظ ﴿بظلم﴾؟","answer":"أفاد التحذير من أدنى قدر من الظلم المقصود، وهو الشرك؛ فإذا انتفى قليله كان نفي كثيره أولى، فخلص الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص262–263، تحت عنوان «فائدة تنكير لفظ ﴿بظلم﴾»","url":""}]},{"id":"s6-611","number":611,"surah":6,"verses":[82],"references":[{"surah":6,"verses":[82]}],"verseLabel":"الأنعام: 82","question":"ما سرّ التعبير في قوله تعالى: ﴿أولئك لهم الأمن﴾ بتقديم ﴿لهم﴾؟","answer":"قُدم ﴿لهم﴾ للاختصاص والعناية؛ فالأمن الحق ثابت لهؤلاء دون من خلط إيمانه بالشرك، وهو جواب مباشر لسؤال: أي الفريقين أحق بالأمن؟","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص263–264، تحت «العدول عن الجواب بـ(أحق بالأمن) إلى ﴿أولئك لهم الأمن﴾».","url":""}]},{"id":"s6-612","number":612,"surah":6,"verses":[82],"references":[{"surah":6,"verses":[82]}],"verseLabel":"الأنعام: 82","question":"لماذا عُرّف ﴿الأمن﴾؟","answer":"عُرّف ﴿الأمن﴾ تعريف الجنس لإثبات جنس الأمن كله لهم بطريق أوكد؛ فيشمل طمأنينة القلب في الدنيا والسلامة من الخوف والعذاب في الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص263–264، تحت «العدول عن الجواب بـ(أحق بالأمن) إلى ﴿أولئك لهم الأمن﴾»، في بيان تعريف ﴿الأمن﴾ للجنس.","url":""}]},{"id":"s6-613","number":613,"surah":6,"verses":[82],"references":[{"surah":6,"verses":[82]}],"verseLabel":"الأنعام: 82","question":"ما سرّ التعبير في قوله تعالى: ﴿وهم مهتدون﴾ بالاسم، دون أن يقال: ويهتدون؟","answer":"الجملة الاسمية تدل على ثبوت اهتدائهم ودوامه، لا على حدوث عابر؛ فمن خلص إيمانه استقر على الهدى ولم يكن اهتداؤه مؤقتًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص264، تحت «نكتة الإخبار بالاسمية في قوله: ﴿وهم مهتدون﴾».","url":""}]},{"id":"s6-614","number":614,"surah":6,"verses":[83],"references":[{"surah":6,"verses":[83]}],"verseLabel":"الأنعام: 83","question":"ما سرّ التعبير في قوله تعالى: ﴿وتلك حجتنا﴾ باسم الإشارة للبعيد؟","answer":"أشير إلى الحجة باسم البعيد تعظيمًا لشأنها ورفعة منزلتها، مع استحضار ما سبق من وجوه البرهان كأنه أمر متميز مشاهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص270، تحت «فائدة اسم الإشارة في قوله: ﴿وتلك حجتنا﴾».","url":""}]},{"id":"s6-615","number":615,"surah":6,"verses":[83],"references":[{"surah":6,"verses":[83]}],"verseLabel":"الأنعام: 83","question":"لماذا أضيفت الحجة إلى الله: ﴿حجتنا﴾، مع أن إبراهيم هو الذي نطق بها؟","answer":"أضيفت الحجة إلى الله لأنها بتعليمه وتوفيقه وإيتائه، وإن جرت على لسان إبراهيم؛ فمصدر نورها وقوتها من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص270، تحت «فائدة التعريف بالإضافة إلى ضمير العظمة في ﴿حجتنا﴾».","url":""}]},{"id":"s6-616","number":616,"surah":6,"verses":[83],"references":[{"surah":6,"verses":[83]}],"verseLabel":"الأنعام: 83","question":"ما دلالة التعبير عن الحجة بالإيتاء في قوله تعالى: ﴿وتلك حجتنا آتيناها إبراهيم﴾؟","answer":"جعل الحجة عطاء من الله، فدل على أنها نعمة موهوبة لإبراهيم بالعلم والبيان، لا ثمرة استقلال بشري.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص270، تحت عنوان «التعبير عن الحجة بالإيتاء»","url":""}]},{"id":"s6-1233","number":1233,"surah":6,"verses":[83],"references":[{"surah":6,"verses":[83]}],"verseLabel":"الأنعام: 83","question":"ما نكتة تقديم المفعول الثاني ﴿حجتنا﴾ على المفعول الأول؟","answer":"قدم الحجة للعناية بها والتنويه بشأنها، ثم ذكر من أوتيها، فصار محور الكلام النعمة التي أقام الله بها البرهان.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص270–271، تحت عنوان «نكتة تقديم المفعول الثاني على المفعول الأول»","url":""}]},{"id":"s6-617","number":617,"surah":6,"verses":[83],"references":[{"surah":6,"verses":[83]}],"verseLabel":"الأنعام: 83","question":"ما سرّ التعبير في قوله تعالى: ﴿على قومه﴾، وما دلالة ﴿على﴾؟","answer":"تفيد ﴿على﴾ الاستعلاء؛ فقد علت حجة إبراهيم حجج قومه وغلبتها، فكانت له منزلة الانتصار بالحجة عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص272، تحت «سر استعمال حرف الاستعلاء في قوله: ﴿على قومه﴾».","url":""}]},{"id":"s6-618","number":618,"surah":6,"verses":[83],"references":[{"surah":6,"verses":[83]}],"verseLabel":"الأنعام: 83","question":"ما بلاغة الاستعارة في التعبير برفع الدرجات؟","answer":"صوّر زيادة المنزلة والفضل بصعود محسوس في درجات عالية، فقرّب رفعة أهل الإيمان والعلم إلى الذهن.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص273، تحت عنوان «بلاغة الاستعارة بالتعبير برفع الدرجات»","url":""}]},{"id":"s6-1234","number":1234,"surah":6,"verses":[83],"references":[{"surah":6,"verses":[83]}],"verseLabel":"الأنعام: 83","question":"ما سر التعبير بالموصول والعدول عن الضمير في قوله تعالى: ﴿من نشاء﴾؟","answer":"عم الموصول كل من تتعلق به المشيئة، فلم يقصر الرفع على إبراهيم وحده، وربط المنزلة باختيار الله وحكمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص273–274، تحت عنوان «سر التعبير بالموصول، والعدول عن الضمير إليه»","url":""}]},{"id":"s6-619","number":619,"surah":6,"verses":[83],"references":[{"surah":6,"verses":[83]}],"verseLabel":"الأنعام: 83","question":"لماذا أوثر لفظ الربوبية في قوله تعالى: ﴿إن ربك حكيم عليم﴾؟","answer":"ناسب مقام رفع الدرجات والهداية؛ فالرب هو المتولي للتربية والإنعام، وفي إضافته إلى النبي عناية وتثبيت.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص276–277، تحت عنوان «إيثار لفظ الربوبية في قوله: ﴿إن ربك حكيم عليم﴾»","url":""}]},{"id":"s6-1235","number":1235,"surah":6,"verses":[83],"references":[{"surah":6,"verses":[83]}],"verseLabel":"الأنعام: 83","question":"كيف ناسبت فاصلة ﴿حكيم عليم﴾ مضمون الآية؟","answer":"رفع الدرجات يجري بحكمة تضع الفضل موضعه، وبعلم بمن يستحقه وبمقادير أحوال العباد، فلا يكون اعتباطًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص277–278، تحت عنوان «مناسبة الفاصلة لمضمون الآية»","url":""}]},{"id":"s6-620","number":620,"surah":6,"verses":[83],"references":[{"surah":6,"verses":[83]}],"verseLabel":"الأنعام: 83","question":"لم قدم ﴿حكيم﴾ على ﴿عليم﴾ في ختام إيتاء الحجة ورفع الدرجات؟","answer":"المقام يبين تفضيل إبراهيم ورفع درجته، وهو مظهر للحكمة في وضع الفضل موضعه، فناسب تقديمها. ثم جاء العلم ليبين أن هذا الإحكام قائم على العلم بمن يليق به ذلك الفضل وبما ينبغي له.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص278، تحت «سر تقديم الحكيم على العليم»","url":""}]},{"id":"s6-621","number":621,"surah":6,"verses":[84],"references":[{"surah":6,"verses":[84]}],"verseLabel":"الأنعام: 84","question":"ما بلاغة الكناية في وصف إيتاء الذرية بأنه هبة؟","answer":"الهبة عطاء بلا عوض، فكنى بها عن محض فضل الله على إبراهيم بإسحاق ويعقوب، ثم كملت النعمة بهدايتهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص282، تحت عنوان «بلاغة الكناية في وصف إيتاء الذرية بأنه هبة»","url":""}]}]);
